import { ISimpleEvent, SimpleEventDispatcher } from "strongly-typed-events";
import { Indexer } from "../utils/types";
import { globals } from "../../scenes/making_game/src/api/globals";

// Finding keyCode: https://www.cambiaresearch.com/articles/15/javascript-char-codes-key-codes
// Using const : src\api\utils\keycode.ts

export const DEBUG: boolean = false;

export type KeyState = {
  justPressed: boolean;
  down: boolean;
};

export type KeyWithName = [
  keycode: number,
  KeyName: string
];

export type KeyInfos = {
  keyName: string,
  keyCode?: number,
  down: boolean,
};

export interface IKeyElement { key: string, element: HTMLElement }

// 1. Start by using addUIItems to fill items
//
// 2. Keeps the state of keys/buttons
//
//  - to check if the left key is currently held down:
//      InputManager.instance.keys.left.down
//
//  - to check if the left key was pressed this frame:
//      InputManager.instance.keys.left.justPressed
//
// 3. TO update the states
//      InputManager.instance.update();
//
// Todo: externalize this
// Keys are defined here as 'left', 'right', 'a', 'b', 'up', 'down'

export class InputManager {

  private static _instance?: InputManager;
  static get instance(): InputManager {
    if (this._instance === undefined) this._instance = new InputManager();
    return this._instance;
  }

  private _onKeyChanged: SimpleEventDispatcher<KeyInfos> = new SimpleEventDispatcher<KeyInfos>();
  public get onKeyChanged(): ISimpleEvent<KeyInfos> {
    return this._onKeyChanged.asEvent();
  }

  private _onKeyPressed: SimpleEventDispatcher<KeyInfos> = new SimpleEventDispatcher<KeyInfos>();
  public get onKeyPressed(): ISimpleEvent<KeyInfos> {
    return this._onKeyPressed.asEvent();
  }

  //<Key, KeyState>
  keys: Indexer<KeyState> = {};

  //<KeyCode, Key>
  private keyMap: Map<number, string> = new Map();

  //Will contain external uiItems
  private _uiItems: IKeyElement[] = [];

  private constructor() {
    //Bind handlers
    this.handleMouseMove = this.handleMouseMove.bind(this);
    this.handleMouseUp = this.handleMouseUp.bind(this);

    this.setKeyFromKeyCode = this.setKeyFromKeyCode.bind(this);

    window.addEventListener("keydown", (e: KeyboardEvent) => {
      this.setKeyFromKeyCode(e.keyCode, true);
    });

    window.addEventListener("keyup", (e: KeyboardEvent) => {
      this.setKeyFromKeyCode(e.keyCode, false);
    });
  }

  addUIItems(keyElements: IKeyElement[]): void {
    keyElements.forEach((v: IKeyElement) => this._uiItems.push(v));
  }

  addKeyWithNames(KeyWithNames: KeyWithName[]): void {
    KeyWithNames.forEach((k: KeyWithName) => this.addKeyInfos(k[0], k[1]));
  }

  private setKey(keyName: string, pressed: boolean, keyCode?: number): void {
    const keyState: KeyState = this.keys[keyName];
    keyState.justPressed = pressed && !keyState.down;
    keyState.down = pressed;

    const keyInfo = {
      down: pressed,
      keyName,
      keyCode
    };
    this._onKeyChanged.dispatch(keyInfo);

    if (pressed) {
      this._onKeyPressed.dispatch(keyInfo);
    }

    DEBUG && console.debug(keyInfo);
  }

  private addKeyInfos(keyCode: number, name: string): void {
    this.keys[name] = { down: false, justPressed: false };
    this.keyMap.set(keyCode, name);
  }

  private setKeyFromKeyCode(keyCode: number, pressed: boolean): void {
    const keyName: string | undefined = this.keyMap.get(keyCode);
    if (!keyName) {
      return;
    }
    this.setKey(keyName, pressed, keyCode);
  }

  private clearKeys(): void {
    for (const { key } of this._uiItems) {
      this.setKey(key, false);
    }
  }

  handleMouseMove(e: MouseEvent): void {
    e.preventDefault();
    // This is needed because we call preventDefault();
    // we also gave the canvas a tabindex so it can
    // become the focus
    globals.canvas.focus();
    window.addEventListener("pointermove", this.handleMouseMove);
    window.addEventListener("pointerup", this.handleMouseUp);

    for (const { element: elem, key } of this._uiItems) {
      let pressed: boolean = false;
      const rect: DOMRect = elem.getBoundingClientRect();
      const x: number = e.clientX;
      const y: number = e.clientY;
      const inRect: boolean =
        x >= rect.left &&
        x < rect.right &&
        y >= rect.top &&
        y < rect.bottom;
      if (inRect) {
        pressed = true;
      }
      this.setKey(key, pressed);
    }
  }

  handleMouseUp(): void {
    this.clearKeys();
    window.removeEventListener("pointermove", this.handleMouseMove, {
      passive: false,
    } as AddEventListenerOptions);
    window.removeEventListener("pointerup", this.handleMouseUp);
  }

  update(): void {
    for (const k in this.keys) {
      const keyState: KeyState = this.keys[k];
      if (keyState && keyState.justPressed) {
        keyState.justPressed = false;
      }
    }
  }
}