/* eslint-disable @typescript-eslint/no-unsafe-member-access */
import { IViewable, View } from './view';
import { IProject } from './project';
import { ILoopable, RenderLoop } from './render_loop';
import * as THREE from "three";
import { AScene } from './a_scene';
import { InputManager } from './input_manager';

export class Engine implements ILoopable, IViewable {
    private readonly view: View;
    private renderLoop: RenderLoop;

    readonly loadingManager: THREE.LoadingManager = new THREE.LoadingManager();

    canFullScreen: boolean = false;

    private _project?: IProject;

    get currentScene(): AScene | undefined {
        return this._project?.currentScene;
    }

    get clock(): THREE.Clock {
        return this.renderLoop.clock;
    }

    get renderer(): THREE.WebGLRenderer {
        return this.view.renderer;
    }

    get aspect(): number {
        return this.view.aspect;
    }

    get canvas(): HTMLCanvasElement {
        return this.view.renderer.domElement;
    }

    constructor(canvas?: HTMLCanvasElement) {
        this.view = new View(this, canvas);
        this.renderLoop = new RenderLoop(this);

        (window as any).engine = this;
    }

    run(project?: IProject): void {
        this._project = project;
        this.renderLoop.run();
    }

    update(): void {
        InputManager.instance.update();
        this._project?.update();
    }

    render(): void {
        this.view.render();
    }

    // Stats

    hideStats(): void {
        this.view.hideStats();
    }

    showStats(): void {
        this.view.showStats();
    }
}
