import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { ParametricGeometry } from 'three/examples/jsm/geometries/ParametricGeometry';
import { AScene } from '../../api/engine/a_scene';
import { GUI } from 'dat.gui';
import { MathUtils } from 'three';

export class ParametricGeometryScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    phongMaterial: THREE.MeshPhongMaterial = new THREE.MeshPhongMaterial({
        color: 0x3F78DB,
        side: THREE.DoubleSide,
        flatShading: true
    });
    standardMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x3F78DB });
    wireMaterial: THREE.MeshBasicMaterial = new THREE.MeshBasicMaterial({ color: 0x639BFA, wireframe: true, wireframeLinewidth: 2 });
    pointMaterial: THREE.PointsMaterial = new THREE.PointsMaterial({
        size: 0.1,
        color: 0xffff00
    });

    geometry: THREE.BufferGeometry = new THREE.BufferGeometry();
    mesh!: THREE.Mesh;

    parametricParameters: {
        slices: number,
        stacks: number,
        a: number,
        n: number,
        m: number,
    } = {
            slices: 100,
            stacks: 100,
            a: 3,
            n: 3,
            m: 1,
        };
    gui: GUI = new GUI();

    constructor() {
        super();
    }

    setup(): void {
        this.setupScene();

        const axesHelper = new THREE.AxesHelper(1);
        this.add(axesHelper);

        this.buildGeometry();
        this.mesh = new THREE.Mesh(this.geometry, this.phongMaterial);
        this.add(this.mesh);

        this.gui = new GUI();

        const parametricFolder: GUI = this.gui.addFolder('Parametric Geometry');
        parametricFolder.add(this.parametricParameters, 'slices', -5, 100).step(1).onChange(() => {
            this.updateGeometry();
        });
        parametricFolder.add(this.parametricParameters, 'stacks', -5, 100).step(1).onChange(() => {
            this.updateGeometry();
        });
        parametricFolder.add(this.parametricParameters, 'a', -5, 5).step(0.05).onChange(() => {
            this.updateGeometry();
        });
        parametricFolder.add(this.parametricParameters, 'n', -5, 5).step(0.05).onChange(() => {
            this.updateGeometry();
        });
        parametricFolder.add(this.parametricParameters, 'm', -60, 60).step(0.01).onChange(() => {
            this.updateGeometry();
        });
        parametricFolder.open();

        this.updateGeometry();
    }

    private setupScene(): void {
        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.x = 1;
        this.perspectiveCamera.position.y = -0.5;
        this.perspectiveCamera.position.z = 5;
        this.perspectiveCamera.lookAt(0);
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
    }

    //>
    buildGeometry(): void {
        this.geometry = new ParametricGeometry(this.parametricFunction.bind(this), this.parametricParameters.slices, this.parametricParameters.stacks);
    }

    updateGeometry(): void {
        this.mesh.geometry.dispose();
        this.buildGeometry();
        this.mesh.geometry = this.geometry;
    }

    parametricFunction(u: number, v: number, target: THREE.Vector3): void {
        const a: number = this.parametricParameters.a;
        const n: number = this.parametricParameters.n;
        const m: number = MathUtils.degToRad(this.parametricParameters.m);
        u = u * 4 * Math.PI;
        v = v * 2 * Math.PI;
        const x = (a + Math.cos(n * u / 2.0)
            * Math.sin(v) - Math.sin(n * u / 2.0)
            * Math.sin(2 * v)) * Math.cos(m * u / 2.0);
        const y = (a + Math.cos(n * u / 2.0)
            * Math.sin(v) - Math.sin(n * u / 2.0)
            * Math.sin(2 * v)) * Math.sin(m * u / 2.0);
        const z = Math.sin(n * u / 2.0)
            * Math.sin(v) + Math.cos(n * u / 2.0)
            * Math.sin(2 * v);
        target.set(x, y, z);
    }

    update(): void {
        //
    }

    dispose(): void {
        this.gui.destroy();
    }
}
