import * as THREE from 'three';
import { UtilsMesh } from '../../../utils/mesh';
import { EditMesh } from '../edit_mesh';
import { EditMeshMode } from "../edit_mesh_mode";
import { MoveMeshTool } from '../meshtool/type/common/move';
import { AEditMeshItem } from "./a_edit_mesh_item";

export class EditMeshEdge extends AEditMeshItem {
    readonly editMeshMode: EditMeshMode = EditMeshMode.edge;

    get canDrag(): boolean {
        return this.editMesh.editMeshMode === this.editMeshMode
            && this.vertexInfos?.length === 2
            && this.currentIntersection?.index !== undefined;
    }

    private edges?: THREE.Line;

    private readonly edgeColor: THREE.ColorRepresentation = 0x639BFA;
    private readonly overEdgeColor: THREE.ColorRepresentation = 0xffff00;
    private readonly selectedEdgeColor: THREE.ColorRepresentation = 0xff0000;

    private edgesMaterial: THREE.LineBasicMaterial = new THREE.LineBasicMaterial({
        color: this.edgeColor,
        vertexColors: true,
    });

    constructor(editMesh: EditMesh) {
        super(editMesh);

        this.currentMeshTool = new MoveMeshTool(this);
        // this.currentMeshTool = new EdgeSplitMeshTool(this);
    }

    enter(): void {
        const edgesGeometry = this.createEdgeGeometry(this.mesh.geometry, this.edgeColor);
        this.edges = new THREE.LineSegments(edgesGeometry, this.edgesMaterial);

        this.edges.layers.enable(1); //meshRayCaster is set to layer 1 by default
        this.mesh.add(this.edges);
    }

    exit(): void {
        if (!this.edges) return;

        this.mesh.remove(this.edges);
        this.edges = undefined;
    }

    overMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this.edges) return;

        this.vertexInfos = [];

        const meshPositions = this.mesh.geometry.attributes.position as THREE.BufferAttribute;
        const edgePositions = this.edges.geometry.attributes.position as THREE.BufferAttribute;

        this.currentIntersection = this.meshRayCaster.selectEdge(normalizedMouseCoordinates, this.edges);

        if (this.currentIntersection && this.currentIntersection.index !== undefined) {

            //Todo find something else with the mesh instead of the edge to use this.setVertexInfos
            // Vertex A
            const vertexAIndex = this.currentIntersection.index;
            const vertexA = new THREE.Vector3().fromArray(edgePositions.array, vertexAIndex * 3);
            const vertexAInfos = UtilsMesh.getEdgeVertexInfos(vertexA, meshPositions);
            this.vertexInfos.push(vertexAInfos);

            // Vertex B
            const vertexBIndex = this.meshRayCaster.getEdgeNearVertexIndex(vertexAIndex);
            const vertexB = new THREE.Vector3().fromArray(edgePositions.array, vertexBIndex * 3);
            const vertexBInfos = UtilsMesh.getEdgeVertexInfos(vertexB, meshPositions);
            this.vertexInfos.push(vertexBInfos);
        }
    }

    selectMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this.edges) return;
        this.currentIntersection = this.meshRayCaster.selectEdge(normalizedMouseCoordinates, this.edges);
    }

    updateGeometry(): void {
        if (!this.edges) return;
        this.edges.geometry = this.createEdgeGeometry(this.mesh.geometry, this.edgeColor);
    }

    private createEdgeGeometry(geometry: THREE.BufferGeometry, edgeColor: THREE.ColorRepresentation): THREE.EdgesGeometry {
        const edgesGeometry = new THREE.EdgesGeometry(geometry, 2);

        const colors = [];
        const color = new THREE.Color(edgeColor);
        for (let i = 0; i < edgesGeometry.attributes.position.count; i++) {
            colors.push(color.r, color.g, color.b);
        }
        edgesGeometry.setAttribute(
            "color",
            new THREE.Float32BufferAttribute(colors, 3)
        );

        return edgesGeometry;
    }
}
