/* eslint-disable @typescript-eslint/no-unsafe-member-access */
import { ArrowHelperScene } from "./experiment/arrow_helper";
import { BaseCubeScene } from "./experiment/base_cube";
import { DynamicLineScene } from "./experiment/dynamic_line";
import { ObjectSelectorScene } from "./experiment/object_selector";
import { EditMeshScene } from "./experiment/edit_mesh";
import { ParametricGeometryScene } from "./experiment/parametric_function";
import { HalfEdgeScene } from "./experiment/half_edge";
import { MeshModifierScene } from "./experiment/mesh_modifier";
import { FlutePlayerScene } from "./making_game/flutePlayer/main";
import { EditorScene } from "./editor/editor";
import { MeshCreatorAndRaycasterScene } from "./experiment/mesh_creator_and_raycaster";
import { InteractiveLinesScene } from "./experiment/interactive_lines";
import { LineStyleScene } from "./experiment/line_style";
import { BaseMathScene } from "./math/base_math";
import { EditMeshEdgeSelectScene } from "./experiment/edit_mesh_edge_select";
import { EditMeshFaceSelectScene } from "./experiment/edit_mesh_face_select";
import { MaterialGroupScene } from "./experiment/material_group";
import { IScene } from "../api/scene/i_scene";
import { DelaunatorScene } from "./experiment/delaunator/delaunator";
import { HalfEdgeProcessingScene } from "./experiment/half_edge_processing";
import { BallShooterScene } from "./vr/ball_shooter";

export enum SceneType {
  Default = "Default",

  //Editor
  Editor = "Editor",

  //Math
  BaseMathScene = "BaseMathScene",
  DelaunatorScene = "DelaunatorScene",

  //Experiment
  BaseCubeScene = "BaseCubeScene",
  EditMeshScene = "EditMeshScene",
  EditMeshEdgeSelectScene = "EditMeshEdgeSelectScene",
  EditMeshFaceSelectScene = "EditMeshFaceSelectScene",
  MaterialGroupScene = "MaterialGroupScene",
  ArrowHelperScene = "ArrowHelperScene",
  DynamicLineScene = "DynamicLineScene",
  ObjectSelectorScene = "ObjectSelectorScene",
  // GeneratorScene = "GeneratorScene",
  LineStyleScene = "LineStyleScene",
  ParametricGeometryScene = "ParametricGeometryScene",
  HalfEdgeScene = "HalfEdgeScene",
  HalfEdgeProcessingScene = "HalfEdgeProcessingScene",
  MeshModifierScene = "MeshModifierScene",
  MeshCreatorAndRaycasterScene = "MeshCreatorAndRaycasterScene",
  InteractiveLinesScene = "InteractiveLinesScene",

  //VR
  BallShooterScene = "BallShooterScene",

  //Games
  FlutePlayerScene = "FlutePlayerScene",
  VoxelPainterScene = "VoxelPainterScene",
}

export class SceneFactory {
  static create(sceneName: string): IScene | undefined {
    let result: IScene | undefined;

    switch (sceneName) {
      //Default
      case SceneType.Default:
        result = new BallShooterScene();
        break;


      //Editor
      case SceneType.Editor:
        result = new EditorScene();
        break;


      //Math
      case SceneType.BaseMathScene:
        result = new BaseMathScene();
        break;
      case SceneType.DelaunatorScene:
        result = new DelaunatorScene();
        break;


      //Experiment
      case SceneType.BaseCubeScene:
        result = new BaseCubeScene();
        break;
      case SceneType.EditMeshScene:
        result = new EditMeshScene();
        break;
      case SceneType.EditMeshEdgeSelectScene:
        result = new EditMeshEdgeSelectScene();
        break;
      case SceneType.EditMeshFaceSelectScene:
        result = new EditMeshFaceSelectScene();
        break;
      case SceneType.MaterialGroupScene:
        result = new MaterialGroupScene();
        break;
      case SceneType.ArrowHelperScene:
        result = new ArrowHelperScene();
        break;
      case SceneType.DynamicLineScene:
        result = new DynamicLineScene();
        break;
      case SceneType.ObjectSelectorScene:
        result = new ObjectSelectorScene();
        break;
      case SceneType.LineStyleScene:
        result = new LineStyleScene();
        break;
      case SceneType.ParametricGeometryScene:
        result = new ParametricGeometryScene();
        break;
      case SceneType.HalfEdgeScene:
        result = new HalfEdgeScene();
        break;
      case SceneType.HalfEdgeProcessingScene:
        result = new HalfEdgeProcessingScene();
        break;
      case SceneType.MeshModifierScene:
        result = new MeshModifierScene();
        break;
      case SceneType.MeshCreatorAndRaycasterScene:
        result = new MeshCreatorAndRaycasterScene();
        break;
      case SceneType.InteractiveLinesScene:
        result = new InteractiveLinesScene();
        break;


      //Game
      case SceneType.FlutePlayerScene:
        result = new FlutePlayerScene();
        break;


      default:
        break;
    }

    (window as any).scene = result;

    return result;
  }
}
