"use strict";

import { Vector } from "../linear-algebra/vector";
import { UtilsVector } from "../utils/vector";


export class PolygonSoup {
    v: Vector[];
    f: number[];

    constructor(
        vertices: Float32Array = new Float32Array(),
        indices: Uint16Array = new Uint16Array()) {

        this.f = Array.from(indices);
        this.v = UtilsVector.vectorsfrom(vertices);
    }
}
