import * as THREE from "three";
import { Component } from "../../src/api/component";
import { GameObject } from "../../src/api/game_object";
import { globals } from "../../src/api/globals";
import { globalsCustom } from "../globals";

export class StateDisplayHelper extends Component {
  elem: HTMLElement;
  pos: THREE.Vector3;
  helper: THREE.PolarGridHelper;

  constructor(gameObject: GameObject, size: number) {
    super(gameObject);
    this.elem = document.createElement("div");
    globalsCustom.ui.labels.element.appendChild(this.elem);
    this.pos = new THREE.Vector3();

    this.helper = new THREE.PolarGridHelper(size / 2, 1, 1, 16);
    gameObject.transform.add(this.helper);
  }

  setState(s: string): void {
    this.elem.textContent = s;
  }

  setColor(cssColor: string): void {
    this.elem.style.color = cssColor;

    (this.helper.material as any).color.set(cssColor);
  }

  update(): void {
    this.helper.visible = globals.debug;
    if (!globals.debug) {
      return;
    }
    const { pos } = this;
    const { transform } = this.gameObject;
    const { canvas } = globals;
    pos.copy(transform.position);

    // get the normalized screen coordinate of that position
    // x and y will be in the -1 to +1 range with x = -1 being
    // on the left and y = -1 being on the bottom
    pos.project(globals.camera);

    // convert the normalized position to CSS coordinates
    const x: number = (pos.x * 0.5 + 0.5) * canvas.clientWidth;
    const y: number = (pos.y * -0.5 + 0.5) * canvas.clientHeight;

    // move the elem to that position
    this.elem.style.transform = `translate(-50%, -50%) translate(${x}px,${y}px)`;
  }
}