import * as THREE from "three";
import { CustomMouseEvent } from "../../../../../engine/mouse_manager";
import { UtilsMesh } from "../../../../../utils/mesh";
import { IEditMeshItem } from "../../../item/i_edit_mesh_item";
import { AMeshTool } from "../../a_mesh_tool";

export class MoveMeshTool extends AMeshTool {
    editMeshItem: IEditMeshItem;

    constructor(editMeshItem: IEditMeshItem) {
        super();
        this.editMeshItem = editMeshItem;
    }

    onMouseMoveHandler(e: CustomMouseEvent): void {
        this.editMeshItem.overMeshItem(e.normalizedMouseCoordinates);
    }

    onMouseDownHandler(e: CustomMouseEvent): void {
        this.editMeshItem.selectMeshItem(e.normalizedMouseCoordinates);
        if (this.editMeshItem.currentIntersection !== undefined) {
            this.editMeshItem.editMesh.onDragMeshElementChangedDispatcher.dispatch(true);
        }
    }

    onMouseDragHandler(e: CustomMouseEvent): void {
        this.moveMeshItem(e.normalizedMouseCoordinates);
    }

    onMouseUpHandler(e: CustomMouseEvent): void {
        e; //not used currently but keep function parameter
        this.editMeshItem.reset();
    }

    //>

    moveMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (this.editMeshItem.mesh && this.editMeshItem.currentIntersection && this.editMeshItem.vertexInfos) {

            const intersectPoint = this.editMeshItem.meshRayCaster.getPlaneIntersection(normalizedMouseCoordinates);
            const baseIntersectPoint = this.editMeshItem.currentIntersection.point;
            const deltaMove = new THREE.Vector3().subVectors(intersectPoint, baseIntersectPoint);

            this.editMeshItem.editMesh.addDebugPoint(intersectPoint);

            if (this.editMeshItem.canDrag) {
                UtilsMesh.moveVertices(this.editMeshItem.mesh, this.editMeshItem.vertexInfos, deltaMove);

                this.editMeshItem.mesh.geometry.attributes.position.needsUpdate = true;
                this.editMeshItem.mesh.geometry.computeVertexNormals();
                this.editMeshItem.mesh.geometry.computeBoundingSphere(); // Needed to have correct intersect detection

                this.editMeshItem.updateGeometry();
            }
        }
    }
}