import { ISimpleEvent, SimpleEventDispatcher } from 'strongly-typed-events';
import * as THREE from 'three';
import { degToRad } from 'three/src/math/MathUtils';
import { CustomMeshCreator } from './custom_mesh_creator';
import { GeometryCreator } from './geometry_creator';
import { BoxGeometryCustomCreator, BoxGeometryParameters, DefaultBoxGeometryParameters } from '../primitives/box';
import { CylinderGeometryCustomCreator, CylinderGeometryParameters, DefaultCylinderGeometryParameters } from '../primitives/cylinder';
import { DefaultPlaneGeometryParameters, PlaneGeometryCustomCreator, PlaneGeometryParameters } from '../primitives/plane';
import { DefaultSphereGeometryParameters, SphereGeometryCustomCreator, SphereGeometryParameters } from '../primitives/sphere';
import { UniqueNameCreator } from './unique_name_creator';

export class MeshCreator {

    private constructor() {
        // Private 
    }

    private static standardMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x3F78DB });

    private static _onMeshCreated: SimpleEventDispatcher<THREE.Mesh> = new SimpleEventDispatcher<THREE.Mesh>();
    public static get onMeshCreated(): ISimpleEvent<THREE.Mesh> {
        return this._onMeshCreated.asEvent();
    }

    static plane(parameters: PlaneGeometryParameters = DefaultPlaneGeometryParameters): THREE.Mesh {
        const mesh = new CustomMeshCreator().create(new PlaneGeometryCustomCreator(parameters));
        mesh.material = this.standardMaterial;
        mesh.name = UniqueNameCreator.createUniqueNameFor("Plane");
        mesh.layers.enable(1);
        mesh.rotateX(degToRad(-90));
        mesh.receiveShadow = true;
        this._onMeshCreated.dispatch(mesh);
        return mesh;
    }

    static box(parameters: BoxGeometryParameters = DefaultBoxGeometryParameters): THREE.Mesh {
        const mesh = new CustomMeshCreator().create(new BoxGeometryCustomCreator(parameters));
        mesh.material = this.standardMaterial;
        mesh.name = UniqueNameCreator.createUniqueNameFor("Box");
        mesh.layers.enable(1);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        this._onMeshCreated.dispatch(mesh);
        return mesh;
    }

    static sphere(parameters: SphereGeometryParameters = DefaultSphereGeometryParameters): THREE.Mesh {
        const mesh = new CustomMeshCreator().create(new SphereGeometryCustomCreator(parameters));
        mesh.material = this.standardMaterial;
        mesh.name = UniqueNameCreator.createUniqueNameFor("Sphere");
        mesh.layers.enable(1);
        mesh.rotateX(degToRad(-90));
        mesh.receiveShadow = true;
        this._onMeshCreated.dispatch(mesh);
        return mesh;
    }

    static cylinder(parameters: CylinderGeometryParameters = DefaultCylinderGeometryParameters): THREE.Mesh {
        const mesh = new CustomMeshCreator().create(new CylinderGeometryCustomCreator(parameters));
        mesh.material = this.standardMaterial;
        mesh.name = UniqueNameCreator.createUniqueNameFor("Cylinder");
        mesh.layers.enable(1);
        mesh.receiveShadow = true;
        this._onMeshCreated.dispatch(mesh);
        return mesh;
    }

    static customIndexed(): THREE.Mesh {
        const geometry: THREE.BufferGeometry = GeometryCreator.customIndexed();
        const material: THREE.MeshStandardMaterial = this.standardMaterial;
        const mesh: THREE.Mesh = new THREE.Mesh(geometry, material);
        mesh.name = UniqueNameCreator.createUniqueNameFor("Custom");
        mesh.layers.enable(1);
        mesh.receiveShadow = true;
        this._onMeshCreated.dispatch(mesh);
        return mesh;
    }
}

