import { GUI } from 'dat.gui';
import { KeyWithName, InputManager, KeyInfos } from '../../engine/input_manager';
import { KeyCode } from '../../utils/keycode';
import { EditMesh } from './edit_mesh';
import { EditMeshMode } from "./edit_mesh_mode";

export class EditMeshGUI {
    private gui: GUI;
    private folder?: GUI;
    private editMesh?: EditMesh;
    private removeAfter: boolean = false;

    constructor(gui: GUI) {
        this.gui = gui;

        this.bindKeyboard();
    }

    private bindKeyboard(): void {
        const KeyWithNames: KeyWithName[] = [
            [KeyCode.SPACE, "editMode"],
        ];
        InputManager.instance.addKeyWithNames(KeyWithNames);

        InputManager.instance.onKeyPressed.subscribe((k: KeyInfos) => {
            switch (k.keyName) {
                case "editMode":
                    this.toggle();
                    break;
            }
        });
    }

    init(editMesh: EditMesh, removeAfter: boolean = false): void {
        this.editMesh = editMesh;
        this.removeAfter = removeAfter;

        this.folder = this.gui.addFolder('Edit Mesh');
        this.folder.add(this, this.enterVertexMode.name).name("Enter Edit Vertex");
        this.folder.add(this, this.enterEdgeMode.name).name("Enter Edit Edge");
        this.folder.add(this, this.enterFaceMode.name).name("Enter Edit Face");
        this.folder.add(this, this.exit.name).name("Exit Edit Mesh");
        this.folder.open();
    }

    private enterVertexMode(): void {
        this.enter(EditMeshMode.vertex);
    }

    private enterEdgeMode(): void {
        this.enter(EditMeshMode.edge);
    }

    private enterFaceMode(): void {
        this.enter(EditMeshMode.face);
    }

    private enter(editMeshMode: EditMeshMode = EditMeshMode.vertex): void {
        if (this.folder && this.editMesh && this.gui.__folders[this.folder.name]) {
            this.editMesh?.enter(editMeshMode);
        }
    }

    private exit(): void {
        this.clear();

        if (this.folder && this.editMesh) {
            this.editMesh.exit();
        }
    }

    toggle(): void {
        if (this.editMesh) {
            this.editMesh.toggle();
        }
    }

    clear(): void {
        if (this.folder && this.editMesh) {
            if (this.removeAfter) {
                if (this.gui.__folders[this.folder.name]) {
                    this.gui.removeFolder(this.folder);
                }
            }
        }
    }
}
