import {
  Button,
  Drawer, DrawerBody, DrawerContent, DrawerHeader, DrawerOverlay, SlideDirection, useDisclosure
} from "@chakra-ui/react";
import * as React from "react";
import { useState } from "react";
import { useDispatch } from "react-redux";
import { UseStateType } from "../api/utils/chakra";
import { SceneType } from "../scenes/scene_factory";
import { RootDispatcher } from "../store/root_reducer";

export const BaseDrawer: React.FC = (): React.ReactElement => {
  const { isOpen, onOpen, onClose } = useDisclosure();
  const [placement]: UseStateType<string> = useState<string>('top');
  const [sceneName, setSceneName]: UseStateType<SceneType> = useState<SceneType>(SceneType.Default);

  const dispatch = useDispatch();
  const rootDispatcher = new RootDispatcher(dispatch);
  
  let onChangeSceneHandler = (sceneName: SceneType): void => {
    setSceneName(sceneName);
    rootDispatcher.updateSceneName(sceneName);
    onClose();
  };

  onChangeSceneHandler = onChangeSceneHandler.bind(this);

  const renderItems = (): React.ReactNode[] => {
    const result: React.ReactNode[] = [];
    const sceneTypes = Object.values(SceneType);
    for(const sceneType of sceneTypes){

      const handler = (): void => {
        onChangeSceneHandler(sceneType);
      };

      result.push((<p key={sceneType} onClick={handler}>{sceneType}</p>));
    }
    return result;
  };

  return (
    <div style={{position: "absolute"}}>
      <Button colorScheme='blue' onClick={onOpen}>
        Open
      </Button>
      <Drawer placement={placement as SlideDirection} onClose={onClose} isOpen={isOpen}>
        <DrawerOverlay />
        <DrawerContent>
          <DrawerHeader borderBottomWidth='1px'>Select Scene</DrawerHeader>
          <DrawerBody>
            {renderItems()}
          </DrawerBody>
        </DrawerContent>
      </Drawer>
      
      <span>&nbsp;&nbsp;Scene name : {sceneName}</span>
    </div>
  );
};
