import * as THREE from "three";
import { MeshModifier } from "../mesh_modifier";
import { GuiParameters, GUIParamsItemType } from "../../../utils/gui";
import { Modifier } from "../modifier";

export const getDefaultTaperGUIParameters = (modifier: Taper): GuiParameters => {
    const result: GuiParameters = {
        name: 'Taper',
        target: modifier.parameters,
        controllers: [
            {
                key: 'amount',
                type: GUIParamsItemType.number,
                min: -1,
                max: 1,
                step: 0.01
            },
        ],
    };

    return result;
};

export interface TaperParameters {
    amount: number;
}

export class Taper extends Modifier {
    parameters: TaperParameters = {
        amount: 0,
    };

    constructor(editableMesh: MeshModifier) {
        super(editableMesh);
    }

    update(): void {
        if (this.baseObject.mesh) {
            this.resultGeometry = this.build(this.baseObject.mesh.geometry);
        }
    }

    private build(geometry: THREE.BufferGeometry): THREE.BufferGeometry {

        const { amount } = this.parameters;

        const geometrySize = new THREE.Vector3();
        geometry.computeBoundingBox();
        geometry.boundingBox?.getSize(geometrySize);

        const positions = geometry.attributes.position as THREE.BufferAttribute;
        const vertex = new THREE.Vector3();

        for (let i = 0; i < positions.count; i++) {
            vertex.fromBufferAttribute(positions, i);

            const yFactor = vertex.y;

            vertex.x = vertex.x * (1 + (amount * yFactor));
            vertex.z = vertex.z * (1 + (amount * yFactor));

            geometry.attributes.position.setXYZ(i, vertex.x, vertex.y, vertex.z);
        }

        geometry.computeVertexNormals();
        geometry.attributes.position.needsUpdate = true;

        return geometry;
    }
}