import * as THREE from 'three';
import Stats from 'three/examples/jsm/libs/stats.module';
import { AScene } from './a_scene';

export interface IViewable {
    get canFullScreen(): boolean;
    get currentScene(): AScene | undefined;
}

export class View {
    readonly engine: IViewable;
    readonly canvas!: HTMLCanvasElement;
    readonly sizes: {
        width: number;
        height: number;
    };

    renderer: THREE.WebGLRenderer;

    get aspect(): number {
        return this.sizes.width / this.sizes.height;
    }

    stats: Stats;
    get isStatsVisible(): boolean {
        return this.stats.dom.style.display === "block";
    }

    constructor(engine: IViewable, canvas?: HTMLCanvasElement) {
        this.engine = engine;

        this.stats = Stats();
        document.body.appendChild(this.stats.dom);
        this.hideStats();

        this.sizes = {
            width: window.innerWidth,
            height: window.innerHeight
        };

        this.renderer = new THREE.WebGLRenderer({
            antialias: true,
            canvas: canvas,
        });

        this.renderer.setSize(this.sizes.width, this.sizes.height);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

        window.addEventListener('resize', this.resize.bind(this));
        window.addEventListener('dblclick', this.fullscreen.bind(this));
    }

    render(): void {
        if (this.engine.currentScene) {
            this.renderer.render(this.engine.currentScene, this.engine.currentScene.mainCamera);
        }

        if (this.isStatsVisible) {
            this.stats.update();
        }
    }

    resize(): void {
        // Update sizes
        this.sizes.width = window.innerWidth;
        this.sizes.height = window.innerHeight;

        // Update renderer
        this.renderer.setSize(this.sizes.width, this.sizes.height);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

        if (!this.engine.currentScene) return;

        const mainCamera: THREE.Camera = this.engine.currentScene.mainCamera;
        if (mainCamera instanceof THREE.PerspectiveCamera) {
            mainCamera.aspect = this.aspect;
            mainCamera.updateProjectionMatrix();
        } else {
            //ortho camera
        }
    }

    fullscreen(): void {
        if (!this.engine.canFullScreen) return;

        const fullscreenElement: Element | null = document.fullscreenElement;

        if (!fullscreenElement) {
            if (this.renderer.domElement.requestFullscreen) {
                void this.renderer.domElement.requestFullscreen();
            }
        }
        else {
            if (document.exitFullscreen) {
                void document.exitFullscreen();
            }
        }
    }

    // Stats

    hideStats(): void {
        this.stats.dom.style.display = 'none';
    }

    showStats(): void {
        this.stats.dom.style.display = 'block';
    }
}
