import { ISimpleEvent, SimpleEventDispatcher } from 'strongly-typed-events';
import * as THREE from 'three';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js';
import { degToRad } from 'three/src/math/MathUtils';
import { KeyCode } from '../utils/keycode';
import { UtilsObject3D } from '../utils/object3d';
import { InputManager, KeyInfos, KeyWithName } from './input_manager';
import { AScene } from './a_scene';

const DEBUG: boolean = false;

export enum TransformMode {
    translate = 'translate',
    rotate = 'rotate',
    scale = 'scale',
}

export enum TransformSpace {
    local = 'local',
    world = 'world',
}

export class ObjectSelector {
    private scene: AScene;

    private _onSelectionChanged: SimpleEventDispatcher<THREE.Object3D | undefined> = new SimpleEventDispatcher<THREE.Object3D | undefined>();
    public get onSelectionChanged(): ISimpleEvent<THREE.Object3D<THREE.Event> | undefined> {
        return this._onSelectionChanged.asEvent();
    }

    transformControls!: TransformControls;
    pointer: THREE.Vector2 = new THREE.Vector2();
    objectRaycaster: THREE.Raycaster = new THREE.Raycaster();
    intersects: THREE.Object3D[] = [];

    private isMouseDown: boolean = false;
    private shouldDeselect: boolean = false;
    private isDragging: boolean = false;

    private _selection: THREE.Object3D | undefined;
    public get selection(): THREE.Object3D | undefined {
        return this._selection;
    }

    private _enabled: boolean = true;
    public get enabled(): boolean {
        return this._enabled;
    }
    public set enabled(value: boolean) {
        this._enabled = value;
        this.transformControls.enabled = value;
        this.transformControls.visible = value;
    }

    constructor(scene: AScene) {
        this.scene = scene;

        this.objectRaycaster.layers.set(1);

        // TransformControls
        this.transformControls = new TransformControls(this.scene.mainCamera, this.scene.engine.renderer.domElement);
        this.transformControls.translationSnap = 0;
        this.transformControls.rotationSnap = degToRad(0);
        this.transformControls.visible = false;
        if (DEBUG) {
            this.transformControls.addEventListener("objectChange", () => {
                console.debug("dragging", this.transformControls.dragging);
                console.debug("axis", this.transformControls.axis);
            });
        }
        this.transformControls.addEventListener("mouseDown", () => {
            this.scene.controls!.enabled = false;
        });
        this.transformControls.addEventListener("mouseUp", () => {
            this.scene.controls!.enabled = true;
        });
        this.scene.add(this.transformControls);

        this.scene.engine.canvas.addEventListener('pointerdown', this.onPointerDown.bind(this));
        this.scene.engine.canvas.addEventListener('pointermove', this.onPointerMove.bind(this));
        this.scene.engine.canvas.addEventListener('pointerup', this.onPointerUp.bind(this));

        this.bindKeyboard();
    }

    private bindKeyboard(): void {
        const KeyWithNames: KeyWithName[] = [
            [KeyCode.DELETE, "delete"],
            [KeyCode.T, TransformMode.translate],
            [KeyCode.R, TransformMode.rotate],
            [KeyCode.S, TransformMode.scale],
            [KeyCode.L, TransformSpace.local],
            [KeyCode.W, TransformSpace.world],
        ];

        InputManager.instance.addKeyWithNames(KeyWithNames);
        InputManager.instance.onKeyChanged.subscribe((k: KeyInfos) => {
            switch (k.keyName) {
                case "delete":
                    this.deleteSelection();
                    break;
                case TransformMode.rotate:
                    this.transformControls.setMode(TransformMode.rotate);
                    break;
                case TransformMode.scale:
                    this.transformControls.setMode(TransformMode.scale);
                    break;
                case TransformMode.translate:
                    this.transformControls.setMode(TransformMode.translate);
                    break;
                case TransformSpace.local:
                    this.transformControls.setSpace(TransformSpace.local);
                    break;
                case TransformSpace.world:
                    this.transformControls.setSpace(TransformSpace.world);
                    break;

            }
        });
    }

    onPointerDown(event: PointerEvent): void {
        this.isMouseDown = true;
        this.isDragging = false;
        if (!this.enabled || this.transformControls.dragging)
            return;

        if (event.button === 0) {
            if (this.intersects[0]) {
                const object3D: THREE.Object3D = this.intersects[0];
                this.select(object3D);
            } else {
                this.shouldDeselect = true;
                // this.deselect();
            }
        }
    }

    onPointerMove(event: PointerEvent): void {
        this.isDragging = true;
        if (!this.isMouseDown && this.shouldDeselect) {
            this.deselect();
            this.shouldDeselect = false;
        }

        if (this.transformControls.dragging) { return; }

        // calculate pointer position in normalized device coordinates
        // (-1 to +1) for both components
        this.pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
        this.pointer.y = -(event.clientY / window.innerHeight) * 2 + 1;

        // update the picking ray with the camera and pointer position
        this.objectRaycaster.setFromCamera(this.pointer, this.scene.mainCamera);

        // calculate objects intersecting the picking ray
        const intersects: THREE.Intersection[] = this.objectRaycaster.intersectObjects(this.scene.children, true);
        /*
            An intersection has the following properties :
                - object : intersected object (THREE.Mesh)
                - distance : distance from camera to intersection (number)
                - face : intersected face (THREE.Face3)
                - faceIndex : intersected face index (number)
                - point : intersection point (THREE.Vector3)
                - uv : intersection point in the object's UV coordinates (THREE.Vector2)
        */
        this.intersects = [];
        for (let i: number = 0; i < intersects.length; i++) {
            const item: THREE.Object3D = intersects[i].object;
            if (item.layers.isEnabled(1)) {
                this.intersects.push(item);
            }
        }

        if (DEBUG) {
            console.debug(this.intersects.map((m: THREE.Object3D) => m.name.length > 0 ? `${m.name}(${m.layers.mask})` : m.type));
        }
    }

    onPointerUp(): void {
        if (this.isMouseDown && this.shouldDeselect && !this.isDragging) {
            this.deselect();
        }
        this.shouldDeselect = false;
        this.isMouseDown = false;
        this.isDragging = false;
    }

    deselect(): void {
        if (this.selection !== undefined) {
            this._selection = undefined;
            this._onSelectionChanged.dispatch(this._selection);
            this.transformControls.detach();
            this.transformControls.visible = false;
        }
    }

    select(object3D: THREE.Object3D): void {
        if (this._selection !== object3D) {
            this._selection = object3D;
            this._onSelectionChanged.dispatch(this._selection);
            this.transformControls.attach(this._selection);
            this.transformControls.visible = true;
        }
    }

    deleteSelection(): void {
        const selection = this.selection;
        this.deselect();
        UtilsObject3D.deleteObject3D(selection);
    }
}
