
import * as THREE from "three";
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from "../../../api/engine/a_scene";
import { CustomMouseEvent, MouseManager } from "../../../api/engine/mouse_manager";
import { MeshRayCaster } from "../../../api/mesh/mesh_ray_caster";
import { Point } from "../../../api/mesh/primitives/point";
import { DelaunayHelper } from "./delaunay_helper";
import { Delaunator, Point as DPoint } from "./lib/delaunator";

// https://mapbox.github.io/delaunator/ >>
// https://github.sre.pub/mapbox/delaunator

export class DelaunatorScene extends AScene {

  delaunay!: Delaunator;

  updated!: boolean;

  points!: DPoint[];

  minX!: number;
  minY!: number;
  maxX!: number;
  maxY!: number;

  perspectiveCamera!: THREE.PerspectiveCamera;

  geometry: THREE.BufferGeometry = new THREE.BufferGeometry();
  wireMaterial: THREE.MeshBasicMaterial = new THREE.MeshBasicMaterial({ color: 0x639BFA, wireframe: true, wireframeLinewidth: 2 });
  edgesMaterial: THREE.LineBasicMaterial = new THREE.LineBasicMaterial({
    color: 0x639BFA,
    vertexColors: true,
  });

  mesh: THREE.Mesh = new THREE.Mesh(this.geometry, this.wireMaterial);
  edges: THREE.LineSegments = new THREE.LineSegments(this.geometry, this.edgesMaterial);
  vertices: THREE.Group = new THREE.Group();

  meshRayCaster!: MeshRayCaster;

  constructor() {
    super();
  }

  setup(): void {

    this.setupScene();

    this.points = [
      [0, 0],
      [1, 0],
      [0, 1],
      [1, 1],
    ];

    this.setupRaycaster();
    this.setupDelaunay();

    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    (window as any).delaunay = this.delaunay;
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    (window as any).delaHelper = new DelaunayHelper();
  }

  setupRaycaster(): void {
    this.meshRayCaster = new MeshRayCaster(() => this.mainCamera);
    this.add(this.meshRayCaster.helper);
  }

  setupDelaunay(): void {

    console.time('delaunay');
    this.delaunay = Delaunator.from(this.points);
    console.timeEnd('delaunay');

    //Bouding box
    this.minX = Infinity;
    this.minY = Infinity;
    this.maxX = -Infinity;
    this.maxY = -Infinity;
    for (let i = 0; i < this.points.length; i++) {
      const x = this.points[i][0];
      const y = this.points[i][1];
      if (x < this.minX) this.minX = x;
      if (y < this.minY) this.minY = y;
      if (x > this.maxX) this.maxX = x;
      if (y > this.maxY) this.maxY = y;
    }

    this.updated = true;

    MouseManager.instance.mouseDown.subscribe(this.onMouseDown.bind(this));

    this.add(this.mesh);
    this.add(this.vertices);

    this.update();
  }

  private setupScene(): void {
    this.background = new THREE.Color(0xffffff);

    // Base camera
    this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.001, 1000);
    this.perspectiveCamera.position.x = 0;
    this.perspectiveCamera.position.y = 2;
    this.perspectiveCamera.position.z = 0;
    this.perspectiveCamera.lookAt(0, 0, 0);
    this.add(this.perspectiveCamera);

    this.mainCamera = this.perspectiveCamera;

    //Light
    const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
    this.add(ambientLight);

    const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
    directionalLight.position.set(2, 5, 3);
    this.add(directionalLight);

    // Controls
    this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
    this.controls.target.set(0, 0, 0);
    this.controls.enableDamping = false;
    this.controls.autoRotate = false;
  }

  onMouseDown(e: CustomMouseEvent): void {
    if (e.event.button === 0) {

      const intersection = this.meshRayCaster.getPlaneIntersection(e.normalizedMouseCoordinates);
      const x = intersection.x;
      const y = intersection.z;
      this.addPoint(x, y);
    }
  }

  addPoint(x: number, y: number): void {
    this.points.push([x, y]);
    console.time('delaunay');
    this.delaunay = Delaunator.from(this.points);
    console.timeEnd('delaunay');
    this.updated = true;
  }

  getX(i: number): number {
    return this.points[i][0] - this.minX;
  }
  getY(i: number): number {
    return this.points[i][1] - this.minY;
  }

  draw(): void {
    if (!this.updated) return;
    this.updated = false;

    this.vertices.children.length = 0;

    this.drawTriangles(this.delaunay.triangles);
    // this.drawHull(this.delaunay.hull);
    this.drawPoints(this.points);
  }

  drawPoints(points: DPoint[]): void {
    for (let i = 0; i < points.length; i++) {
      const point = new Point({ color: 0x000000 });
      point.position.copy(new THREE.Vector3(this.getX(i), 0, this.getY(i)));
      this.vertices.add(point);
    }
  }

  // drawHull(hull: Uint32Array): void {
  //   this.ctx.beginPath();
  //   for (const i of hull) {
  //     this.ctx.lineTo(this.getX(i), this.getY(i));
  //   }
  //   this.ctx.closePath();
  //   this.ctx.lineWidth = 1;
  //   this.ctx.strokeStyle = 'red';
  //   this.ctx.stroke();
  // }

  drawTriangles(triangles: Uint32Array): void {
    this.mesh.geometry.dispose();

    const geometry = new THREE.BufferGeometry();
    const triangle = new THREE.BufferAttribute(new Float32Array(triangles.length * 3), 3);
    geometry.setAttribute("position", triangle);

    for (let i = 0; i < triangles.length; i += 3) {
      const p0 = triangles[i];
      const p1 = triangles[i + 1];
      const p2 = triangles[i + 2];
      triangle.setXYZ(i, this.getX(p0), 0, this.getY(p0));
      triangle.setXYZ(i + 1, this.getX(p1), 0, this.getY(p1));
      triangle.setXYZ(i + 2, this.getX(p2), 0, this.getY(p2));
    }

    this.mesh.geometry = geometry;
  }

  update(): void {
    if (this.updated) {
      this.draw();
    }
  }

}
