import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { GUI } from 'dat.gui';
import { Twist } from '../../api/mesh/modifiers/types/twist';
import { Sinusoid } from '../../api/mesh/modifiers/types/sinusoid';
import { Bend } from '../../api/mesh/modifiers/types/bend';
import { Axis } from "../../api/utils/axis";
import { MathUtils } from 'three';
import { Taper } from '../../api/mesh/modifiers/types/taper';
import { MeshModifier } from '../../api/mesh/modifiers/mesh_modifier';
import { AScene } from '../../api/engine/a_scene';
import { BoxGeometryParameters, DefaultBoxGeometryParameters } from '../../api/mesh/primitives/box';

//From: https://medium.com/@crazypixel/geometry-manipulation-in-three-js-twisting-c53782c38bb

export class MeshModifierScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    gui: GUI = new GUI();

    //Mesh Modifier
    editableMesh!: MeshModifier;
    standardMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x3F78DB });
    wireMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x639BFA, wireframe: true, wireframeLinewidth: 2 });
    mesh!: THREE.Mesh;
    geometry!: THREE.BufferGeometry;
    public data: BoxGeometryParameters = DefaultBoxGeometryParameters;

    twistModifier!: Twist;
    sinusoidModifier!: Sinusoid;
    bendModifier!: Bend;
    taperModifier!: Taper;

    constructor() {
        super();
    }

    setup(): void {

        this.background = new THREE.Color(0x151F30);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.set(2, 2, 2);
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        // Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
        this.controls.target.set(0, 1, 0);
        this.controls.update();

        this.createGeometry();
        this.createUI();
    }

    createUI(): void {

        //GUI

        const geometryFolder: GUI = this.gui.addFolder('Geometry');
        geometryFolder.add(this.data, 'heightSegments', 1, 120).step(1).onChange(() => {
            this.updateGeometry();
        });
        geometryFolder.add(this.data, 'widthSegments', 1, 120).step(1).onChange(() => {
            this.updateGeometry();
        });
        geometryFolder.add(this.data, 'depthSegments', 1, 120).step(1).onChange(() => {
            this.updateGeometry();
        });
        geometryFolder.add(this.data, 'wireframe').onChange(() => {
            this.updateGeometry();
        });
        geometryFolder.open();

        const twistFolder: GUI = this.gui.addFolder('Twist');
        twistFolder.add(this.twistModifier.parameters, 'amount', -360, 360).step(1).onChange(() => {
            this.editableMesh.update();
        });
        twistFolder.open();

        const taperFolder: GUI = this.gui.addFolder('Taper');
        taperFolder.add(this.taperModifier.parameters, 'amount', -1, 1).step(0.01).onChange(() => {
            this.editableMesh.update();
        });
        taperFolder.open();

        const SinusoidFolder: GUI = this.gui.addFolder('Sinusoid');
        SinusoidFolder.add(this.sinusoidModifier.parameters, 'amplitude', -2, 2).step(0.001).onChange(() => {
            this.updateGeometry();
        });
        SinusoidFolder.add(this.sinusoidModifier.parameters, 'frequency', 0, 10).step(0.1).onChange(() => {
            this.updateGeometry();
        });
        SinusoidFolder.add(this.sinusoidModifier.parameters, 'phase', MathUtils.degToRad(-360), MathUtils.degToRad(360)).step(0.1).onChange(() => {
            this.updateGeometry();
        });
        SinusoidFolder.open();

        const bendFolder: GUI = this.gui.addFolder('Bend');
        bendFolder.add(this.bendModifier.parameters, 'axis', Object.values(Axis)).onChange(() => {
            this.updateGeometry();
        });
        bendFolder.add(this.bendModifier.parameters, 'angle', MathUtils.degToRad(-180), MathUtils.degToRad(180)).step(0.01).onChange(() => {
            this.updateGeometry();
        });
        bendFolder.open();
    }

    private createGeometry(): void {

        const axesHelper = new THREE.AxesHelper(5);
        this.add(axesHelper);

        this.geometry = this.createBaseGeometry();
        this.mesh = new THREE.Mesh(this.geometry);
        this.mesh.material = this.data.wireframe ? this.wireMaterial : this.standardMaterial;

        this.editableMesh = new MeshModifier();
        this.editableMesh.init(this.mesh);
        this.twistModifier = this.editableMesh.addModifier(Twist);
        this.taperModifier = this.editableMesh.addModifier(Taper);
        this.sinusoidModifier = this.editableMesh.addModifier(Sinusoid);
        this.bendModifier = this.editableMesh.addModifier(Bend);

        this.add(this.mesh);
    }

    createBaseGeometry(): THREE.BufferGeometry {
        const height = 2;
        const geometry = new THREE.BoxGeometry(1, height, 1, this.data.depthSegments, this.data.heightSegments, this.data.widthSegments);
        geometry.translate(0, height / 2, 0);

        return geometry;
    }

    updateGeometry(): void {
        this.geometry = this.createBaseGeometry();
        this.mesh.material = this.data.wireframe ? this.wireMaterial : this.standardMaterial;
        this.mesh.geometry.dispose();
        this.mesh.geometry = this.geometry;

        this.editableMesh.update();// don't forget to update editable mesh !
    }

    update(): void {
        //
    }

    dispose(): void {
        this.gui.destroy();
    }
}
