import * as THREE from "three";
import { Engine } from "./engine";
import { AScene, DefaultScene } from "./a_scene";

export interface IUpdatable {
    update(): void;
}

export interface IProject {
    get engine(): Engine;

    get currentScene(): AScene;
    set currentScene(scene: AScene);

    get loadingManager(): THREE.LoadingManager;

    update(): void;
    run(): void;
    dispose(): void;
}

export abstract class AProject implements IProject {
    private _engine: Engine;
    get engine(): Engine {
        return this._engine;
    }

    public get canvas(): HTMLCanvasElement {
        return this.engine.canvas;
    }

    private _currentScene: AScene = new DefaultScene();
    get currentScene(): AScene {
        return this._currentScene;
    }
    set currentScene(scene: AScene) {
        this._currentScene = scene;
    }

    get mainCamera(): THREE.Camera {
        return this.currentScene?.mainCamera;
    }

    get loadingManager(): THREE.LoadingManager {
        return this._engine.loadingManager;
    }

    constructor(canvas?: HTMLCanvasElement) {
        this._engine = new Engine(canvas);
    }

    update(): void {
        if (this.currentScene) {
            if (!this.currentScene.hasInit) {
                this.currentScene.initialize(this.engine);
                this.currentScene.setup();
            }
            this.currentScene.update();
        }
    }

    run(): void {
        this.engine.run(this);
    }

    dispose(): void {
        console.debug("AProject::dispose not implemented");
    }
}


export class DefaultProject extends AProject {
    constructor(canvas?: HTMLCanvasElement) {
        super(canvas);
    }
}