import { globals } from "./globals";

// function* waitFrames(numFrames) {
//   while (numFrames > 0) {
//     --numFrames;
//     yield;
//   }
// }

export function* waitSeconds(duration: number): Generator<undefined, void, unknown> {
  while (duration > 0) {
    duration -= globals.deltaTime;
    yield;
  }
}

export class CoroutineRunner {
  generatorStacks: any[][] = [];
  addQueue: any[][] = [];
  removeQueue: Set<any> = new Set();

  constructor() {
    //
  }

  isBusy(): boolean {
    return this.addQueue.length + this.generatorStacks.length > 0;
  }

  add(generator: any, delay: number = 0): void {
    const genStack: any[] = [generator];
    if (delay) {
      genStack.push(waitSeconds(delay));
    }
    this.addQueue.push(genStack);
  }

  remove(generator: any): void {
    this.removeQueue.add(generator);
  }

  update(): void {
    this._addQueued();
    this._removeQueued();
    for (const genStack of this.generatorStacks) {
      const main: any = genStack[0];
      // Handle if one coroutine removes another
      if (this.removeQueue.has(main)) {
        continue;
      }
      while (genStack.length) {
        const topGen: any = genStack[genStack.length - 1];
        const { value, done } = topGen.next();
        if (done) {
          if (genStack.length === 1) {
            this.removeQueue.add(topGen);
            break;
          }
          genStack.pop();
        } else if (value) {
          genStack.push(value);
        } else {
          break;
        }
      }
    }
    this._removeQueued();
  }

  private _addQueued(): void {
    if (this.addQueue.length) {
      this.generatorStacks.splice(
        this.generatorStacks.length,
        0,
        ...this.addQueue
      );
      this.addQueue = [];
    }
  }

  private _removeQueued(): void {
    if (this.removeQueue.size) {
      this.generatorStacks = this.generatorStacks.filter(
        (genStack: any[]) => !this.removeQueue.has(genStack[0])
      );
      this.removeQueue.clear();
    }
  }
}