import * as THREE from "three";
import { MeshModifier } from "../mesh_modifier";
import { Modifier } from "../modifier";
import { Axis } from "../../../utils/axis";
import { MathUtils } from "three";
import { GuiParameters, GUIParamsItemType } from "../../../utils/gui";

export const getDefaultBendGUIParameters = (modifier: Bend): GuiParameters => {
    const result: GuiParameters = {
        name: 'Bend',
        target: modifier.parameters,
        controllers: [
            {
                key: 'axis',
                type: GUIParamsItemType.stringList,
                itemsString: Object.values(Axis),
            },
            {
                key: 'angle',
                type: GUIParamsItemType.number,
                min: MathUtils.degToRad(-180),
                max: MathUtils.degToRad(180),
                step: 0.01
            },
        ],
    };

    return result;
};

export interface BendParameters {
    axis: Axis,
    angle: number,
}

export class Bend extends Modifier {
    parameters: BendParameters = {
        axis: Axis.x,
        angle: 0,
    };

    constructor(editableMesh: MeshModifier) {
        super(editableMesh);
    }

    update(): void {
        if (this.baseObject.mesh) {
            this.resultGeometry = this.build(this.baseObject.mesh.geometry);
        }
    }

    private build(geometry: THREE.BufferGeometry): THREE.BufferGeometry {

        const { axis, angle } = this.parameters;

        let theta = 0;
        if (angle !== 0) {
            const v = geometry.attributes.position
                .array as number[];
            for (let i = 0; i < v.length; i += 3) {
                const x = v[i];
                const y = v[i + 1];
                const z = v[i + 2];

                switch (axis) {
                    case Axis.x:
                        theta = z * angle;
                        break;
                    case Axis.y:
                        theta = x * angle;
                        break;
                    default:
                        //z
                        theta = x * angle;
                        break;
                }

                const sinTheta = Math.sin(theta);
                const cosTheta = Math.cos(theta);

                switch (axis) {
                    case Axis.x:
                        v[i] = x;
                        v[i + 1] = (y - 1.0 / angle) * cosTheta + 1.0 / angle;
                        v[i + 2] = -(y - 1.0 / angle) * sinTheta;
                        break;
                    case Axis.y:
                        v[i] = -(z - 1.0 / angle) * sinTheta;
                        v[i + 1] = y;
                        v[i + 2] = (z - 1.0 / angle) * cosTheta + 1.0 / angle;
                        break;
                    default:
                        //z
                        v[i] = -(y - 1.0 / angle) * sinTheta;
                        v[i + 1] = (y - 1.0 / angle) * cosTheta + 1.0 / angle;
                        v[i + 2] = z;
                        break;
                }
            }

            geometry.computeVertexNormals();
            geometry.attributes.position.needsUpdate = true;
        }

        return geometry;
    }
}