import * as THREE from 'three';
import { CustomMouseEvent } from '../../../engine/mouse_manager';
import { VertexInfo } from '../../../utils/mesh';
import { MeshRayCaster } from '../../mesh_ray_caster';
import { EditMesh } from '../edit_mesh';
import { EditMeshMode } from "../edit_mesh_mode";
import { IMeshTool } from '../meshtool/i_mesh_tool';
import { IEditMeshItem } from "./i_edit_mesh_item";

export abstract class AEditMeshItem implements IEditMeshItem {
    readonly editMesh: EditMesh;
    readonly mesh: THREE.Mesh;
    readonly meshRayCaster: MeshRayCaster;

    protected _currentMeshTool!: IMeshTool;
    get currentMeshTool(): IMeshTool {
        if (!this._currentMeshTool)
            throw new Error("currentMeshTool must be set before use.");

        return this._currentMeshTool;
    }
    set currentMeshTool(value: IMeshTool) {
        this._currentMeshTool = value;
    }

    public vertexInfos?: VertexInfo[];
    currentIntersection?: THREE.Intersection;

    abstract readonly editMeshMode: EditMeshMode;

    abstract get canDrag(): boolean;

    constructor(editMesh: EditMesh) {
        this.editMesh = editMesh;
        if (!editMesh.mesh)
            throw new Error(`Editmesh mesh must be set before`);
        this.mesh = editMesh.mesh;
        this.meshRayCaster = editMesh.meshRayCaster;
    }

    protected setVertexInfos(vertexIndex: number): void {
        if (!this.vertexInfos || !this.mesh)
            return;
        const meshPositions = this.mesh.geometry.attributes.position as THREE.BufferAttribute;
        const vertexPosition: THREE.Vector3 = new THREE.Vector3().fromArray(meshPositions.array, vertexIndex * 3);
        const vertexInfo = { index: vertexIndex, position: vertexPosition };
        this.vertexInfos.push(vertexInfo);
    }

    abstract enter(): void;
    abstract exit(): void;

    onMouseMoveHandler(e: CustomMouseEvent): void {
        this.currentMeshTool.onMouseMoveHandler(e);
    }

    onMouseDownHandler(e: CustomMouseEvent): void {
        this.currentMeshTool.onMouseDownHandler(e);
    }

    onMouseDragHandler(e: CustomMouseEvent): void {
        this.currentMeshTool.onMouseDragHandler(e);
    }

    onMouseUpHandler(e: CustomMouseEvent): void {
        this.currentMeshTool.onMouseUpHandler(e);
    }

    abstract overMeshItem(normalizedMouseCoordinates: THREE.Vector2): void;
    abstract selectMeshItem(normalizedMouseCoordinates: THREE.Vector2): void;

    abstract updateGeometry(): void;

    reset(): void {
        this.currentIntersection = undefined;
        this.vertexInfos = undefined;
        this.editMesh.onDragMeshElementChangedDispatcher.dispatch(false);
    }
}
