import { UtilsHtml } from '../../../../api/utils/html';

export class ProgressBar {

    get element(): HTMLElement {
        return this.loading;
    }

    private readonly loading: HTMLElement;
    private readonly progressBar: HTMLElement;

    constructor() {
        const xmlString: string = `
        <div id="loading">
            <div>
                <div>...loading...</div>
                <div class="progress">
                    <div id="progressbar"></div>
                </div>
            </div>
        </div>
        `;
        const doc: Document = new DOMParser().parseFromString(xmlString, "text/xml");

        const loading: HTMLDivElement = doc.getElementById("loading") as HTMLDivElement;
        this.loading = UtilsHtml.convertHtmlFromParser(loading) as HTMLDivElement;

        const progressBar: HTMLDivElement = doc.getElementById("progressbar") as HTMLDivElement;
        this.progressBar = UtilsHtml.convertHtmlFromParser(progressBar) as HTMLDivElement;

    }

    setValue(url: string, loaded: number, total: number): void {
        const value: number = ((loaded / total) * 100) | 0;
        this.progressBar.style.width = `${value}%`;
        console.log("Progress: ", url, value);
    }

    show(): void {
        this.loading.style.display = 'block';
    }

    hide(): void {
        this.loading.style.display = 'none';
    }
}
