import { Triangle, Vector3 } from 'three';
import { VertexNode } from './vertex_node';
import { HalfEdge } from './half_edge';

const _triangle = new Triangle();

export enum VisibilityType {
    visible,
    deleted
}

// https://threejs.org/docs/#examples/en/math/convexhull/Face

// Represents a section bounded by a specific amount of half-edges. The current implementation assumes that a face always consist of three edges.
export class Face {
    normal: Vector3;
    midpoint: Vector3;
    area: number;
    constant: number; // signed distance from face to the origin
    outside: VertexNode | null; // reference to a vertex in a vertex list this face can see
    mark: VisibilityType;
    edge: HalfEdge | null; // main half edge reference

    constructor() {
        this.normal = new Vector3();
        this.midpoint = new Vector3();
        this.area = 0;
        this.constant = 0;

        this.outside = null;

        this.mark = VisibilityType.visible;
        this.edge = null;
    }

    static create(a: VertexNode, b: VertexNode, c: VertexNode): Face | null {
        const face: Face = new Face();

        const e0: HalfEdge = new HalfEdge(a, face);
        const e1: HalfEdge = new HalfEdge(b, face);
        const e2: HalfEdge = new HalfEdge(c, face);

        // join edges
        e0.next = e2.prev = e1;
        e1.next = e0.prev = e2;
        e2.next = e1.prev = e0;

        // main half edge reference
        face.edge = e0;
        a.face = face;

        return face.compute();
    }

    getEdge(i: number): HalfEdge | null {
        if (this.edge === null) return null;

        let edge: HalfEdge | null = this.edge;

        while (i > 0 && edge !== null) {
            edge = edge.next;
            i--;
        }

        while (i < 0 && edge !== null) {
            edge = edge.prev;
            i++;
        }

        return edge;
    }

    getVertexNodes(): VertexNode[] {
        const vertexNodes = new Array<VertexNode>();

        const edge0: HalfEdge | null = this.getEdge(0);

        if (edge0) {
            const head = edge0.head();
            const nextHead = edge0.next?.head();
            const nextNext = edge0.next?.next;
            const nextNextHead = nextNext && nextNext.head();

            head && vertexNodes.push(head);
            nextHead && vertexNodes.push(nextHead);
            nextNextHead && vertexNodes.push(nextNextHead);
        }

        return vertexNodes;
    }

    compute(): Face | null {
        const a = this.edge?.tail();
        const b = this.edge?.head();
        const c = this.edge?.next?.head();

        if (!(a && b && c)) return null;

        _triangle.set(a.point, b.point, c.point);

        _triangle.getNormal(this.normal);
        _triangle.getMidpoint(this.midpoint);
        this.area = _triangle.getArea();

        this.constant = this.normal.dot(this.midpoint);

        return this;
    }

    distanceToPoint(point: Vector3): number {
        return this.normal.dot(point) - this.constant;
    }
}
