import { ICustomCreator } from "../creators/custom_mesh_creator";
import { GeometryCreator } from "../creators/geometry_creator";
import { GuiParameters, GUIParamsItemType } from "../../utils/gui";
import { GeometryParameters } from "./primitives";

export const DefaultSphereGeometryParameters = {
    radius: 1,
    widthSegments: 32,
    heightSegments: 16,
    phiStart: 0,
    phiLength: Math.PI * 2,
    thetaStart: 0,
    thetaLength: Math.PI
};

export interface SphereGeometryParameters extends GeometryParameters {
    radius?: number,
    widthSegments?: number,
    heightSegments?: number,
    phiStart?: number,
    phiLength?: number,
    thetaStart?: number,
    thetaLength?: number,
}

export const getSphereGeometryGUIParameters = (parameters: SphereGeometryParameters): GuiParameters => {
    const result: GuiParameters = {
        name: 'Sphere',
        target: parameters,
        controllers: [
            {
                key: 'radius',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            },  {
                key: 'widthSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },{
                key: 'heightSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },{
                key: 'phiStart',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },{
                key: 'phiLength',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },{
                key: 'thetaStart',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },{
                key: 'thetaLength',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },
        ],
    };

    return result;
};

export class SphereGeometryCustomCreator implements ICustomCreator {
    geometryParameters: SphereGeometryParameters ;
    geometryGUIParameters: GuiParameters;

    constructor(parameters: SphereGeometryParameters = DefaultSphereGeometryParameters){
        this.geometryParameters = { ...parameters };
        this.geometryGUIParameters = getSphereGeometryGUIParameters(this.geometryParameters); 
    }

    geometryCreator(parameters: SphereGeometryParameters): THREE.BufferGeometry {
        const geometry = GeometryCreator.sphere(parameters);
        return geometry;
    }
}
