import '../../../styles/style.css';
import * as THREE from 'three';
import { GUI } from 'dat.gui';
import { Animal } from './components/animal';
import { GameObjectManager } from '../src/api/game_object_manager';
import { UtilsMath } from '../../../api/utils/math';
import { CameraInfo } from '../src/components/camera_info';
import { globalsCustom } from './globals';
import { Player } from './components/player';
import { Labels } from './ui/labels';
import { ProgressBar } from './ui/progress_bar';
import { UIControls } from './ui/ui_controls';
import { IKeyElement, InputManager, KeyWithName } from '../../../api/engine/input_manager';
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { globals } from '../src/api/globals';
import { GameObject } from '../src/api/game_object';
import { GLTFModel, UtilsGLTF } from '../../../api/utils/gltf';
import { Indexer } from '../../../api/utils/types';
import { Geo } from '../src/components/geo';
import { UtilsPositionner } from '../../../api/mesh/creators/positionner';
import { UtilsString } from '../../../api/utils/string';
import { AScene } from '../../../api/engine/a_scene';

export class FlutePlayerScene extends AScene {

    uiControls!: UIControls;
    progressBar!: ProgressBar;
    labels!: Labels;
    gui: GUI = new GUI();

    constructor() {
        super();
    }

    setup(): void {

        // Renderer
        this.setupRenderer();

        // Environment
        this.setupEnvironment();

        const fov: number = 45;
        const aspect: number = 2; // the canvas default
        const near: number = 0.1;
        const far: number = 1000;
        const camera: THREE.PerspectiveCamera = new THREE.PerspectiveCamera(fov, aspect, near, far);
        camera.position.set(0, 40, 80);
        this.mainCamera = camera;

        const controls: OrbitControls = new OrbitControls(this.mainCamera, this.engine.canvas);
        controls.target.set(0, 5, 0);
        controls.update();

        this.addLight(new THREE.Vector3(5, 5, 2));
        this.addLight(new THREE.Vector3(-5, 5, 5));

        this.setupGlobals();
        this.setupUI();

        this.engine.loadingManager.onProgress = this.progressBar.setValue.bind(this.progressBar);
        this.engine.loadingManager.onLoad = this.init.bind(this); //> when loaded

        UtilsGLTF.loadModels(this.engine.loadingManager, Object.values(globalsCustom.models));

        this.showHideDebugInfo();
    }

    setupEnvironment(): void {
        this.background = new THREE.Color(0xffffff);
    }

    setupRenderer(): void {
        this.engine.renderer.outputEncoding = THREE.sRGBEncoding;
    }

    setupGlobals(): void {
        //Globals
        globals.scene = this;
        globals.camera = this.mainCamera;
        globals.canvas = this.engine.canvas;
        globals.time = this.engine.clock.getElapsedTime();
        globals.deltaTime = this.engine.clock.getDelta();
        globals.debug = false;

        //Custom
        globalsCustom.models = {
            pig: { url: "/assets/making_game/flutePlayer/animals/Pig.gltf" },
            cow: { url: "/assets/making_game/flutePlayer/animals/Cow.gltf" },
            llama: { url: "/assets/making_game/flutePlayer/animals/Llama.gltf" },
            pug: { url: "/assets/making_game/flutePlayer/animals/Pug.gltf" },
            sheep: { url: "/assets/making_game/flutePlayer/animals/Sheep.gltf" },
            zebra: { url: "/assets/making_game/flutePlayer/animals/Zebra.gltf" },
            horse: { url: "/assets/making_game/flutePlayer/animals/Horse.gltf" },
            knight: { url: "/assets/making_game/flutePlayer/knight/KnightCharacter.gltf" },
        };
        globalsCustom.player = null;
        globalsCustom.playerRadius = 1;
        globalsCustom.congaLine = [];
        globalsCustom.moveSpeed = 16;
    }

    setupUI(): void {
        // Hud
        this.uiControls = new UIControls();
        document.body.appendChild(this.uiControls.element);

        this.progressBar = new ProgressBar();
        document.body.appendChild(this.progressBar.element);

        this.labels = new Labels();
        document.body.appendChild(this.progressBar.element);

        globalsCustom.ui.labels = this.labels;

        //Init InputManager
        {
            //> Keyboard

            const KeyWithNames: KeyWithName[] = [
                [37, "left"],
                [39, "right"],
                [38, "up"],
                [40, "down"],
                [90, "a"],
                [88, "b"],
            ];

            InputManager.instance.addKeyWithNames(KeyWithNames);

            //> UI

            const keyElements: IKeyElement[] = [
                { key: "left", element: document.querySelector("#left") as HTMLElement },
                { key: "right", element: document.querySelector("#right") as HTMLElement },
            ];

            // note: not a good design?
            // The last direction the user presses should take
            // precedence. Example: User presses L, without letting go of
            // L user presses R. Input should now be R. User lets off R
            // Input should now be L.
            // With this code if user pressed both L and R result is nothing

            const uiElem: HTMLElement = document.querySelector("#ui") as HTMLElement;

            uiElem.addEventListener("pointerdown", InputManager.instance.handleMouseMove, {
                passive: false,
            });

            uiElem.addEventListener(
                "touchstart",
                (e: TouchEvent) => {
                    // prevent scrolling
                    e.preventDefault();
                },
                { passive: false }
            );

            InputManager.instance.addUIItems(keyElements);
        }

        // GUI
        this.gui.add(globals, "debug").onChange(this.showHideDebugInfo.bind(this));
        this.gui.close();
    }

    showHideDebugInfo(): void {
        this.labels.setVisibility(globals.debug);
    }

    addLight(pos: THREE.Vector3): void {
        const light: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        light.position.set(pos.x, pos.y, pos.z);
        this.add(light);
        this.add(light.target);
    }

    init(): void {
        this.progressBar.hide();

        this.createGameCamera();
        this.createGameModels();
    }

    createGameCamera(): void {
        //Create camera gameObject
        const gameObject: GameObject = GameObjectManager.instance.createGameObject(this.mainCamera, "camera");
        globalsCustom.cameraInfo = gameObject.addComponent(CameraInfo);
    }

    createGameModels(): void {
        this.prepareModelsAndAnimations(Object.values(globalsCustom.models));

        //Create player gameObject
        const gameObject: GameObject = GameObjectManager.instance.createGameObject(this, "player");
        globalsCustom.player = gameObject.addComponent(Player);
        globalsCustom.congaLine = [gameObject];

        //Create animals gameObject
        UtilsPositionner.createSpiral(this.createRandomAnimal.bind(this));
    }

    createRandomModel(): THREE.Vector3 {
        const name: string = UtilsString.makeRandomStringId();
        const gameObject: GameObject = GameObjectManager.instance.createGameObject(this, name);
        gameObject.addComponent(Geo);
        const position: THREE.Vector3 = gameObject.transform.position;
        return position;
    }

    createRandomAnimal(): THREE.Vector3 {
        //Animals
        const modelNames: string[] = [
            "pig",
            "cow",
            "llama",
            "pug",
            "sheep",
            "zebra",
            "horse",
        ];

        const name: string = modelNames[UtilsMath.rand(modelNames.length) | 0];
        const gameObject: GameObject = GameObjectManager.instance.createGameObject(this, name);
        gameObject.addComponent(Animal, globalsCustom.models[name]);
        const position: THREE.Vector3 = gameObject.transform.position;
        return position;
    }

    prepareModelsAndAnimations(models: GLTFModel[]): void {
        const box: THREE.Box3 = new THREE.Box3();
        const size: THREE.Vector3 = new THREE.Vector3();

        models.forEach((model: GLTFModel) => {
            if (!model.gltf) return;

            box.setFromObject(model.gltf.scene);
            box.getSize(size);
            model.size = size.length();
            const animsByName: Indexer<THREE.AnimationClip> = {};
            model.gltf.animations.forEach((clip: THREE.AnimationClip) => {
                animsByName[clip.name] = clip;
                // Should be fixed this in .blend file
                if (clip.name === "Walk") {
                    clip.duration /= 2;
                }
            });
            model.animations = animsByName;
        });
    }

    then: number = 0;
    update(): void {
        // convert to seconds
        globals.time = this.engine.clock.getElapsedTime();
        // make sure delta time isn't too big.
        globals.deltaTime = Math.min(globals.time - this.then, 1 / 20);
        this.then = globals.time;

        GameObjectManager.instance.update();
        InputManager.instance.update();
    }

    dispose(): void {
        this.gui.destroy();
    }
}
