import * as THREE from "three";
import { Point } from "../../api/mesh/primitives/point";

export class LineHelper extends THREE.Object3D {
    private p1: THREE.Vector3;
    private p2: THREE.Vector3;
    pt1: Point;
    pt2: Point;
    line!: THREE.Line<THREE.BufferGeometry, THREE.LineDashedMaterial>;
    material!: THREE.LineDashedMaterial;

    private validColor: THREE.ColorRepresentation = 0xffffff;
    private invalidColor: THREE.ColorRepresentation = 0xff0000;

    constructor(p1: THREE.Vector3, p2: THREE.Vector3, isConstruction: boolean = false, color?: THREE.ColorRepresentation) {
        super();

        this.p1 = p1;
        this.p2 = p2;

        this.pt1 = new Point({ size: 0.18 });
        this.pt1.position.copy(this.p1);

        this.pt2 = new Point({ size: 0.18 });
        this.pt2.position.copy(this.p2);

        const line = this.buildLine(this.p1, this.p2, isConstruction, color);

        this.add(this.pt1).add(this.pt2).add(line);
    }

    private buildLine(p1: THREE.Vector3, p2: THREE.Vector3, dashed: boolean = false, color?: THREE.ColorRepresentation): THREE.Line {

        const geometry = new THREE.BufferGeometry().setFromPoints([p1, p2]);

        this.material = new THREE.LineDashedMaterial({
            color: color ? color : dashed ? 0xcccccc : 0x0000000,
            linewidth: 1,
            scale: 1,          //Globale scale dashes
            dashSize: 0.05,    //Dash line size
            gapSize: 0.05,     //Dash gap size
        });
        this.line = new THREE.Line(geometry, this.material);
        dashed && this.line.computeLineDistances(); //Needed to compute dashes
        return this.line;
    }

    setPoints(p1: THREE.Vector3, p2: THREE.Vector3): void {
        this.p1 = p1;
        this.p2 = p2;
        this.updateLineGeometry();
    }

    setPoint1(p1: THREE.Vector3): void {
        this.p1 = p1;
        this.updateLineGeometry();
    }

    setPoint2(p2: THREE.Vector3): void {
        this.p2 = p2;
        this.updateLineGeometry();
    }

    setValid(): void {
        this.material.color.set(this.validColor);
    }

    setInvalid(): void {
        this.material.color.set(this.invalidColor);
    }

    private updateLineGeometry(): void {
        this.pt1.position.copy(this.p1);
        this.pt2.position.copy(this.p2);

        const geometry = new THREE.BufferGeometry().setFromPoints([this.p1, this.p2]);
        this.line.geometry.dispose();
        this.line.geometry = geometry;
    }
}