import { ICustomCreator } from "../creators/custom_mesh_creator";
import { GeometryCreator } from "../creators/geometry_creator";
import { GuiParameters, GUIParamsItemType } from "../../utils/gui";
import { GeometryParameters } from "./primitives";

export const DefaultPlaneGeometryParameters = {
    width: 1,
    height: 1,
    widthSegments: 1,
    heightSegments: 1,
};

export interface PlaneGeometryParameters extends GeometryParameters {
    width: number,
    height: number,
    widthSegments: number,
    heightSegments: number,
}

export const getPlaneGeometryGUIParameters = (parameters: PlaneGeometryParameters): GuiParameters => {
    const result: GuiParameters = {
        name: 'Plane',
        target: parameters,
        controllers: [
            {
                key: 'width',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'height',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'heightSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'widthSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },
        ],
    };

    return result;
};

export class PlaneGeometryCustomCreator implements ICustomCreator {
    geometryParameters: PlaneGeometryParameters;
    geometryGUIParameters: GuiParameters;

    constructor(parameters: PlaneGeometryParameters = DefaultPlaneGeometryParameters) {
        this.geometryParameters = { ...parameters };
        this.geometryGUIParameters = getPlaneGeometryGUIParameters(this.geometryParameters);
    }

    geometryCreator(parameters: PlaneGeometryParameters): THREE.BufferGeometry {
        const geometry = GeometryCreator.plane(parameters);
        return geometry;
    }
}