import { useEffect, useRef } from "react";
import { useSelector } from "react-redux";
import { AProject, DefaultProject } from "../api/engine/project";
import { AScene } from "../api/engine/a_scene";
import { SceneFactory, SceneType } from "../scenes/scene_factory";
import { InitialState } from "../store/root_reducer";
import { ABaseScene } from "../api/scene/a_base_scene";
import { IScene } from "../api/scene/i_scene";
import { UtilsHtml } from "../api/utils/html";

interface StateProps {
  sceneName: SceneType;
}

let project: AProject | undefined;
const loadProject = (container: HTMLDivElement | null, sceneName: SceneType): void |(() =>void) =>{
  if (!container) { return; }

  let canvas: HTMLCanvasElement | undefined ;
  const scene: IScene | undefined = SceneFactory.create(sceneName);

  if (scene && scene instanceof AScene) {
    if(!project){
      project = new DefaultProject();
      project.run();
    }
    
    project.currentScene.dispose();
    project.currentScene = scene;

    canvas = project.canvas;

  } else if (scene && scene instanceof ABaseScene){
    scene.container = container;
    scene.setup();
    scene.update();

    canvas = scene.canvas;

  } else {
    canvas = document.createElement('canvas');
  }

  UtilsHtml.removeAllChildren(container);
  container.appendChild(canvas);

  return (): void => {
    UtilsHtml.removeAllChildren(container);
    project?.dispose();
  };
};

export const SceneComponent: React.FC = (): React.ReactElement => {

  const divContainerRef = useRef<HTMLDivElement>(null);

  const {sceneName} = useSelector<InitialState, StateProps>((state: InitialState) => {
    return {
      sceneName: state.sceneName,
    };
  });

  useEffect(() => {
    const { current: container } = divContainerRef;
    loadProject(container, sceneName);
  }, [sceneName]);

  return (
    <>
      <div id="Container" ref={divContainerRef}>
      </div>
    </>
  );
};
  