import * as THREE from "three";
import { MeshModifier } from "../modifiers/mesh_modifier";
import { MeshData } from "../mesh_data";
import { GuiParameters, TargetParameters } from "../../utils/gui";

export interface ICustomCreator {
    geometryParameters: TargetParameters;
    geometryGUIParameters: GuiParameters;
    geometryCreator(parameters: TargetParameters): THREE.BufferGeometry
}

export class CustomMeshCreator {

    private standardMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x3F78DB });
    private wireMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x639BFA, wireframe: true, wireframeLinewidth: 2 });

    private _mesh!: THREE.Mesh;

    public meshModifier: MeshModifier = new MeshModifier();

    constructor() {
        //
    }

    create(customCreator: ICustomCreator): THREE.Mesh {
        //Create mesh
        this._mesh = new THREE.Mesh();
        this._mesh.geometry = customCreator.geometryCreator(customCreator.geometryParameters);
        this._mesh.material = this.standardMaterial;
        this._mesh.layers.enable(1);

        //MeshData
        const meshData = MeshData.get(this._mesh);

        meshData.geometryParameters = customCreator.geometryParameters;
        meshData.geometryGuiParameters = customCreator.geometryGUIParameters;
        meshData.geometryCreator = customCreator.geometryCreator.bind(this);
        meshData.geometryUpdater = this.update.bind(this);
        meshData.modifierUpdater = this.update.bind(this);

        return this._mesh;
    }

    private update(): void {
        this.updateGeometry();
        this.updateModifiers();
    }

    private updateGeometry(): void {
        const meshData = MeshData.get(this._mesh);

        if (meshData.geometryCreator && meshData.geometryParameters) {
            const geometry = meshData.geometryCreator(meshData.geometryParameters);
            this._mesh.geometry.dispose();
            this._mesh.geometry = meshData.geometryCreator(meshData.geometryParameters);
            // this._mesh.material = this.parameters.wireframe ? this.wireMaterial : this.standardMaterial; //>>>>>>>>>>
            MeshData.get(this._mesh).originalGeometry = geometry;
        }
    }

    private updateModifiers(): void {
        this.meshModifier.init(this._mesh);
        this.meshModifier.update();
    }
}
