import * as THREE from 'three';
import { AScene } from '../engine/a_scene';
import { CustomMouseEvent, MouseManager } from '../engine/mouse_manager';

export class HitTester {
    raycaster: THREE.Raycaster = new THREE.Raycaster();
    pointer: THREE.Vector2 = new THREE.Vector2();
    intersects!: THREE.Intersection[];
    private scene: AScene;

    private hitMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({
        color: 0x3F78DB,
        opacity: 0.5,
        transparent: true,
    });

    private tempMaterial!: THREE.Material | THREE.Material[];

    constructor(scene: AScene) {
        this.scene = scene;
        this.raycaster.layers.set(1);
        MouseManager.instance.mouseMove.subscribe(this.onMouseMoveHandler.bind(this));
    }

    onMouseMoveHandler(e: CustomMouseEvent): void {
        // update the picking ray with the camera and pointer position
        this.raycaster.setFromCamera(e.normalizedMouseCoordinates, this.scene.mainCamera);
        this.intersects = this.raycaster.intersectObjects(this.scene.children);
    }

    update(): void {
        for (let i = 0; i < this.scene.children.length; i++) {
            const child = this.scene.children[i];
            if ((child as THREE.Mesh).isMesh) {
                if (this.tempMaterial) {
                    const mesh: THREE.Mesh = child as THREE.Mesh;
                    mesh.material = this.tempMaterial;
                }
            }
        }

        const hasInterset: boolean = this.intersects && this.intersects.length > 0;
        if (hasInterset) {
            for (let i = 0; i < this.intersects.length; i++) {
                const child = this.intersects[i].object;
                if ((child as THREE.Mesh).isMesh) {
                    const mesh: THREE.Mesh = child as THREE.Mesh;
                    this.tempMaterial = mesh.material;

                    mesh.material = this.hitMaterial;
                }
            }
        }
    }
}
