
import * as THREE from "three";
import { UtilsArray } from "../../../../api/utils/array";
import { Component } from "./component";

/* new T() */
export type Newable<T> = { new(...args: any[]): T };

export class GameObject {
  name: string;
  transform: THREE.Object3D = new THREE.Object3D();
  components: Component[] = [];

  constructor(parent: THREE.Object3D, name: string) {
    this.name = name;
    this.components = [];
    this.transform.name = name;
    parent.add(this.transform);
  }

  addComponent<C extends Component>(ComponentType: Newable<C>, ...args: any[]): C {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
    const component: C = new ComponentType(this, ...args);
    this.components.push(component);
    return component;
  }

  removeComponent(component: Component): void {
    UtilsArray.removeArrayElement(this.components, component);
  }

  getComponent<C extends Component>(ComponentType: Newable<C>): Component | undefined {
    return this.components.find((c: Component) => c instanceof ComponentType);
  }

  update(): void {
    for (const component of this.components) {
      component.update();
    }
  }
}
