export interface IState {
  enter?: (p: FiniteStateMachine) => void;
  exit?: (p: FiniteStateMachine) => void;
  update: () => void;
}

export class FiniteStateMachine {
  states: { [key: string]: IState };
  currentState!: string;

  constructor(states: { [key: string]: IState }, initialState: string) {
    this.states = states;
    this.transition(initialState);
  }

  get state(): string {
    return this.currentState;
  }

  transition(state: string): void {
    const oldState: IState = this.states[this.currentState];
    if (oldState && oldState.exit) {
      oldState.exit(this);
    }
    this.currentState = state;
    const newState: IState = this.states[state];
    if (newState.enter) {
      newState.enter(this);
    }
  }

  update(): void {
    const state: IState = this.states[this.currentState];
    if (state.update) {
      state.update.call(this);
    }
  }
}