import { GUI } from 'dat.gui';
import * as THREE from 'three';
import { ToneMapping } from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { ObjectSelector } from '../../api/engine/object_selector';
import { AScene } from '../../api/engine/a_scene';
import { CustomMeshCreator } from '../../api/mesh/creators/custom_mesh_creator';
import { MeshCreator } from '../../api/mesh/creators/mesh_creator';
import { MeshCreatorWithGUI } from "../../api/mesh/creators/mesh_creator_gui";
import { EditMesh } from '../../api/mesh/editMesh/edit_mesh';
import { EditMeshMode } from "../../api/mesh/editMesh/edit_mesh_mode";
import { EditMeshGUI } from "../../api/mesh/editMesh/edit_mesh_gui";
import { MeshData } from '../../api/mesh/mesh_data';
import { MeshModifier } from '../../api/mesh/modifiers/mesh_modifier';
import { MeshModifierGUI } from '../../api/mesh/modifiers/mesh_modifier_gui';
import { BoxGeometryCustomCreator } from '../../api/mesh/primitives/box';
import '../../styles/style.css';
import { editMeshItemFactory } from '../../api/mesh/editMesh/item/edit_mesh_factory';

const DEBUG: boolean = false;

export class EditorScene extends AScene {

    gui: GUI = new GUI();

    standardMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x3F78DB });

    //Mesh Creator
    meshCreatorWithGUI!: MeshCreatorWithGUI;

    //Object Selector
    objectSelector!: ObjectSelector;

    //Mesh Modifier
    meshModifier: MeshModifier = new MeshModifier();
    meshModifierGUI: MeshModifierGUI = new MeshModifierGUI(this.gui);

    //EditMesh
    editMesh: EditMesh = new EditMesh(() => this.mainCamera, editMeshItemFactory);
    editMeshGUI: EditMeshGUI = new EditMeshGUI(this.gui);

    constructor() {
        super();
    }

    setup(): void {

        this.setupRenderer();
        // this.setupEnvironment();
        this.setupScene();

        //Object Selector
        this.objectSelector = new ObjectSelector(this);
        this.objectSelector.onSelectionChanged.subscribe(this.manageEditMesh.bind(this));

        //Mesh Creator
        this.meshCreatorWithGUI = new MeshCreatorWithGUI(this.gui);
        this.meshCreatorWithGUI.guiFolder.add(this, this.createCustomMeshModifierWithGui.name).name('Custom MeshModifier');
        MeshCreator.onMeshCreated.subscribe((mesh: THREE.Mesh) => {
            this.addAndSelectMesh(mesh);
        });

        this.editMesh.scene = this;//used to debug mode to add some visual elements
    }

    //Todo: remove this
    private createCustomMeshModifierWithGui(): void {
        const mesh = new CustomMeshCreator().create(new BoxGeometryCustomCreator());
        this.addAndSelectMesh(mesh);
    }

    private addAndSelectMesh(mesh: THREE.Mesh): void {
        this.add(mesh);
        this.objectSelector.select(mesh);
    }

    private setupEnvironment(): void {
        const textureLoader: THREE.TextureLoader = new THREE.TextureLoader();
        //https://dl.polyhaven.org/file/ph-assets/HDRIs/extra/Tonemapped%20JPG/venice_sunset.jpg
        const textureEquirec: THREE.Texture = textureLoader.load('/assets/environment/venice_sunset.jpg');
        textureEquirec.mapping = THREE.EquirectangularReflectionMapping;
        textureEquirec.encoding = THREE.sRGBEncoding;

        this.background = textureEquirec;
        this.environment = textureEquirec;
    }

    private setupRenderer(): void {
        const params: {
            exposure: number,
            toneMapping: ToneMapping
        } = {
            exposure: 2.2,
            toneMapping: THREE.LinearToneMapping
        };

        this.engine.renderer.toneMapping = params.toneMapping;
        this.engine.renderer.toneMappingExposure = params.exposure;

        this.engine.renderer.shadowMap.enabled = true;
        this.engine.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    }

    private setupScene(): void {

        this.background = new THREE.Color(0x151F30);

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.1);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(1, 5, 2);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 512;
        directionalLight.shadow.mapSize.height = 512;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 1000;
        this.add(directionalLight);

        if (DEBUG) {
            const directionalLightHelper: THREE.DirectionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 0.5);
            this.add(directionalLightHelper);

            const helper: THREE.CameraHelper = new THREE.CameraHelper(directionalLight.shadow.camera);
            this.add(helper);
        }

        // Base camera
        const perspectiveCamera: THREE.PerspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        perspectiveCamera.position.x = 3;
        perspectiveCamera.position.y = 3;
        perspectiveCamera.position.z = 3;
        this.add(perspectiveCamera);

        this.mainCamera = perspectiveCamera;

        // Controls
        const controls = new OrbitControls(perspectiveCamera, this.engine.renderer.domElement);
        controls.target.set(0, 0, 0);
        this.controls = controls;

        //Grid
        const gridHelper: THREE.GridHelper = new THREE.GridHelper(4, 4, 0x253754, 0x1e2d44);
        gridHelper.position.setY(-0.001);
        this.add(gridHelper);

        //Origin
        const axesHelper = new THREE.AxesHelper(1);
        axesHelper.renderOrder = 10;
        this.add(axesHelper);
    }

    unSubscribeOnDragMeshElementChanged?: () => void;
    unSubscribeOnEditModeChanged?: () => void;
    manageEditMesh(data: THREE.Object3D | undefined): void {
        this.editMeshGUI.clear();
        this.meshModifierGUI.clear();

        this.unSubscribeOnEditModeChanged && this.unSubscribeOnEditModeChanged();
        this.unSubscribeOnDragMeshElementChanged && this.unSubscribeOnDragMeshElementChanged();

        if (data && (data as THREE.Mesh).isMesh) {
            const mesh: THREE.Mesh = data as THREE.Mesh;

            MeshData.set(mesh);

            this.editMesh.init(mesh);
            this.editMeshGUI.init(this.editMesh, true);

            this.meshModifier.init(mesh);
            this.meshModifierGUI.init(this.meshModifier, true);

            this.unSubscribeOnEditModeChanged = this.editMesh.onEditModeChanged.subscribe((mode: EditMeshMode) => {
                if (mode !== EditMeshMode.none) {
                    this.objectSelector.enabled = false;
                    let controlsEnabledCache: boolean | undefined;
                    this.unSubscribeOnDragMeshElementChanged = this.editMesh.onDragMeshElementChanged.subscribe((dragging: boolean) => {
                        if (dragging) {
                            if (this.controls) {
                                controlsEnabledCache = this.controls.enabled;
                                this.controls.enabled = false;
                            }
                        } else if (!dragging) {
                            if (this.controls) {
                                this.controls.enabled = controlsEnabledCache ?? true;
                            }
                        }
                    });
                } else if (mode === EditMeshMode.none) {
                    this.objectSelector.enabled = true;
                    if (this.controls) {
                        this.controls.enabled = true;
                    }

                    this.editMesh.cleanup();
                    this.meshModifier.cleanup();
                    this.manageEditMesh(data);
                }
            });
        } else {
            this.editMesh.cleanup();
            this.meshModifier.cleanup();
        }
    }

    update(): void {
        //
    }

    dispose(): void {
        this.gui.destroy();
    }
}
