import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { CustomMouseEvent, MouseManager } from '../../api/engine/mouse_manager';
import { AScene } from '../../api/engine/a_scene';
import { GeometryCreator } from '../../api/mesh/creators/geometry_creator';
import { MeshRayCaster } from '../../api/mesh/mesh_ray_caster';

//https://hofk.de/main/discourse.threejs/2018/selectingFaceindex/selectingFaceindex.html

export class EditMeshFaceSelectScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    mesh!: THREE.Mesh;

    meshRayCaster!: MeshRayCaster;

    constructor() {
        super();
    }

    setup(): void {
        this.setupScene();

        const material: THREE.MeshBasicMaterial = new THREE.MeshBasicMaterial({ color: 0x666666, vertexColors: false, wireframe: false, side: THREE.DoubleSide });
        const geometry = GeometryCreator.cylinder({
            radiusTop: 2,
            radiusBottom: 2,
            height: 15,
            radialSegments: 32,
            heightSegments: 20,
            openEnded: true,
        });

        this.mesh = new THREE.Mesh(geometry, [material]);
        this.mesh.rotation.x = -Math.PI * .5;
        this.mesh.layers.enable(1);//> for MeshRayCaster
        this.add(this.mesh);

        const wire = new THREE.LineSegments(new THREE.WireframeGeometry(this.mesh.geometry));
        wire.material = new THREE.LineBasicMaterial({ color: 0xffff00 });
        this.mesh.add(wire);

        this.meshRayCaster = new MeshRayCaster((): THREE.Camera => this.mainCamera);
        MouseManager.instance.mouseDown.subscribe(this.onMouseDown.bind(this));
    }

    private setupScene(): void {

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.x = 3;
        this.perspectiveCamera.position.z = 3;
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = false;
        this.controls.autoRotate = false;
    }

    onMouseDown(event: CustomMouseEvent): void {
        const normalizedMouseCoordinates = event.normalizedMouseCoordinates;
        this.meshRayCaster.selectFace(normalizedMouseCoordinates, this.mesh);
    }

    update(): void {
        //
    }
}


