export class StringBuffer {
    private _strings: string[];

    constructor() {
        this._strings = new Array<string>();
    }

    append(value: string): void {
        if (value) {
            this._strings.push(value);
        }
    }

    appendLine(value: string): void {
        if (value) {
            this._strings.push(value + "\n");
        }
    }

    clear(): void {
        this._strings.length = 0;
    }

    toString(): string {
        return this._strings.join('');
    }
}

export class AnyBuffer {
    private _datas: any[];

    constructor() {
        this._datas = new Array<any>();
    }

    append(value: any): void {
        if (value) {
            this._datas.push(value);
        }
    }

    clear(): void {
        this._datas.length = 0;
    }

    log(): void {
        for (const data of this._datas) {
            console.log(data);
        }
    }
}