import { MeshModifier } from "./mesh_modifier";
import { AComponent } from "../../../scenes/making_game/src/api/component";

// Base for all modifiers

export abstract class Modifier extends AComponent<MeshModifier> {

  private _resultGeometry: THREE.BufferGeometry;
  public get resultGeometry(): THREE.BufferGeometry {
    return this._resultGeometry;
  }
  public set resultGeometry(value: THREE.BufferGeometry) {
    this._resultGeometry = value;
  }

  constructor(editableMesh: MeshModifier) {
    super(editableMesh);
    if (!this.baseObject.mesh) throw "Modifier: No geometry";
    this._resultGeometry = this.baseObject.mesh.geometry;
  }

  abstract update(): void;
}
