import { GameObject } from "./game_object";
import { SafeArray } from "./safe_array";

export class GameObjectManager {
  private static _instance: GameObjectManager;
  static get instance(): GameObjectManager {
    if (this._instance === undefined) this._instance = new GameObjectManager();
    return this._instance;
  }

  gameObjects: SafeArray<GameObject> = new SafeArray();

  private constructor() {
    //
  }

  createGameObject(parent: THREE.Object3D, name: string): GameObject {
    const gameObject: GameObject = new GameObject(parent, name);
    this.gameObjects.add(gameObject);
    return gameObject;
  }

  removeGameObject(gameObject: GameObject): void {
    this.gameObjects.remove(gameObject);
  }

  update(): void {
    this.gameObjects.forEach((gameObject: GameObject) => gameObject.update());
  }
}