import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { DynamicLine } from '../../api/mesh/creators/dynamic_line';
import { GUI } from 'dat.gui';
import { AScene } from '../../api/engine/a_scene';
import { IUpdatable } from '../../api/engine/project';

export class DynamicLineScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    updatables: IUpdatable[] = [];
    gui: GUI = new GUI();

    constructor() {
        super();
    }

    setup(): void {

        // camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.z = 3;
        this.add(this.perspectiveCamera);
        this.mainCamera = this.perspectiveCamera;

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;

        // Objects
        const dynamicLine1: DynamicLine = new DynamicLine();
        this.add(dynamicLine1);
        this.updatables.push(dynamicLine1);

        const dynamicLine2: DynamicLine = new DynamicLine();
        this.add(dynamicLine2);
        this.updatables.push(dynamicLine2);

        // GUI
        const lineFolder: GUI = this.gui.addFolder('Dynamic Line');
        lineFolder.add(dynamicLine1, 'maxPoint', 0, dynamicLine1.MAX_POINTS);
        lineFolder.add(dynamicLine2, 'maxPoint', 0, dynamicLine2.MAX_POINTS);
        lineFolder.open();

        //Stats
        // this.engine.showStats();
    }

    update(): void {
        for (const item of this.updatables) {
            item.update();
        }
    }

    dispose(): void {
        this.gui.destroy();
    }
}