import { CoroutineRunner } from "../../src/api/coroutine_runner";
import * as THREE from "three";
import { Component } from "../../src/api/component";
import { GameObject } from "../../src/api/game_object";
import { GameObjectManager } from "../../src/api/game_object_manager";
import { UtilsMath } from "../../../../api/utils/math";
import { UtilsTexture } from "../../../../api/utils/texture";
import { globals } from "../../src/api/globals";

export class Note extends Component {
  runner: CoroutineRunner;

  constructor(gameObject: GameObject) {
    super(gameObject);

    const { transform } = gameObject;
    const noteMaterial: THREE.SpriteMaterial = new THREE.SpriteMaterial({
      color: new THREE.Color().setHSL(UtilsMath.rand(1), 1, 0.5),
      map: UtilsTexture.makeTextTexture("♪"),
      side: THREE.DoubleSide,
      transparent: true,
    });
    const note: THREE.Sprite = new THREE.Sprite(noteMaterial);
    note.scale.setScalar(3);
    transform.add(note);
    this.runner = new CoroutineRunner();
    const direction: THREE.Vector3 = new THREE.Vector3(UtilsMath.rand(-0.2, 0.2), 1, UtilsMath.rand(-0.2, 0.2));

    function* moveAndRemove(): Generator<undefined, void, unknown> {
      for (let i: number = 0; i < 60; ++i) {
        transform.translateOnAxis(direction, globals.deltaTime * 10);
        noteMaterial.opacity = 1 - i / 60;
        yield;
      }
      transform.parent?.remove(transform);
      GameObjectManager.instance.removeGameObject(gameObject);
    }

    this.runner.add(moveAndRemove());
  }

  update(): void {
    this.runner.update();
  }
}