import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from '../../api/engine/a_scene';
import { LineHelper } from '../math/line_helper';

//Other to check:
// view-source:https://hofk.de/main/discourse.threejs/2018/MovementLinesDashed/MovementLinesDashed.html

export class LineStyleScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    lineMaterial: THREE.LineBasicMaterial = new THREE.LineBasicMaterial({
        vertexColors: true
    });

    constructor() {
        super();
    }

    setup(): void {
        this.setupScene();

        this.line_base();
        this.line_dashed();
        this.createLine2();
        this.buildLineFrom2Points();
    }

    private setupScene(): void {
        this.background = new THREE.Color(0xffffff);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(40, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.set(10, 5, 20);
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        // Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
        this.controls.target.set(10, 0, 0);
        this.controls.update();
    }

    line_base(): void {
        const material = new THREE.LineBasicMaterial({
            color: 0x000000,
            linewidth: 2,
            linecap: 'round', //ignored by WebGLRenderer
            linejoin: 'round' //ignored by WebGLRenderer
        });

        const points = [];
        points.push(new THREE.Vector3(- 2, 0, 0));
        points.push(new THREE.Vector3(0, 2, 0));
        points.push(new THREE.Vector3(2, 0, 0));

        const geometry = new THREE.BufferGeometry().setFromPoints(points);

        const line = new THREE.Line(geometry, material);
        this.add(line);
    }

    line_dashed(): void {
        const material = new THREE.LineDashedMaterial({
            color: 0x000000,
            linewidth: 1,
            scale: 1,          //Globale scale dashes
            dashSize: 0.05,    //Dash line size
            gapSize: 0.05,     //Dash gap size
        });

        const points = [];
        points.push(new THREE.Vector3(0, 0, 0));
        points.push(new THREE.Vector3(5, 0, 0));
        points.push(new THREE.Vector3(5, 5, 0));

        const geometry = new THREE.BufferGeometry().setFromPoints(points);

        const line = new THREE.Line(geometry, material);
        line.computeLineDistances(); //Needed to compute dashes
        this.add(line);
    }

    createLine2(): void {
        const points = [
            new THREE.Vector3(-5, 2, -4),
            new THREE.Vector3(1, 1, 1),
            new THREE.Vector3(1, 1, 1),
            new THREE.Vector3(5, 2, 0),
            new THREE.Vector3(3, 5, 4),
            new THREE.Vector3(5, -2, 0)
        ];

        const geometry = new THREE.BufferGeometry().setFromPoints(points);
        geometry.setAttribute("color", new THREE.BufferAttribute(new Float32Array([1, 0, 1, 0, 0, 1, 0, 1, 1, 1, 1, 1, .5, .5, .5, 1, 0, 1]), 3));
        geometry.setAttribute("colorBase", new THREE.BufferAttribute(new Float32Array([1, 0, 1, 0, 0, 1, 0, 1, 1, 1, 1, 1, .5, .5, .5, 1, 0, 1]), 3));
        geometry.computeBoundingSphere();
        const line = new THREE.LineSegments(geometry, this.lineMaterial);
        line.name = "BLine";
        line.layers.enable(1);
        this.add(line);

        const boxHelper = new THREE.BoxHelper(line, 0xffff00);
        this.add(boxHelper);
    }

    buildLineFrom2Points(): void {
        const ph1 = new THREE.Vector3(0, 0, 0);
        const ph2 = new THREE.Vector3(20, 0, 0);
        const horizonLine = new LineHelper(ph1, ph2);
        this.add(horizonLine);

        const p3v = new THREE.Vector3(2, 0, 0);
        const p4v = new THREE.Vector3(2, 3, 0);
        const line_3v_4v = new LineHelper(p3v, p4v, true);
        this.add(line_3v_4v);

        const p3h = new THREE.Vector3(2, 0, 0);
        const p4h = new THREE.Vector3(2, 0, 3);
        const line_3h_4h = new LineHelper(p3h, p4h, true);
        this.add(line_3h_4h);
    }

    update(): void {
        //
    }
}
