
// https://mapbox.github.io/delaunator/ >>
// https://github.sre.pub/mapbox/delaunator

import { Delaunator, Point } from "./lib/delaunator";

// Each half-edge e starts at points[e]

// Half-edges e are the indices into both of delaunator’s outputs:
// - delaunay.triangles[e] returns the point id where the half-edge starts
// - delaunay.halfedges[e] returns the opposite half-edge in the adjacent triangle, or -1 if there is no adjacent triangle

//Triangle ids and half-edge ids are related.
// - The half-edges of triangle t are 3*t, 3*t + 1, and 3*t + 2.
// - The triangle of half-edge id e is floor(e/3).

// Summary

// edge      →    edges           : nextHalfedge, prevHalfedge, halfedges[]
// edge      →    points          : triangles[]
// edge      →    triangle        : triangleOfEdge

// triangle  →    edges           : edgesOfTriangle
// triangle  →    points          : pointsOfTriangle
// triangle  →    triangles       : trianglesAdjacentToTriangle

// point     →    incoming edges  : edgesAroundPoint
// point     →    outgoing edges  : edgesAroundPoint + halfedge[]
// point     →    points          : edgesAroundPoint + triangles[]
// point     →    triangles       : edgesAroundPoint + triangleOfEdge

export class DelaunayHelper {

  constructor() {
    this.forEachTriangleEdge = this.forEachTriangleEdge.bind(this);
    this.forEachTriangle = this.forEachTriangle.bind(this);
    this.pointsOfTriangle = this.pointsOfTriangle.bind(this);
    this.triangleCenter = this.triangleCenter.bind(this);
    this.forEachVoronoiCell = this.forEachVoronoiCell.bind(this);
    this.edgesAroundPoint = this.edgesAroundPoint.bind(this);
  }

  //Get all coordinates back for each triangle
  getCoordinatesFromTriangles(points: Point[], triangles: Uint32Array): Point[][] {
    const result: Point[][] = [];
    for (let i = 0; i < triangles.length; i += 3) {
      result.push([
        points[triangles[i]],
        points[triangles[i + 1]],
        points[triangles[i + 2]]
      ]);
    }

    return result;
  }

  /**
   * Given a triangle, return it's HalfEdge's ids
   * t: Triangle Id
   */
  edgesOfTriangle(t: number): number[] { const id = 3 * t; return [id, id + 1, id + 2]; }

  /**
   * Given a HalfEdge, return e: HalfEdge Id
   */
  triangleOfEdge(e: number): number { return Math.floor(e / 3); }

  /**
   * Given a HalfEdge, return the next HalfEdge
   */
  nextHalfedge(e: number): number { return (e % 3 === 2) ? e - 2 : e + 1; }
  /**
    * Given a HalfEdge, return the previous HalfEdge
    */
  prevHalfedge(e: number): number { return (e % 3 === 0) ? e + 2 : e - 1; }

  //> Delaunay edges

  /**
   * e: number > HalfEdge Id
   * p: number > Start point
   * q: number > End Point > Next Edge Start point
   */
  forEachTriangleEdge(points: Point[], delaunay: Delaunator, callback: (e: number, p: Point, q: Point) => void): void {
    for (let e = 0; e < delaunay.triangles.length; e++) {
      console.log("halfedges: ", e, delaunay.halfedges[e]);
      if (e > delaunay.halfedges[e]) {
        const p = points[delaunay.triangles[e]]; //Start point
        const q = points[delaunay.triangles[this.nextHalfedge(e)]]; //End Point : Next Edge Start point
        callback(e, p, q);
      }
    }
  }

  //> Constructing triangles

  pointsOfTriangle(delaunay: Delaunator, t: number): number[] {
    return this.edgesOfTriangle(t)
      .map((e: number) => delaunay.triangles[e]);
  }

  /**
   * Usage exemple : draw triangle
    const results = [];
     forEachTriangle(points, delaunay, (t: number, p: Point[]) => {
      const line = `<polygon data-id="${t}" points="${UtilsString.arrayToString(UtilsArray.convert(p))}" fill="${fill(t)}"/>` ;
       results.push(line);
     });
     results.push(line);
   */

  forEachTriangle(points: Point[], delaunay: Delaunator, callback: (t: number, p: Point[]) => void): void {
    for (let t = 0; t < delaunay.triangles.length / 3; t++) {
      callback(t, this.pointsOfTriangle(delaunay, t).map((p: number) => points[p]));
    }
  }

  //> Adjacent triangles

  trianglesAdjacentToTriangle(delaunay: Delaunator, t: number): number[] {
    const adjacentTriangles = [];
    for (const e of this.edgesOfTriangle(t)) {
      const opposite = delaunay.halfedges[e];
      if (opposite >= 0) {
        adjacentTriangles.push(this.triangleOfEdge(opposite));
      }
    }
    return adjacentTriangles;
  }

  //> Triangle circumcenters

  circumcenter(a: Point, b: Point, c: Point): Point {
    const ad = a[0] * a[0] + a[1] * a[1];
    const bd = b[0] * b[0] + b[1] * b[1];
    const cd = c[0] * c[0] + c[1] * c[1];
    const D = 2 * (a[0] * (b[1] - c[1]) + b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]));
    return [
      1 / D * (ad * (b[1] - c[1]) + bd * (c[1] - a[1]) + cd * (a[1] - b[1])),
      1 / D * (ad * (c[0] - b[0]) + bd * (a[0] - c[0]) + cd * (b[0] - a[0])),
    ];
  }

  triangleCenter(points: Point[], delaunay: Delaunator, t: number): Point {
    const vertices: Point[] = this.pointsOfTriangle(delaunay, t).map((p: number) => points[p]);
    return this.circumcenter(vertices[0], vertices[1], vertices[2]);
  }

  //> Voronoi edges

  forEachVoronoiEdge(points: Point[], delaunay: Delaunator, callback: (e: number, p: Point, q: Point) => void): void {
    for (let e = 0; e < delaunay.triangles.length; e++) {
      if (e < delaunay.halfedges[e]) {
        const p = this.triangleCenter(points, delaunay, this.triangleOfEdge(e));
        const q = this.triangleCenter(points, delaunay, this.triangleOfEdge(delaunay.halfedges[e]));
        callback(e, p, q);
      }
    }
  }

  //> Constructing Voronoi cells

  edgesAroundPoint(delaunay: Delaunator, start: number): number[] {
    const result = [];
    let incoming = start;
    do {
      result.push(incoming);
      const outgoing = this.nextHalfedge(incoming);
      incoming = delaunay.halfedges[outgoing];
    } while (incoming !== -1 && incoming !== start);
    return result;
  }

  //> Drawing Voronoi cells

  forEachVoronoiCell(points: Point[], delaunay: Delaunator, callback: (p: number, vertices: Point[]) => void): void {
    const seen = new Set(); // of point ids
    for (let e = 0; e < delaunay.triangles.length; e++) {
      const p = delaunay.triangles[this.nextHalfedge(e)];
      if (!seen.has(p)) {
        seen.add(p);
        const edges = this.edgesAroundPoint(delaunay, e);
        const triangles = edges.map(this.triangleOfEdge);
        const vertices = triangles.map((t: number) => this.triangleCenter(points, delaunay, t));
        callback(p, vertices);
      }
    }
  }

  //> Convex hull

  forEachVoronoiCell2(points: Point[], delaunay: Delaunator, callback: (p: number, vertices: Point[]) => void): void {
    const index: Map<number, number> = new Map(); // point id to half-edge id
    for (let e = 0; e < delaunay.triangles.length; e++) {
      const endpoint = delaunay.triangles[this.nextHalfedge(e)];
      if (!index.has(endpoint) || delaunay.halfedges[e] === -1) {
        index.set(endpoint, e);
      }
    }
    for (let p = 0; p < points.length; p++) {
      const incoming = index.get(p);
      const edges = this.edgesAroundPoint(delaunay, incoming ?? -1);
      const triangles = edges.map(this.triangleOfEdge);
      const vertices = triangles.map((t: number) => this.triangleCenter(points, delaunay, t));
      callback(p, vertices);
    }
  }
}
