import { IScene } from "./i_scene";

/**
 * A ABaseScene is a scene with basic setup with a canvas.
 * This is use to be do simple configurations
 */
export abstract class ABaseScene implements IScene {
    private _container!: HTMLDivElement;
    get container(): HTMLDivElement {
        if (!this._container)
            throw new Error("container must be set before use. Use set container before.");
        return this._container;
    }
    public set container(value: HTMLDivElement) {
        this._container = value;
    }

    protected _canvas: HTMLCanvasElement;
    get canvas(): HTMLCanvasElement {
        if (!this._canvas)
            throw new Error("canvas must be set before use. Use set canvas before.");
        return this._canvas;
    }
    constructor() {
        const canvas = document.createElement('canvas');
        this._canvas = canvas;
    }

    abstract setup(): void;
    abstract update(): void;
}
