import * as THREE from 'three';
import { ISimpleEvent, SimpleEventDispatcher } from 'strongly-typed-events';

//Todo Extends this ?
export interface CustomMouseEvent {
    event: MouseEvent;
    mouseCoordinates: THREE.Vector2;
    normalizedMouseCoordinates: THREE.Vector2;
}

export class MouseManager {
    private static _instance?: MouseManager;
    static get instance(): MouseManager {
        if (this._instance === undefined)
            this._instance = new MouseManager();
        return this._instance;
    }

    //Mouse
    private _dragging: boolean = false;
    public get dragging(): boolean {
        return this._dragging;
    }

    mouseCoordinates: THREE.Vector2 = new THREE.Vector2();
    normalizedMouseCoordinates: THREE.Vector2 = new THREE.Vector2();

    private readonly onMouseDownEvent: SimpleEventDispatcher<CustomMouseEvent> = new SimpleEventDispatcher<CustomMouseEvent>();
    public get mouseDown(): ISimpleEvent<CustomMouseEvent> { return this.onMouseDownEvent.asEvent(); }

    private readonly onMouseMoveEvent: SimpleEventDispatcher<CustomMouseEvent> = new SimpleEventDispatcher<CustomMouseEvent>();
    public get mouseMove(): ISimpleEvent<CustomMouseEvent> { return this.onMouseMoveEvent.asEvent(); }

    private readonly onMouseDragEvent: SimpleEventDispatcher<CustomMouseEvent> = new SimpleEventDispatcher<CustomMouseEvent>();
    public get mouseDrag(): ISimpleEvent<CustomMouseEvent> { return this.onMouseDragEvent.asEvent(); }

    private readonly onMouseUpEvent: SimpleEventDispatcher<CustomMouseEvent> = new SimpleEventDispatcher<CustomMouseEvent>();
    public get mouseUp(): ISimpleEvent<CustomMouseEvent> { return this.onMouseUpEvent.asEvent(); }

    private constructor() {
        window.addEventListener("mousedown", this._mouseDown.bind(this), false);
        window.addEventListener("mousemove", this._mouseMove.bind(this), false);
        window.addEventListener("mouseup", this._mouseUp.bind(this), false);
    }

    private _mouseDown(event: MouseEvent): void {
        this._dragging = true;
        this.updateMouseCoordinates(event);

        this.onMouseDownEvent.dispatch(this.fillEvent(event));
    }

    private _mouseMove(event: MouseEvent): void {
        this.updateMouseCoordinates(event);
        if (this.dragging) {
            this.onMouseDragEvent.dispatch(this.fillEvent(event));
        } else {
            this.onMouseMoveEvent.dispatch(this.fillEvent(event));
        }
    }

    private _mouseUp(event: MouseEvent): void {
        this.updateMouseCoordinates(event);
        this._dragging = false;

        this.onMouseUpEvent.dispatch(this.fillEvent(event));
    }

    private fillEvent(event: MouseEvent): CustomMouseEvent {
        return {
            event,
            mouseCoordinates: this.mouseCoordinates,
            normalizedMouseCoordinates: this.normalizedMouseCoordinates
        };
    }

    updateMouseCoordinates(event: MouseEvent): void {
        //classic
        this.mouseCoordinates.x = event.clientX;
        this.mouseCoordinates.y = event.clientY;

        //normalized
        this.normalizedMouseCoordinates.x = (event.clientX / window.innerWidth) * 2 - 1;
        this.normalizedMouseCoordinates.y = -(event.clientY / window.innerHeight) * 2 + 1;
    }
}
