export class UtilsHtml {
    static convertHtmlFromString(value: string): HTMLElement {
        const template: HTMLTemplateElement = document.createElement('template');
        template.innerHTML = value;
        return template.content.firstElementChild as HTMLElement;
    }

    static convertHtmlFromParser(value: HTMLElement): HTMLElement {
        return UtilsHtml.convertHtmlFromString(`${value?.outerHTML}`);
    }

    static removeAllChildren(element: HTMLElement): void {
        while (element.lastElementChild) {
            element.removeChild(element.lastElementChild);
        }
    }
}