import * as THREE from "three";
import { assert } from "../../../utils/type_check";
import { Edge } from "../core/edge";
import { Geometry } from "../core/geometry";
import { Mesh } from "../core/mesh";
import { PolygonSoup } from "../core/polygon_soup";
import { Vertex } from "../core/vertex";
import { Vector } from "../linear-algebra/vector";
import { UtilsGeometryProcessingLogger } from "./logger";

export class GeometryProcessingBuilder {

    private mesh!: Mesh;
    private geometry!: Geometry;

    public threeMesh?: THREE.Mesh = undefined;
    public threeGeometry?: THREE.BufferGeometry = undefined;
    public wireframe?: THREE.LineSegments = undefined;

    private positions?: Float32Array = undefined;
    // private uvs?: Float32Array = undefined;
    private normals?: Float32Array = undefined;
    private colors?: Float32Array = undefined;
    private indices?: Uint32Array = undefined;

    readonly ORANGE: Vector = new Vector(1.0, 0.5, 0.0);

    initMesh(polygonSoup: PolygonSoup): THREE.Mesh | undefined {
        let result: THREE.Mesh | undefined = undefined;

        this.mesh = new Mesh();
        if (this.mesh.build(polygonSoup)) {
            // create geometry object
            this.geometry = new Geometry(this.mesh, polygonSoup["v"], false);

            // create a THREE.js mesh and geometry object
            this.threeGeometry = this.initThreeGeometry();
            this.initThreeMesh();

            result = this.threeMesh;
        } else {
            alert("Unable to build halfEdge mesh");
        }

        return result;
    }

    public work(): boolean {
        if (!this.threeMesh) return false;

        // const vertexA = this.getVertexByVector(new Vector(0, 0, 0))[0];
        // const vertexB = this.getVertexByVector(new Vector(0, 1, 0))[0];

        // const edge = this.getEdgeByVertices(vertexA, vertexB);

        // const corner1 = edge.halfEdge?.corner;
        // const corner2 = edge.halfEdge?.twin?.corner;

        //Log Adjacence
        // const stringBuffer = new StringBuffer();
        // UtilsGeometryProcessingLogger.logVertex(vertexB, stringBuffer);
        // for (const h of vertexB.adjacentHalfedges()) {
        //     if (h) {
        //         UtilsGeometryProcessingLogger.logHalfEdge(h, stringBuffer);
        //     }
        // }
        // console.log(stringBuffer.toString());

        UtilsGeometryProcessingLogger.logData(this.mesh, this.geometry);

        const newThreeGeometry = this.initThreeGeometry();
        if (!newThreeGeometry) return false;

        this.threeMesh.geometry.dispose();
        this.threeMesh.geometry = newThreeGeometry;

        return true;
    }

    /**
     * 
     * @param vector : Vector
     * @returns number[]: array of indices. Could have multiple vertices over the same position 
     */
    getVertexIndicesByVector(vector: Vector): number[] {
        const result: number[] = [];
        for (const k in this.geometry.positions) {
            if (this.geometry.positions[k].x === vector.x &&
                this.geometry.positions[k].y === vector.y) {
                result.push(Number(k));
            }
        }

        return result;
    }

    getVertexByVector(vector: Vector): Vertex[] {
        const result: Vertex[] = [];
        const vertexIndices = this.getVertexIndicesByVector(vector);

        for (let i = 0; i < vertexIndices.length; i++) {
            const vertex = this.mesh.vertices[vertexIndices[i]];
            result.push(vertex);
        }
        return result;
    }

    getEdgeByVertices(vertexA: Vertex, vertexB: Vertex): Edge {
        const result = this.mesh.edges.filter((e: Edge) => {
            const d1 = e.halfEdge?.vertex === vertexA && e.halfEdge?.twin?.vertex === vertexB;
            const d2 = e.halfEdge?.vertex === vertexB && e.halfEdge?.twin?.vertex === vertexA;
            return d1 || d2;
        });

        if (result.length > 1) {
            throw new Error("Mulitple Edges for 2 vertices");
        }

        return result[0];
    }

    private initThreeGeometry(): THREE.BufferGeometry {
        // create geometry object
        const result = new THREE.BufferGeometry();

        // fill position, normal and color buffers
        const V = this.mesh.vertices.length;
        this.positions = new Float32Array(V * 3);
        this.normals = new Float32Array(V * 3);
        this.colors = new Float32Array(V * 3);
        for (const v of this.mesh.vertices) {
            const i = v.index;

            const position = this.geometry.positions[v.index];
            this.positions[3 * i + 0] = position.x;
            this.positions[3 * i + 1] = position.y;
            this.positions[3 * i + 2] = position.z;

            const normal = this.geometry.vertexNormalEquallyWeighted(v);
            this.normals[3 * i + 0] = normal.x;
            this.normals[3 * i + 1] = normal.y;
            this.normals[3 * i + 2] = normal.z;

            this.colors[3 * i + 0] = this.ORANGE.x;
            this.colors[3 * i + 1] = this.ORANGE.y;
            this.colors[3 * i + 2] = this.ORANGE.z;
        }

        // fill index buffer
        const F = this.mesh.faces.length;
        this.indices = new Uint32Array(F * 3);
        for (const f of this.mesh.faces) {
            let i = 0;
            for (const v of f.adjacentVertices()) {
                assert(v);
                this.indices[3 * f.index + i++] = v.index;
            }
        }

        // set geometry
        result.setIndex(new THREE.BufferAttribute(this.indices, 1));
        result.setAttribute("position", new THREE.BufferAttribute(this.positions, 3));
        result.setAttribute("normal", new THREE.BufferAttribute(this.normals, 3));
        result.setAttribute("color", new THREE.BufferAttribute(this.colors, 3));

        return result;
    }

    private initThreeMesh(): void {
        // const threeMaterial = new THREE.MeshPhongMaterial({
        //     color: 0x3F78DB,
        //     polygonOffset: true,
        //     polygonOffsetFactor: 1,
        //     polygonOffsetUnits: 1,
        //     side: THREE.DoubleSide
        // });

        const standardMaterial: THREE.MeshBasicMaterial = new THREE.MeshBasicMaterial({ color: 0x3F78DB, side: THREE.DoubleSide });

        // create wireframe
        this.wireframe = new THREE.LineSegments();
        this.wireframe.geometry = new THREE.WireframeGeometry(this.threeGeometry);
        this.wireframe.material = new THREE.LineBasicMaterial({
            color: 0x000000,
            linewidth: 0.75
        });

        // create mesh
        this.threeMesh = new THREE.Mesh(this.threeGeometry, standardMaterial);
    }


}