import * as THREE from "three";

export class UtilsTexture {
  static makeTextTexture(str: string, width: number = 64, height: number = 64): THREE.CanvasTexture | null {
    const ctx: CanvasRenderingContext2D | null = document.createElement("canvas").getContext("2d");
    if (!ctx) return null;

    ctx.canvas.width = width;
    ctx.canvas.height = height;
    ctx.font = "60px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillStyle = "#FFF";
    ctx.fillText(str, ctx.canvas.width / 2, ctx.canvas.height / 2);
    return new THREE.CanvasTexture(ctx.canvas);
  }
}