'use strict';

import * as Utils from "./utils";

//https://mathworld.wolfram.com/DelaunayTriangulation.html

const EPSILON = Math.pow(2, -52);
const EDGE_STACK = new Uint32Array(512);

export type Point = [number, number];

export class Delaunator {
    coords: Float64Array;
    triangles!: Uint32Array;
    halfedges!: Uint32Array | Int32Array;
    hull!: Uint32Array;
    trianglesLen: number = 0;

    private _hullTri: Uint32Array;
    private _hullHash: Int32Array;
    private _hullNext: Uint32Array; //Store next Hull Id
    private _hullPrev: Uint32Array; //Store previous Hull Id
    private _hashSize: number;
    private _triangles: Uint32Array;
    private _halfedges: Int32Array;
    private _ids: Uint32Array;
    private _hullStart!: number;

    static from(points: Point[], getX: (p: Point) => number = Utils.defaultGetX, getY: (p: Point) => number = Utils.defaultGetY): Delaunator {
        const n = points.length;
        const coords = new Float64Array(n * 2); //2 elements by point (x, y)

        // flattern points in coords
        for (let i = 0; i < n; i++) {
            const p = points[i];
            coords[2 * i] = getX(p);
            coords[2 * i + 1] = getY(p);
        }

        return new Delaunator(coords);
    }

    constructor(coords: Float64Array) {
        const n = coords.length >> 1;
        if (n > 0 && typeof coords[0] !== 'number') throw new Error('Expected coords to contain numbers.');

        this.coords = coords;

        // arrays that will store the triangulation graph
        const maxTriangles = Math.max(2 * n - 5, 0);
        this._triangles = new Uint32Array(maxTriangles * 3);
        this._halfedges = new Int32Array(maxTriangles * 3);

        // temporary arrays for tracking the edges of the advancing convex hull
        this._hashSize = Math.ceil(Math.sqrt(n));
        this._hullPrev = new Uint32Array(n); // edge to prev edge
        this._hullNext = new Uint32Array(n); // edge to next edge
        this._hullTri = new Uint32Array(n); // edge to adjacent triangle
        this._hullHash = new Int32Array(this._hashSize).fill(-1); // angular edge hash

        // temporary arrays for sorting points
        this._ids = new Uint32Array(n);


        this.update();
    }

    update(): void {
        const { coords, _hullPrev: hullPrev, _hullNext: hullNext, _hullTri: hullTri, _hullHash: hullHash } = this;
        const n = coords.length >> 1;

        // populate an array of point indices; 
        for (let i = 0; i < n; i++) {
            this._ids[i] = i;
        }

        // find point's bounding box
        // calculate input data bbox ()
        // starting at + Infinity, this slides minX to the min value found
        // starting at + Infinity, this slides minY to the min value found
        // starting at - Infinity, this slides maxX to the min value found
        // starting at - Infinity, this slides maxY to the min value found

        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;

        for (let i = 0; i < n; i++) {
            const x = coords[2 * i];
            const y = coords[2 * i + 1];
            if (x < minX) minX = x;
            if (y < minY) minY = y;
            if (x > maxX) maxX = x;
            if (y > maxY) maxY = y;
        }

        // center of the bouding box
        const boundingBoxCenterX = (minX + maxX) / 2;
        const boundingBoxCenterY = (minY + maxY) / 2;

        // find the 3 first points to start triangulation
        let minDist: number;

        let i0: number = -1; // will store the id of the closest point to the bouding box center
        let i1: number = -1; // will Store the id of the closest point to i0
        let i2: number = -1; // will Store the id of the point on the 3 points circle for i0, i1, i2 with the minimal radius

        // find the close seed point to the center
        minDist = Infinity;
        for (let i = 0; i < n; i++) {
            const d = Utils.dist(boundingBoxCenterX, boundingBoxCenterY, coords[2 * i], coords[2 * i + 1]);
            if (d < minDist) {
                i0 = i;
                minDist = d;
            }
        }
        const i0x: number = coords[2 * i0];
        const i0y: number = coords[2 * i0 + 1];

        // find the point closest to the seed
        minDist = Infinity;
        for (let i = 0; i < n; i++) {
            if (i === i0) continue; //skip the first one
            const d = Utils.dist(i0x, i0y, coords[2 * i], coords[2 * i + 1]);
            if (d < minDist && d > 0) {
                i1 = i;
                minDist = d;
            }
        }
        let i1x: number = coords[2 * i1];
        let i1y: number = coords[2 * i1 + 1];

        // find the third point which forms the smallest circumcircle with the first two
        let minRadius = Infinity;
        for (let i = 0; i < n; i++) {
            if (i === i0 || i === i1) continue; //skip the two first one
            const r = Utils.circumradius(i0x, i0y, i1x, i1y, coords[2 * i], coords[2 * i + 1]);
            if (r < minRadius) {
                i2 = i;
                minRadius = r;
            }
        }
        let i2x: number = coords[2 * i2];
        let i2y: number = coords[2 * i2 + 1];

        // if the 3 points are aligned => minRadius === infinity 
        const _dists: Float64Array = new Float64Array(n);
        if (minRadius === Infinity) {
            // order collinear points by dx (or dy if all x are identical)
            // and return the list as a hull
            for (let i = 0; i < n; i++) {
                _dists[i] = (coords[2 * i] - coords[0]) || (coords[2 * i + 1] - coords[1]);
            }
            Utils.quicksort(this._ids, _dists, 0, n - 1);
            const hull = new Uint32Array(n);
            let j = 0;
            for (let i = 0, d0 = -Infinity; i < n; i++) {
                const id = this._ids[i];
                if (_dists[id] > d0) {
                    hull[j++] = id;
                    d0 = _dists[id];
                }
            }
            this.hull = hull.subarray(0, j);
            this.triangles = new Uint32Array(0);
            this.halfedges = new Uint32Array(0);
            return;
        }

        // swap the order of the seed points for counter-clockwise orientation
        if (Utils.orient2d(i0x, i0y, i1x, i1y, i2x, i2y) < 0) {
            const i = i1;
            const x = i1x;
            const y = i1y;
            i1 = i2;
            i1x = i2x;
            i1y = i2y;
            i2 = i;
            i2x = x;
            i2y = y;
        }

        // get the center of the circle
        const center = Utils.circumcenter(i0x, i0y, i1x, i1y, i2x, i2y);
        const circleCenterX = center.x;
        const circleCenterY = center.y;

        // store distance of all points to the center
        for (let i = 0; i < n; i++) {
            _dists[i] = Utils.dist(coords[2 * i], coords[2 * i + 1], circleCenterX, circleCenterY);
        }

        // sort the points by distance from the seed triangle circumcenter
        Utils.quicksort(this._ids, _dists, 0, n - 1);

        // set up the seed triangle as the starting hull
        this._hullStart = i0;
        let hullSize = 3;

        hullNext[i0] = hullPrev[i2] = i1;
        hullNext[i1] = hullPrev[i0] = i2;
        hullNext[i2] = hullPrev[i1] = i0;

        hullTri[i0] = 0;
        hullTri[i1] = 1;
        hullTri[i2] = 2;

        hullHash.fill(-1);
        hullHash[this._hashKey(i0x, i0y, circleCenterX, circleCenterY)] = i0;
        hullHash[this._hashKey(i1x, i1y, circleCenterX, circleCenterY)] = i1;
        hullHash[this._hashKey(i2x, i2y, circleCenterX, circleCenterY)] = i2;

        this.trianglesLen = 0;
        this._addTriangle(i0, i1, i2, -1, -1, -1);

        //k: orderer ids
        for (let k = 0, xp = 0, yp = 0; k < this._ids.length; k++) {
            const i = this._ids[k];
            const x = coords[2 * i];
            const y = coords[2 * i + 1];

            // skip near-duplicate points
            if (k > 0 && Math.abs(x - xp) <= EPSILON && Math.abs(y - yp) <= EPSILON) continue;
            xp = x;
            yp = y;

            // skip seed triangle points
            if (i === i0 || i === i1 || i === i2) continue;

            // find a visible edge on the convex hull using edge hash
            let start = 0;
            for (let j = 0, key = this._hashKey(x, y, circleCenterX, circleCenterY); j < this._hashSize; j++) {
                start = hullHash[(key + j) % this._hashSize];
                if (start !== -1 && start !== hullNext[start]) break;
            }

            start = hullPrev[start];
            let e = start, q;
            while (q = hullNext[e], Utils.orient2d(x, y, coords[2 * e], coords[2 * e + 1], coords[2 * q], coords[2 * q + 1]) >= 0) {
                e = q;
                if (e === start) {
                    e = -1;
                    break;
                }
            }
            if (e === -1) continue; // likely a near-duplicate point; skip it

            // add the first triangle from the point
            let t = this._addTriangle(e, i, hullNext[e], -1, -1, hullTri[e]);

            // recursively flip triangles from the point until they satisfy the Delaunay condition
            hullTri[i] = this._legalize(t + 2);
            hullTri[e] = t; // keep track of boundary triangles on the hull
            hullSize++;

            // walk forward through the hull, adding more triangles and flipping recursively
            let n = hullNext[e];
            while (q = hullNext[n], Utils.orient2d(x, y, coords[2 * n], coords[2 * n + 1], coords[2 * q], coords[2 * q + 1]) < 0) {
                t = this._addTriangle(n, i, q, hullTri[i], -1, hullTri[n]);
                hullTri[i] = this._legalize(t + 2);
                hullNext[n] = n; // mark as removed
                hullSize--;
                n = q;
            }

            // walk backward from the other side, adding more triangles and flipping
            if (e === start) {
                while (q = hullPrev[e], Utils.orient2d(x, y, coords[2 * q], coords[2 * q + 1], coords[2 * e], coords[2 * e + 1]) < 0) {
                    t = this._addTriangle(q, i, e, -1, hullTri[e], hullTri[q]);
                    this._legalize(t + 2);
                    hullTri[q] = t;
                    hullNext[e] = e; // mark as removed
                    hullSize--;
                    e = q;
                }
            }

            // update the hull indices
            this._hullStart = hullPrev[i] = e;
            hullNext[e] = hullPrev[n] = i;
            hullNext[i] = n;

            // save the two new edges in the hash table
            hullHash[this._hashKey(x, y, circleCenterX, circleCenterY)] = i;
            hullHash[this._hashKey(coords[2 * e], coords[2 * e + 1], circleCenterX, circleCenterY)] = e;
        }

        this.hull = new Uint32Array(hullSize);
        for (let i = 0, e = this._hullStart; i < hullSize; i++) {
            this.hull[i] = e;
            e = hullNext[e];
        }

        // trim typed triangle mesh arrays
        this.triangles = this._triangles.subarray(0, this.trianglesLen);
        this.halfedges = this._halfedges.subarray(0, this.trianglesLen);
    }

    _hashKey(x: number, y: number, circleCenterX: number, circleCenterY: number): number {
        return Math.floor(Utils.pseudoAngle(x - circleCenterX, y - circleCenterY) * this._hashSize) % this._hashSize;
    }

    _legalize(a: number): number {
        const { _triangles: triangles, _halfedges: halfedges, coords } = this;

        let i = 0;
        let ar = 0;

        // recursion eliminated with a fixed-size stack
        // eslint-disable-next-line no-constant-condition
        while (true) {
            const b = halfedges[a];

            /* if the pair of triangles doesn't satisfy the Delaunay condition
             * (p1 is inside the circumcircle of [p0, pl, pr]), flip them,
             * then do the same check/flip recursively for the new pair of triangles
             *
             *           pl                    pl
             *          /||\                  /  \
             *       al/ || \bl            al/    \a
             *        /  ||  \              /      \
             *       /  a||b  \    flip    /___ar___\
             *     p0\   ||   /p1   =>   p0\---bl---/p1
             *        \  ||  /              \      /
             *       ar\ || /br             b\    /br
             *          \||/                  \  /
             *           pr                    pr
             */
            const a0 = a - a % 3;
            ar = a0 + (a + 2) % 3;

            if (b === -1) { // convex hull edge
                if (i === 0) break;
                a = EDGE_STACK[--i];
                continue;
            }

            const b0 = b - b % 3;
            const al = a0 + (a + 1) % 3;
            const bl = b0 + (b + 2) % 3;

            const p0 = triangles[ar];
            const pr = triangles[a];
            const pl = triangles[al];
            const p1 = triangles[bl];

            const illegal = Utils.inCircle(
                coords[2 * p0], coords[2 * p0 + 1],
                coords[2 * pr], coords[2 * pr + 1],
                coords[2 * pl], coords[2 * pl + 1],
                coords[2 * p1], coords[2 * p1 + 1]);

            if (illegal) {
                triangles[a] = p1;
                triangles[b] = p0;

                const hbl = halfedges[bl];

                // edge swapped on the other side of the hull (rare); fix the halfedge reference
                if (hbl === -1) {
                    let e = this._hullStart;
                    do {
                        if (this._hullTri[e] === bl) {
                            this._hullTri[e] = a;
                            break;
                        }
                        e = this._hullPrev[e];
                    } while (e !== this._hullStart);
                }
                this._link(a, hbl);
                this._link(b, halfedges[ar]);
                this._link(ar, bl);

                const br = b0 + (b + 1) % 3;

                // don't worry about hitting the cap: it can only happen on extremely degenerate input
                if (i < EDGE_STACK.length) {
                    EDGE_STACK[i++] = br;
                }
            } else {
                if (i === 0) break;
                a = EDGE_STACK[--i];
            }
        }

        return ar;
    }

    _link(a: number, b: number): void {
        this._halfedges[a] = b;
        if (b !== -1) this._halfedges[b] = a;
    }

    /**
     * add a new triangle given vertex indices and adjacent half-edge ids
     */ 
    _addTriangle(i0: number, i1: number, i2: number, a: number, b: number, c: number): number {
        const t = this.trianglesLen;

        this._triangles[t] = i0;
        this._triangles[t + 1] = i1;
        this._triangles[t + 2] = i2;

        this._link(t, a);
        this._link(t + 1, b);
        this._link(t + 2, c);

        this.trianglesLen += 3;

        return t;
    }
}
