import { GUI } from 'dat.gui';
import { MeshData } from "../mesh_data";
import { MeshModifier } from "./mesh_modifier";
import { Modifier } from "./modifier";
import { Bend, getDefaultBendGUIParameters } from "./types/bend";
import { getDefaultSinusoidGUIParameters, Sinusoid } from "./types/sinusoid";
import { getDefaultTaperGUIParameters, Taper } from "./types/taper";
import { getDefaultTwistGUIParameters, Twist } from "./types/twist";
import { GuiParameters, UtilsGUI } from "../../utils/gui";
import { allExistingModifiers, ModifierType } from './types';

export const DEBUG: boolean = true;

export class MeshModifierGUI {

  static createUIForModifiers(gui: GUI, modifiers: Modifier[], meshUpdater: () => void): void {
    modifiers.forEach((modifier: Modifier) => {
      MeshModifierGUI.addModifierGUI(gui, modifier, meshUpdater);
    });
  }

  private static addModifierGUI(gui: GUI, modifier: Modifier, meshUpdater: () => void): void {
    let guiParameters: GuiParameters | undefined;

    if (modifier instanceof Twist) {
      guiParameters = getDefaultTwistGUIParameters(modifier);
    } else if (modifier instanceof Bend) {
      guiParameters = getDefaultBendGUIParameters(modifier);
    } else if (modifier instanceof Taper) {
      guiParameters = getDefaultTaperGUIParameters(modifier);
    } else if (modifier instanceof Sinusoid) {
      guiParameters = getDefaultSinusoidGUIParameters(modifier);
    }

    if (guiParameters) {
      UtilsGUI.fillFolderWithParameters(gui, guiParameters, meshUpdater);
    }
  }

  private gui: GUI;
  private meshModifier?: MeshModifier;

  private _folder?: GUI;
  public get folder(): GUI | undefined {
    return this._folder;
  }

  private removeAfter: boolean = false;

  constructor(gui: GUI) {
    this.gui = gui;
  }

  init(meshModifier: MeshModifier, removeAfter: boolean = false): void {
    this.meshModifier = meshModifier;
    this.removeAfter = removeAfter;

    const target: {
      modifier: ModifierType,
      addModifier: (() => void)
    } = {
      modifier: ModifierType.Twist, //Default
      addModifier: () => {
        if (!this.meshModifier) return;
        const modifierType = allExistingModifiers[target.modifier];
        const modifier = this.meshModifier.addModifier<Modifier>(modifierType);

        DEBUG && console.debug("AddModifierGUI::addModifier: ", modifier);

        //Todo : add modifier to gui if exisiting
        this.clear();
        this.init(this.meshModifier, true);
      }
    };

    this._folder = this.gui.addFolder("Modifier");
    this._folder.add(target, "modifier", Object.values(ModifierType).sort()).name("Modifiers");
    this._folder.add(target, target.addModifier.name).name("Add Modifier");
    this._folder.open();

    this.buildGuiForMesh();
  }

  clear(): void {
    if (this._folder && this.meshModifier) {
      if (this.removeAfter) {
        if (this.gui.__folders[this._folder.name]) {
          this.gui.removeFolder(this._folder);
        }
      }
    }
  }

  private buildGuiForMesh(): void {

    if (!this.meshModifier || !this.meshModifier.mesh) return;
    const mesh = this.meshModifier?.mesh;
    const meshData = MeshData.get(mesh);

    // //place elsewhere
    // let modifierUpdater: (() => void) | undefined;
    // if(this.meshModifier){
    //   modifierUpdater = this.meshModifier.update.bind(this.meshModifier);
    //   // modifierUpdater = meshData.geometryUpdater;
    // }

    const gui = this._folder;

    if (gui) {
      //Geometry
      if (meshData.geometryGuiParameters && meshData.geometryUpdater) {
        UtilsGUI.fillFolderWithParameters(gui, meshData.geometryGuiParameters, meshData.geometryUpdater);
      }

      //Modifiers
      if (meshData.modifiers && meshData.modifierUpdater) {
        MeshModifierGUI.createUIForModifiers(gui, meshData.modifiers, meshData.modifierUpdater);
      }
    }
  }
}
