import { VertexNode } from './vertex_node';
import { Face } from './face';

// https://threejs.org/docs/#examples/en/math/convexhull/HalfEdge

// Entity for a Doubly-Connected Edge List (DCEL).
export class HalfEdge {
    next: HalfEdge | null;
    prev: HalfEdge | null;
    vertex: VertexNode | null;
    twin: HalfEdge | null;
    face: Face;

    constructor(vertex: VertexNode, face: Face) {
        this.vertex = vertex;
        this.prev = null;
        this.next = null;
        this.twin = null;
        this.face = face;
    }

    head(): VertexNode | null {
        return this.vertex;
    }

    tail(): VertexNode | null {
        return this.prev ? this.prev.vertex : null;
    }

    length(): number {
        const head = this.head();
        const tail = this.tail();

        if (tail !== null && head !== null) {
            return tail.point.distanceTo(head.point);
        }

        return - 1;
    }

    lengthSquared(): number {
        const head = this.head();
        const tail = this.tail();

        if (tail !== null && head !== null) {
            return tail.point.distanceToSquared(head.point);
        }

        return - 1;
    }

    setTwin(edge: HalfEdge): HalfEdge {
        this.twin = edge;
        edge.twin = this;

        return this;
    }
}