
import * as THREE from "three";
import { Modifier } from "./modifiers/modifier";
import { GuiParameters, TargetParameters } from "../utils/gui";

export class Object3DData {
    private _parent: THREE.Object3D;
    get parent(): THREE.Object3D {
        return this._parent;
    }

    constructor(parent: THREE.Object3D) {
        this._parent = parent;
    }
}

//Should have other implemtation for other type of Object3D : Camera, Light, ...

export class MeshData extends Object3DData {

    static set(mesh: THREE.Mesh): void {
        if (mesh.userData["MeshData"] === undefined) {
            mesh.userData["MeshData"] = new MeshData(mesh);
        }
    }

    static get(mesh: THREE.Mesh): MeshData {
        if (mesh.userData["MeshData"] === undefined) {
            this.set(mesh);
        }

        return mesh.userData["MeshData"] as MeshData;
    }

    get parent(): THREE.Mesh {
        return super.parent as THREE.Mesh;
    }

    private _originalGeometry: THREE.BufferGeometry | undefined;
    public get originalGeometry(): THREE.BufferGeometry | undefined {
        return this._originalGeometry;
    }
    public set originalGeometry(value: THREE.BufferGeometry | undefined) {
        this._originalGeometry = value;
    }

    private _modifiers: Modifier[] = [];
    get modifiers(): Modifier[] {
        return this._modifiers;
    }

    private _geometryParameters: TargetParameters | undefined;
    public get geometryParameters(): TargetParameters | undefined {
        return this._geometryParameters;
    }
    public set geometryParameters(value: TargetParameters | undefined) {
        this._geometryParameters = value;
    }

    private _geometryGuiParameters: GuiParameters | undefined;
    public get geometryGuiParameters(): GuiParameters | undefined {
        return this._geometryGuiParameters;
    }
    public set geometryGuiParameters(value: GuiParameters | undefined) {
        this._geometryGuiParameters = value;
    }

    private _geometryCreator?: ((parameters: any) => THREE.BufferGeometry);
    public get geometryCreator(): ((parameters: any) => THREE.BufferGeometry) | undefined {
        return this._geometryCreator;
    } public set geometryCreator(value: ((parameters: any) => THREE.BufferGeometry) | undefined) {
        this._geometryCreator = value;
    }

    private _geometryUpdater: (() => void) | undefined;
    public get geometryUpdater(): (() => void) | undefined {
        return this._geometryUpdater;
    }
    public set geometryUpdater(value: (() => void) | undefined) {
        this._geometryUpdater = value;
    }

    private _modifierUpdater: (() => void) | undefined;
    public get modifierUpdater(): (() => void) | undefined {
        return this._modifierUpdater;
    }
    public set modifierUpdater(value: (() => void) | undefined) {
        this._modifierUpdater = value;
    }

    constructor(parent: THREE.Mesh, geometryGuiParameters?: GuiParameters) {
        super(parent);
        this._geometryGuiParameters = geometryGuiParameters;
    }

}