import * as THREE from "three";
import { Component } from "../../src/api/component";
import { FiniteStateMachine } from "../../src/api/finite_state_machine";
import { GameObject } from "../../src/api/game_object";
import { globalsCustom, kForward } from "../globals";
import { SkinInstance } from "../../src/api/skin_instance";
import { StateDisplayHelper } from "./state_display_helper";
import { UtilsMath } from "../../../../api/utils/math";
import { globals } from "../../src/api/globals";
import { GLTFModel } from "../../../../api/utils/gltf";

export class Animal extends Component {
  helper: StateDisplayHelper;
  fsm: FiniteStateMachine;

  constructor(gameObject: GameObject, model: GLTFModel) {
    super(gameObject);
    this.helper = gameObject.addComponent(StateDisplayHelper, model.size);
    const hitRadius: number = (model.size ?? 1) / 2;
    const skinInstance: SkinInstance = gameObject.addComponent(SkinInstance, model);
    skinInstance.mixer.timeScale = globalsCustom.moveSpeed / 4;
    const transform: THREE.Object3D = gameObject.transform;
    const playerTransform: THREE.Object3D = globalsCustom.player!.gameObject.transform;
    const maxTurnSpeed: number = Math.PI * (globalsCustom.moveSpeed / 4);
    const targetHistory: THREE.Vector3[] = [];
    let targetNdx: number = 0;

    function addHistory(): void {
      const targetGO: GameObject = globalsCustom.congaLine[targetNdx];
      const newTargetPos: THREE.Vector3 = new THREE.Vector3();
      newTargetPos.copy(targetGO.transform.position);
      targetHistory.push(newTargetPos);
    }

    this.fsm = new FiniteStateMachine(
      {
        idle: {
          enter: (): void => {
            skinInstance.setAnimation("Idle");
          },
          update: (): void => {
            // check if player is near
            if (
              this.isClose(
                transform,
                hitRadius,
                playerTransform,
                globalsCustom.playerRadius
              )
            ) {
              this.fsm.transition("waitForEnd");
            }
          },
        },
        waitForEnd: {
          enter: (): void => {
            skinInstance.setAnimation("Jump");
          },
          update: (): void => {
            // get the gameObject at the end of the conga line
            const lastGO: GameObject = globalsCustom.congaLine[globalsCustom.congaLine.length - 1];
            const deltaTurnSpeed: number = maxTurnSpeed * globals.deltaTime;
            const targetPos: THREE.Vector3 = lastGO.transform.position;
            aimTowardAndGetDistance(transform, targetPos, deltaTurnSpeed);
            // check if last thing in conga line is near
            if (
              this.isClose(
                transform,
                hitRadius,
                lastGO.transform,
                globalsCustom.playerRadius
              )
            ) {
              this.fsm.transition("goToLast");
            }
          },
        },
        goToLast: {
          enter: (): void => {
            // remember who we're following
            targetNdx = globalsCustom.congaLine.length - 1;
            // add ourselves to the conga line
            globalsCustom.congaLine.push(gameObject);
            skinInstance.setAnimation("Walk");
          },
          update: (): void => {
            addHistory();
            // walk to the oldest point in the history
            const targetPos: THREE.Vector3 = targetHistory[0];
            const maxVelocity: number = globalsCustom.moveSpeed * globals.deltaTime;
            const deltaTurnSpeed: number = maxTurnSpeed * globals.deltaTime;
            const distance: number = aimTowardAndGetDistance(
              transform,
              targetPos,
              deltaTurnSpeed
            );
            const velocity: number = distance;
            transform.translateOnAxis(
              kForward,
              Math.min(velocity, maxVelocity)
            );
            if (distance <= maxVelocity) {
              this.fsm.transition("follow");
            }
          },
        },
        follow: {
          update: (): void => {
            addHistory();
            // remove the oldest history and just put ourselves there.
            const targetPos: THREE.Vector3 | undefined = targetHistory.shift();
            if (!targetPos) return;
            transform.position.copy(targetPos);
            const deltaTurnSpeed: number = maxTurnSpeed * globals.deltaTime;
            aimTowardAndGetDistance(
              transform,
              targetHistory[0],
              deltaTurnSpeed
            );
          },
        },
      },
      "idle"
    );
  }

  // Returns true of obj1 and obj2 are close
  isClose(obj1: THREE.Object3D, obj1Radius: number, obj2: THREE.Object3D, obj2Radius: number): boolean {
    const minDist: number = obj1Radius + obj2Radius;
    const dist: number = obj1.position.distanceTo(obj2.position);
    return dist < minDist;
  }

  update(): void {
    this.fsm.update();
    const dir: number = THREE.MathUtils.radToDeg(
      this.gameObject.transform.rotation.y
    );
    this.helper.setState(`${this.fsm.state}:${dir.toFixed(0)}`);
  }
}

// eslint-disable-next-line @typescript-eslint/typedef
const aimTowardAndGetDistance = (function (): (source: THREE.Object3D, targetPos: THREE.Vector3, maxTurn: number) => number {
  const delta: THREE.Vector3 = new THREE.Vector3();

  return function aimTowardAndGetDistance(source: THREE.Object3D, targetPos: THREE.Vector3, maxTurn: number): number {
    delta.subVectors(targetPos, source.position);
    // compute the direction we want to be facing
    const targetRot: number = Math.atan2(delta.x, delta.z) + Math.PI * 1.5;
    // rotate in the shortest direction
    const deltaRot: number =
      ((targetRot - source.rotation.y + Math.PI * 1.5) % (Math.PI * 2)) -
      Math.PI;
    // make sure we don't turn faster than maxTurn
    const deltaRotation: number = UtilsMath.minMagnitude(deltaRot, maxTurn);
    // keep rotation between 0 and Math.PI * 2
    source.rotation.y = THREE.MathUtils.euclideanModulo(
      source.rotation.y + deltaRotation,
      Math.PI * 2
    );
    // return the distance to the target
    return delta.length();
  };
})();

