/* eslint-disable @typescript-eslint/no-unsafe-call */
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from '../../api/engine/a_scene';
import { MeshCreatorWithGUI } from "../../api/mesh/creators/mesh_creator_gui";
import { GUI } from 'dat.gui';
import { MeshCreator } from '../../api/mesh/creators/mesh_creator';
import { HitTester } from '../../api/mesh/hit_tester';
import { Point } from '../../api/mesh/primitives/point';
import { VectorHelper } from '../../api/helpers/vector_helper';

export class MeshCreatorAndRaycasterScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    gui: GUI = new GUI();

    meshCreatorWithGUI!: MeshCreatorWithGUI;
    box!: THREE.Mesh;

    hitTester!: HitTester;
    arrowHelper!: THREE.ArrowHelper;
    arrowHelper2!: THREE.ArrowHelper;
    vectorHelper!: VectorHelper;

    constructor() {
        super();
    }

    setup(): void {

        this.background = new THREE.Color(0x151F30);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.set(2, 2, 2);
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        //
        this.hitTester = new HitTester(this);

        // Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = false;
        this.controls.autoRotate = false;
        this.controls.target.set(0, 0, 0);
        this.controls.update();

        const gridHelper: THREE.GridHelper = new THREE.GridHelper(4, 4, 0x253754, 0x1e2d44);
        this.add(gridHelper);

        const axesHelper = new THREE.AxesHelper(1);
        this.add(axesHelper);

        // MeshCreatorWithGUI
        this.meshCreatorWithGUI = new MeshCreatorWithGUI(this.gui);
        MeshCreator.onMeshCreated.subscribe((mesh: THREE.Mesh) => {
            this.add(mesh);
        });

        //> Arrow 1
        // const origin = new THREE.Vector3(0, 0, 0);
        // const direction = new THREE.Vector3(0, 1, 0).normalize();
        // const length = 1;
        // const color = 0xffff00;
        // this.arrowHelper = new THREE.ArrowHelper(direction, origin, length, color);
        // this.add(this.arrowHelper);

        // //> Arrow 2
        // const origin2 = new THREE.Vector3(0, 0, 0);
        // const direction2 = new THREE.Vector3(1, 1, 0).normalize();
        // const length2 = 1;
        // const color2 = 0x0ffff0;
        // this.arrowHelper2 = new THREE.ArrowHelper(direction2, origin2, length2, color2);
        // this.add(this.arrowHelper2);

        this.vectorHelper = new VectorHelper();
        this.add(this.vectorHelper.objet3D);

        // vectorHelper.setOrigin(new THREE.Vector3(0, 1, 0));
        // vectorHelper.setTarget(new THREE.Vector3(1, 1, 0));
    }

    update(): void {
        this.hitTester.update();

        if (this.hitTester.intersects) {
            const intersect = this.hitTester.intersects[0];
            if (intersect) {
                const child = this.hitTester.intersects[0].object;

                if ((child as THREE.Mesh).isMesh && intersect.point) {
                    this.vectorHelper.setTarget(intersect.point);

                    const point = new Point();
                    point.position.copy(intersect.point);
                    this.add(point);
                }
            }
        }
    }

    dispose(): void {
        this.gui.destroy();
    }
}
