import { Vector3 } from 'three';
import { Face } from './face';

// https://threejs.org/docs/#examples/en/math/convexhull/VertexNode

// A vertex as a double linked list node.
export class VertexNode {
    point: Vector3;
    prev: VertexNode | null;
    next: VertexNode | null;
    face: Face | null; // the face that is able to see this vertex

    constructor(point: Vector3) {
        this.point = point;
        this.prev = null;
        this.next = null;
        this.face = null;
    }
}