import { GUI } from 'dat.gui';
import { MeshCreator } from './mesh_creator';

/*
    Indirect Usage:
        const meshCreatorWithGUI = new MeshCreatorWithGUI(this.gui);
        const box = meshCreatorWithGUI.meshCreator.box();
        scene.add(box);
*/

export class MeshCreatorWithGUI {

    private _guiFolder!: GUI;
    get guiFolder(): GUI {
        return this._guiFolder;
    }

    constructor(gui: GUI) {
        this.init(gui);
    }

    private init(gui: GUI): void {
        this._guiFolder = gui.addFolder('Create Geometry');
        this._guiFolder.add(MeshCreator, MeshCreator.plane.name).name('Plane');
        this._guiFolder.add(MeshCreator, MeshCreator.box.name).name('Box');
        this._guiFolder.add(MeshCreator, MeshCreator.sphere.name).name('Sphere');
        this._guiFolder.add(MeshCreator, MeshCreator.cylinder.name).name('Cylinder');
        this._guiFolder.add(MeshCreator, MeshCreator.customIndexed.name).name('Custom Indexed');
        this._guiFolder.open();
    }
}
