import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from '../../api/engine/a_scene';
import { UtilsMath } from '../../api/utils/math';

export class MaterialGroupScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    geometry2!: THREE.BufferGeometry;

    constructor() {
        super();
    }

    setup(): void {
        this.setupScene();

        const material0: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const material1: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x00ff00 });
        const material2: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x0000ff });
        const material3: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0xffff00 });
        const material4: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0xff00ff });
        const material5: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x00ffff });

        // Box with multiple material set them automatically on box groups defined in the BoxGeometry
        const geometry: THREE.BoxGeometry = new THREE.BoxGeometry(1, 1, 1);
        const mesh: THREE.Mesh = new THREE.Mesh(geometry, [
            material0,
            material1,
            material2,
            material3,
            material4,
            material5,
        ]);
        mesh.translateZ(-2);
        this.add(mesh);

        // But we can play with groups
        this.geometry2 = new THREE.PlaneBufferGeometry(2, 2, 5, 5);
        const mesh2: THREE.Mesh = new THREE.Mesh(this.geometry2, [
            material0,
            material1,
            material2,
            material3,
            material4,
            material5,
        ]);
        this.add(mesh2);

        this.setRandomMaterialId();
    }

    private setRandomMaterialId(): void {
        const index = this.geometry2.index;
        if (index) {
            this.geometry2.clearGroups(); // No groups > no material > no display
            this.geometry2.addGroup(0, index.count, 0); // Fill all with one materiaID, groups uses index if present

            //Assign random from multiple
            const multipleOf = 6;
            const multipleOfX = UtilsMath.randomMultipleOf(6, index.count);
            this.geometry2.addGroup(multipleOfX, multipleOf, 1);
        }
    }

    private setupScene(): void {
        this.background = new THREE.Color(0xffffff);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.x = 3;
        this.perspectiveCamera.position.z = 3;
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
    }

    count: number = 0;
    update(): void {
        //Temporisation
        if ((this.count % 10 === 0)) {
            this.setRandomMaterialId();
        }
        this.count++;
    }
}