import * as THREE from 'three';
import { EditMesh } from '../edit_mesh';
import { EditMeshMode } from "../edit_mesh_mode";
import { MoveMeshTool } from '../meshtool/type/common/move';
import { AEditMeshItem } from "./a_edit_mesh_item";

export class EditMeshFace extends AEditMeshItem {
    readonly editMeshMode: EditMeshMode = EditMeshMode.face;

    get canDrag(): boolean {
        return this.editMesh.editMeshMode === this.editMeshMode
            && this.vertexInfos?.length === 3
            && this.currentIntersection?.face != undefined;
    }

    private faces?: THREE.Mesh;

    private readonly faceColor: THREE.ColorRepresentation = 0x639BFA;
    private readonly overFaceColor: THREE.ColorRepresentation = 0xffff00;
    private readonly selectedFaceColor: THREE.ColorRepresentation = 0xff0000;

    constructor(editMesh: EditMesh) {
        super(editMesh);
        
        this.currentMeshTool = new MoveMeshTool(this);
    }

    enter(): void {
        this.faces = this.mesh;
        this.faces.layers.enable(1);
    }

    exit(): void {
        this.faces = undefined;
    }

    overMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this.faces) return;

        this.vertexInfos = [];

        this.currentIntersection = this.meshRayCaster.selectFace(normalizedMouseCoordinates, this.faces);

        if (this.currentIntersection && this.currentIntersection.face != undefined) {
            this.setVertexInfos(this.currentIntersection.face.a);
            this.setVertexInfos(this.currentIntersection.face.b);
            this.setVertexInfos(this.currentIntersection.face.c);
        }
    }

    selectMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this.faces) return;
        this.currentIntersection = this.meshRayCaster.selectFace(normalizedMouseCoordinates, this.faces);
    }

    updateGeometry(): void {
        //
    }
}
