import { GLTF, GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { Completer } from './completer';
import { Indexer } from './types';

export interface GLTFModel {
    url: string;
    gltf?: GLTF;
    size?: number;
    animations?: Indexer<THREE.AnimationClip>;
}

export class UtilsGLTF {
    static setGLTFShadow(gltf: GLTF, useShadow: boolean = true, width: number = 2048, height: number = 2048, bias: number = -.003): void {
        gltf.scene.traverse((child: THREE.Object3D) => {
            if ((child as THREE.Mesh).isMesh) {
                const m: THREE.Mesh = child as THREE.Mesh;
                m.receiveShadow = useShadow;
                m.castShadow = useShadow;
            }
            if (((child as THREE.Light)).isLight) {
                const l: THREE.Light = child as THREE.Light;
                l.castShadow = useShadow;
                l.shadow.bias = bias;
                l.shadow.mapSize.width = width;
                l.shadow.mapSize.height = height;
            }
        });
    }

    static loadModels(loadingManager: THREE.LoadingManager, models: GLTFModel[]): void {
        const gltfLoader: GLTFLoader = new GLTFLoader(loadingManager);
        for (const model of models) {
            gltfLoader.load(model.url, (gltf: GLTF) => {
                model.gltf = gltf;
            });
        }
    }

    static async loadGltf(url: string): Promise<GLTF | undefined> {
        const completer: Completer<GLTF> = new Completer<GLTF>();

        const loader: GLTFLoader = new GLTFLoader();
        loader.load(
            url,
            (gltf: GLTF) => { completer.complete(gltf); },
            (xhr: ProgressEvent<EventTarget>) => { console.log(`${(xhr.loaded / xhr.total) * 100} % loaded`); },
            (error: ErrorEvent) => { console.log(error); }
        );

        const result: GLTF | undefined = await completer.promise;

        return result;
    }
}