import * as React from "react";
import {
  ChakraProvider,
  theme,
} from "@chakra-ui/react";
import { BaseDrawer } from "./components/base_drawer";
import { SceneComponent } from "./components/base_scene";

export const App = (): React.ReactElement => {
  return (
    <ChakraProvider theme={theme}>
        <BaseDrawer/>
        <SceneComponent/>
    </ChakraProvider>
  );
};
