import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from '../../api/engine/a_scene';

export class InteractiveLinesScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;
    arrowHelper!: THREE.ArrowHelper;
    sphereInter!: THREE.Mesh;
    parentTransform!: THREE.Object3D;

    pointer: THREE.Vector2 = new THREE.Vector2();
    radius: number = 100;
    theta: number = 0;
    raycaster!: THREE.Raycaster;

    constructor() {
        super();
    }

    setup(): void {

        this.setupScene();

        const geometry = new THREE.SphereGeometry(5);
        const material = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        this.sphereInter = new THREE.Mesh(geometry, material);
        this.sphereInter.visible = false;
        this.add(this.sphereInter);

        const lineGeometry = new THREE.BufferGeometry();
        const points = [];

        const point = new THREE.Vector3();
        const direction = new THREE.Vector3();

        for (let i = 0; i < 100; i++) {

            direction.x += 0.1; //Math.random() - 0.5;
            direction.y += 0.1; //Math.random() - 0.5;
            direction.z += 0.1; //Math.random() - 0.5;
            direction.normalize().multiplyScalar(1);

            point.add(direction);
            points.push(point.x, point.y, point.z);
        }

        lineGeometry.setAttribute('position', new THREE.Float32BufferAttribute(points, 3));

        this.parentTransform = new THREE.Object3D();
        this.parentTransform.position.x = Math.random() * 40 - 20;
        this.parentTransform.position.y = Math.random() * 40 - 20;
        this.parentTransform.position.z = Math.random() * 40 - 20;

        this.parentTransform.rotation.x = Math.random() * 2 * Math.PI;
        this.parentTransform.rotation.y = Math.random() * 2 * Math.PI;
        this.parentTransform.rotation.z = Math.random() * 2 * Math.PI;

        this.parentTransform.scale.x = Math.random() + 0.5;
        this.parentTransform.scale.y = Math.random() + 0.5;
        this.parentTransform.scale.z = Math.random() + 0.5;

        for (let i = 0; i < 50; i++) {

            const lineMaterial = new THREE.LineBasicMaterial({ color: Math.random() * 0xffffff });

            // const object = new THREE.Line(lineGeometry, lineMaterial);
            // const object = new THREE.LineSegments(lineGeometry, lineMaterial);

            let object;
            if (Math.random() > 0.5) {
                object = new THREE.Line(lineGeometry, lineMaterial);
            }
            else {
                object = new THREE.LineSegments(lineGeometry, lineMaterial);
            }

            object.position.x = Math.random() * 400 - 200;
            object.position.y = Math.random() * 400 - 200;
            object.position.z = Math.random() * 400 - 200;

            object.rotation.x = Math.random() * 2 * Math.PI;
            object.rotation.y = Math.random() * 2 * Math.PI;
            object.rotation.z = Math.random() * 2 * Math.PI;

            object.scale.x = Math.random() + 0.5;
            object.scale.y = Math.random() + 0.5;
            object.scale.z = Math.random() + 0.5;

            this.parentTransform.add(object);

        }

        this.add(this.parentTransform);

        this.raycaster = new THREE.Raycaster();
        if (this.raycaster.params) {
            this.raycaster.params.Points = { threshold: 3 };
        }

        document.addEventListener('pointermove', this.onPointerMove.bind(this));
    }

    private setupScene(): void {
        this.background = new THREE.Color(0xf0f0f0);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 1000);
        this.perspectiveCamera.position.set(2, 2, 2);
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        // Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
        this.controls.target.set(0, 1, 0);
        this.controls.update();

        const axesHelper = new THREE.AxesHelper(1);
        this.add(axesHelper);
    }

    onPointerMove(event: PointerEvent): void {
        this.pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
        this.pointer.y = - (event.clientY / window.innerHeight) * 2 + 1;
    }

    update(): void {
        this.theta += 0.1;

        this.mainCamera.position.x = this.radius * Math.sin(THREE.MathUtils.degToRad(this.theta));
        this.mainCamera.position.y = this.radius * Math.sin(THREE.MathUtils.degToRad(this.theta));
        this.mainCamera.position.z = this.radius * Math.cos(THREE.MathUtils.degToRad(this.theta));
        this.mainCamera.lookAt(this.position);

        this.mainCamera.updateMatrixWorld();

        // find intersections
        this.raycaster.setFromCamera(this.pointer, this.mainCamera);
        const intersects = this.raycaster.intersectObjects(this.parentTransform.children, true);
        if (intersects.length > 0) {
            this.sphereInter.visible = true;
            this.sphereInter.position.copy(intersects[0].point);
        } else {
            this.sphereInter.visible = false;
        }
    }
}