import { GUI } from 'dat.gui';
import * as THREE from 'three';
import { ToneMapping } from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js';
import { GLTF } from 'three/examples/jsm/loaders/GLTFLoader';
import { degToRad } from 'three/src/math/MathUtils';
import { GLTFModel, UtilsGLTF } from '../../api/utils/gltf';
import { AScene } from '../../api/engine/a_scene';
import { Indexer } from '../../api/utils/types';

const DEBUG: boolean = false;

export class ObjectSelectorScene extends AScene {

    get controls(): OrbitControls {
        return super.controls!;
    }
    set controls(controls: OrbitControls) {
        super.controls = controls;
    }

    transformControls!: TransformControls;

    pointer: THREE.Vector2 = new THREE.Vector2();
    raycaster: THREE.Raycaster = new THREE.Raycaster();
    intersects: THREE.Object3D[] = [];

    models: Indexer<GLTFModel> = {
        helmet: { url: "/assets/helmet/DamagedHelmet.gltf" },
    };
    gui: GUI = new GUI();

    constructor() {
        super();
    }

    setup(): void {

        // Renderer
        this.setupRenderer();

        // Environment
        this.setupEnvironment();

        window.addEventListener('pointerdown', this.onPointerDown.bind(this));
        window.addEventListener('pointermove', this.onPointerMove.bind(this));
        window.addEventListener('pointerup', this.onPointerUp.bind(this));

        this.raycaster.layers.set(1);

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.1);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(1, 5, 2);
        this.add(directionalLight);

        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 512;
        directionalLight.shadow.mapSize.height = 512;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 100;

        if (DEBUG) {
            const directionalLightHelper: THREE.DirectionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 0.5);
            this.add(directionalLightHelper);

            const helper: THREE.CameraHelper = new THREE.CameraHelper(directionalLight.shadow.camera);
            this.add(helper);
        }

        // Base camera
        const perspectiveCamera: THREE.PerspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        perspectiveCamera.position.x = 3;
        perspectiveCamera.position.y = 3;
        perspectiveCamera.position.z = 3;
        this.add(perspectiveCamera);

        this.mainCamera = perspectiveCamera;

        // Controls
        this.controls = new OrbitControls(perspectiveCamera, this.engine.renderer.domElement);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;
        this.controls.target.set(0, 1.5, 0);

        // TransformControls
        this.transformControls = new TransformControls(this.mainCamera, this.engine.renderer.domElement);
        this.transformControls.translationSnap = 0;
        this.transformControls.rotationSnap = degToRad(0);
        this.transformControls.addEventListener("objectChange", () => {
            if (DEBUG) {
                console.debug("dragging", this.transformControls.dragging);
                console.debug("axis", this.transformControls.axis);
            }
        });
        this.transformControls.addEventListener("mouseDown", () => {
            this.controls.enabled = false;
        });
        this.transformControls.addEventListener("mouseUp", () => {
            this.controls.enabled = true;
        });
        this.add(this.transformControls);

        // Objects
        const groundGeometry: THREE.PlaneGeometry = new THREE.PlaneGeometry(10, 10);
        const groundMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const meshGround: THREE.Mesh = new THREE.Mesh(groundGeometry, groundMaterial);
        meshGround.name = "ground";
        meshGround.layers.enable(1);
        meshGround.rotateX(degToRad(-90));
        meshGround.receiveShadow = true;
        this.add(meshGround);

        const boxGeometry: THREE.BoxGeometry = new THREE.BoxGeometry(1, 1, 1);
        const boxMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: 0x00ffe1 });
        const boxMesh: THREE.Mesh = new THREE.Mesh(boxGeometry, boxMaterial);
        boxMesh.name = "box";
        boxMesh.layers.enable(1);
        boxMesh.position.x = 2;
        boxMesh.position.y = 0.5;
        boxMesh.castShadow = true;
        boxMesh.receiveShadow = true;
        this.add(boxMesh);

        this.engine.loadingManager.onLoad = this.initModel.bind(this);
        UtilsGLTF.loadModels(this.engine.loadingManager, Object.values(this.models));
    }

    initModel(): void {
        const gltfScene: GLTF | undefined = this.models.helmet.gltf;
        if (gltfScene) {
            gltfScene.scene.name = "gltf";
            gltfScene.scene.layers.enable(1);
            gltfScene.scene.children[0].layers.enable(1);
            UtilsGLTF.setGLTFShadow(gltfScene);
            gltfScene.scene.position.y = 1;
            this.add(gltfScene.scene);
            this.transformControls.attach(gltfScene.scene);
        }

        // GUI
        const transformControlsFolder: GUI = this.gui.addFolder('TransformControls');
        transformControlsFolder.add(this.transformControls, 'enabled', this.transformControls.enabled);
        transformControlsFolder.add(this.transformControls, 'showX', this.transformControls.showX);
        transformControlsFolder.add(this.transformControls, 'showY', this.transformControls.showY);
        transformControlsFolder.add(this.transformControls, 'showY', this.transformControls.showZ);
        transformControlsFolder.add(this.transformControls, 'size', this.transformControls.size);
        transformControlsFolder.add(this.transformControls, 'mode', ['translate', 'rotate', 'scale']);
        transformControlsFolder.add(this.transformControls, 'space', ['world', 'local']);
        transformControlsFolder.add(this.transformControls, 'translationSnap', 0, 2, 1);
        transformControlsFolder.add(this.transformControls, 'rotationSnap', 0, degToRad(90), degToRad(1));
        transformControlsFolder.open();
    }

    private setupEnvironment(): void {
        const textureLoader: THREE.TextureLoader = new THREE.TextureLoader();
        //https://dl.polyhaven.org/file/ph-assets/HDRIs/extra/Tonemapped%20JPG/venice_sunset.jpg
        const textureEquirec: THREE.Texture = textureLoader.load('/assets/environment/venice_sunset.jpg');
        textureEquirec.mapping = THREE.EquirectangularReflectionMapping;
        textureEquirec.encoding = THREE.sRGBEncoding;

        this.background = textureEquirec;
        this.environment = textureEquirec;
    }

    private setupRenderer(): void {
        const params: {
            exposure: number,
            toneMapping: ToneMapping
        } = {
            exposure: 2.2,
            toneMapping: THREE.ACESFilmicToneMapping
        };

        this.engine.renderer.toneMapping = params.toneMapping;
        this.engine.renderer.toneMappingExposure = params.exposure;

        this.engine.renderer.shadowMap.enabled = true;
        // this.engine.renderer.shadowMap.type = THREE.BasicShadowMap; 
        // this.engine.renderer.shadowMap.type = THREE.PCFShadowMap;
        // this.engine.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        this.engine.renderer.shadowMap.type = THREE.VSMShadowMap;
    }

    isMouseDown: boolean = false;
    onPointerDown(event: PointerEvent): void {
        this.isMouseDown = true;

        if (this.transformControls.dragging) return;

        if (event.button === 0) {
            this.transformControls.attach(this.intersects[0]);
        }
    }

    onPointerUp(): void {
        this.isMouseDown = false;
    }

    onPointerMove(event: PointerEvent): void {

        if (this.transformControls.dragging) return;

        // calculate pointer position in normalized device coordinates
        // (-1 to +1) for both components
        this.pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
        this.pointer.y = - (event.clientY / window.innerHeight) * 2 + 1;

        // update the picking ray with the camera and pointer position
        this.raycaster.setFromCamera(this.pointer, this.mainCamera);

        // calculate objects intersecting the picking ray
        const intersects: THREE.Intersection[] = this.raycaster.intersectObjects(this.children, true);
        /*
            An intersection has the following properties :
                - object : intersected object (THREE.Mesh)
                - distance : distance from camera to intersection (number)
                - face : intersected face (THREE.Face3)
                - faceIndex : intersected face index (number)
                - point : intersection point (THREE.Vector3)
                - uv : intersection point in the object's UV coordinates (THREE.Vector2)
        */

        this.intersects = [];
        for (let i: number = 0; i < intersects.length; i++) {
            const item: THREE.Object3D = intersects[i].object;
            if (item.layers.isEnabled(1)) {
                this.intersects.push(item);
            }
        }

        if (DEBUG) {
            console.debug(this.intersects.map((m: THREE.Object3D) => m.name.length > 0 ? `${m.name}(${m.layers.mask})` : m.type));
        }
    }

    update(): void {
        //
    }

    dispose(): void {
        this.gui.destroy();
    }
}
