export class UtilsArray {

    static removeArrayElement<T>(array: T[], element: T): void {
        const ndx: number = array.indexOf(element);
        if (ndx >= 0) {
            array.splice(ndx, 1);
        }
    }

    static addArray(arrayA: number[], arrayB: number[]): number[] {
        return arrayA.map(function (x: number, index: number) {
            return arrayB[index] + x;
        });
    }

    static mulitplayArray(arrayA: number[], arrayB: number[]): number[] {
        return arrayA.map(function (x: number, index: number) {
            return arrayB[index] * x;
        });
    }

    static sqrtArray(arrayA: number[]): number[] {
        return arrayA.map(function (x: number, index: number) {
            return Math.sqrt(arrayA[index]);
        });
    }

    static convert(points: number[][]): number[] {
        const result: number[] = [];
        for (const a of points) {
            result.push(...a);
        }

        return result;
    }
}