import * as THREE from "three";

export class UtilsPositionner {
    static createSpiral(itemCreator: () => THREE.Vector3): void {
        // Params
        const numItems: number = 28;
        const arc: number = 10;
        const b: number = 10 / (2 * Math.PI);
        let r: number = 10;
        let phi: number = r / b;

        // Position numItems in a spiral.
        const base: THREE.Object3D = new THREE.Object3D();
        const offset: THREE.Object3D = new THREE.Object3D();
        base.add(offset);
        for (let i: number = 0; i < numItems; ++i) {
            // Get random item position
            const position: THREE.Vector3 = itemCreator();

            // Position it
            base.rotation.y = phi;
            offset.position.x = r;
            offset.updateWorldMatrix(true, false);
            offset.getWorldPosition(position);
            phi += arc / r;
            r = b * phi;
        }
    }
}