import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { MouseManager } from '../../api/engine/mouse_manager';
import { ObjectSelector } from '../../api/engine/object_selector';
import { AScene } from '../../api/engine/a_scene';
import { MeshCreator } from '../../api/mesh/creators/mesh_creator';
import { RayHelper } from './ray_helper';

export class BaseMathScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;
    objectSelector!: ObjectSelector;

    private sphere!: THREE.Sphere;
    private sphereHelper!: THREE.Mesh;
    private helperMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({
        color: 0x3F78DB,
        opacity: 0.5,
        transparent: true,
    });

    rayHelper!: RayHelper;
    sphereObject1!: THREE.Mesh;

    constructor() {
        super();
    }

    setup(): void {
        this.setupScene();

        const center = new THREE.Vector3(3, 0, 0);
        const radius = 1;
        this.sphere = new THREE.Sphere(center, radius);

        this.sphereHelper = MeshCreator.sphere({
            radius: radius,
        });
        this.sphereHelper.position.copy(center);
        this.sphereHelper.material = this.helperMaterial;
        this.add(this.sphereHelper);

        this.sphereObject1 = MeshCreator.sphere({
            radius: 0.1,
        });
        this.add(this.sphereObject1);

        this.rayHelper = new RayHelper();
        this.add(this.rayHelper);

        this.updateObjects();

        MouseManager.instance.mouseDrag.subscribe(this.updateObjects.bind(this));
    }

    private updateObjects(): void {
        this.rayHelper.intersectSphere(this.sphere);
        // this.rayHelper.closestPointToPoint(this.sphereObject1.position);
        if (this.objectSelector.selection === this.sphereHelper) {
            this.sphere.center = this.sphereHelper.position;
        }
        if (this.objectSelector.selection === this.sphereObject1) {
            //
        }
    }

    private setupScene(): void {
        this.background = new THREE.Color(0x151F30);

        // Base camera
        this.perspectiveCamera = new THREE.PerspectiveCamera(75, this.engine.aspect, 0.1, 100);
        this.perspectiveCamera.position.x = 3;
        this.perspectiveCamera.position.y = 3;
        this.perspectiveCamera.position.z = 3;
        this.add(this.perspectiveCamera);

        this.mainCamera = this.perspectiveCamera;

        //Light
        const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.3);
        this.add(ambientLight);

        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(2, 5, 3);
        this.add(directionalLight);

        // Controls
        this.controls = new OrbitControls(this.perspectiveCamera, this.engine.canvas);
        this.controls.enableDamping = true;
        this.controls.autoRotate = false;

        //Origin
        const axesHelper = new THREE.AxesHelper(1);
        axesHelper.renderOrder = 10;
        this.add(axesHelper);

        this.objectSelector = new ObjectSelector(this);
    }

    update(): void {
        //
    }
}