import * as THREE from "three";
import { Face } from "./face";
import { GeometryData } from "./geometry_data";
import { VertexNode } from "./vertex_node";

export class GeometryEditor {
  private _geometry: THREE.BufferGeometry;

  private _vertices: VertexNode[] = [];
  public get vertices(): VertexNode[] {
    return this._vertices;
  }

  private _faces: Face[] = [];
  public get faces(): Face[] {
    return this._faces;
  }

  constructor(geometry: THREE.BufferGeometry) {
    this._geometry = geometry;

    this.makeEmpty();
    this.fillVertices();
    this.fillFaces();
  }

  private makeEmpty(): GeometryEditor {
    this._faces = [];
    this._vertices = [];

    return this;
  }

  private fillVertices(): GeometryEditor {
    const attribute = this._geometry.attributes.position;

    if (attribute !== undefined) {
      for (let i = 0, l = attribute.count; i < l; i++) {
        const point = new THREE.Vector3();

        point.fromBufferAttribute(attribute, i);
        // .applyMatrix4(node.matrixWorld)

        this._vertices.push(new VertexNode(point));
      }
    }

    return this;
  }

  private fillFaces(): GeometryEditor {
    const indices: Uint16Array = this.getMeshIndices() as Uint16Array;

    if (indices === null) return this;

    for (let i = 0, l = indices.length; i < l; i += 3) {
      const face: Face = Face.create(
        this._vertices[indices[i]],
        this._vertices[indices[i + 1]],
        this._vertices[indices[i + 2]]
      ) as Face;
      this._faces.push(face);
    }

    return this;
  }

  getGeometryData(): GeometryData {
    const vertices: Float32Array = this.getVertices();
    const indices: Uint16Array = this.getIndices() as Uint16Array;

    const geometryData = {
      vertices: vertices,
      indices: indices,
    };

    return geometryData;
  }

  getGeometry(): THREE.BufferGeometry {
    const geometryData = this.getGeometryData();
    const result = new THREE.BufferGeometry();
    result.setAttribute('position', new THREE.BufferAttribute(geometryData.vertices, 3));
    result.setIndex(new THREE.BufferAttribute(geometryData.indices, 1));
    return result;
  }

  getVertexById(id: number): VertexNode {
    return this._vertices[id];
  }

  private getVertices(): Float32Array {
    const verticesNumbers: number[] = new Array<number>();

    for (let i = 0, l = this._vertices.length; i < l; i++) {
      verticesNumbers.push(...this._vertices[i].point.toArray());
    }

    const vertices: Float32Array = new Float32Array(verticesNumbers);

    return vertices;
  }

  private getIndices(): Uint16Array | null {
    if (this._faces.length === 0) return null;
    const indicesNumbers: number[] = new Array<number>();

    for (let f = 0, l = this._faces.length; f < l; f++) {
      const vertexNodes: VertexNode[] = this._faces[f].getVertexNodes();

      for (let v = 0, l = vertexNodes.length; v < l; v++) {
        const index = this._vertices.indexOf(vertexNodes[v]);
        indicesNumbers.push(index);
      }
    }

    const indices: Uint16Array = new Uint16Array(indicesNumbers);
    return indices;
  }

  private getMeshVertices(): Float32Array {
    const verticesAttribute = this._geometry.attributes.position;
    const vertices: Float32Array = new Float32Array(verticesAttribute.array);
    return vertices;
  }

  private getMeshIndices(): Uint16Array | null {
    const indicesAttribute: THREE.Uint16BufferAttribute = this._geometry.getIndex() as THREE.Uint16BufferAttribute;
    if (indicesAttribute === null) return null;

    const indices: Uint16Array = new Uint16Array(indicesAttribute.array);
    return indices;
  }

  addVertexFromPoint(point: THREE.Vector3): VertexNode {
    const vertexNode = new VertexNode(point);
    this._vertices.push(vertexNode);
    return vertexNode;
  }

  addFaceFromVertices(vertexNode0: VertexNode, vertexNode1: VertexNode, vertexNode2: VertexNode): Face {
    const face: Face = Face.create(vertexNode0, vertexNode1, vertexNode2) as Face;
    this._faces.push(face);
    return face;
  }
}
