import * as THREE from 'three';

export class VectorHelper {
    private length: number = 1;
    private color: THREE.ColorRepresentation = 0x0;
    private arrowHelper: THREE.ArrowHelper;
    private origin: THREE.Vector3 = new THREE.Vector3(0, 0, 0);
    private target: THREE.Vector3 = new THREE.Vector3(0, 0, 0);
    private direction: THREE.Vector3 = new THREE.Vector3(0, 0, 0);

    get objet3D(): THREE.Object3D {
        return this.arrowHelper;
    }

    constructor() {
        this.arrowHelper = new THREE.ArrowHelper(this.direction.normalize(), this.origin, this.length, this.color);
    }

    setOrigin(origin: THREE.Vector3): void {
        this.origin = origin;

        this.update();
    }

    setTarget(target: THREE.Vector3): void {
        this.target = target;
        this.update();
    }

    update(): void {
        this.arrowHelper.position.copy(this.origin);

        const direction = this.target.clone().sub(this.origin).normalize();
        this.arrowHelper.setDirection(direction);

        this.arrowHelper.setLength(this.origin.distanceTo(this.target));
    }
}
