import { Component } from "../../src/api/component";
import { CoroutineRunner, waitSeconds } from "../../src/api/coroutine_runner";
import { GameObject } from "../../src/api/game_object";
import { GameObjectManager } from "../../src/api/game_object_manager";
import { globalsCustom, kForward } from "../globals";
import { InputManager } from "../../../../api/engine/input_manager";
import { Note } from "./note";
import { SkinInstance } from "../../src/api/skin_instance";
import { StateDisplayHelper } from "./state_display_helper";
import { UtilsMath } from "../../../../api/utils/math";
import { globals } from "../../src/api/globals";
import { GLTFModel } from "../../../../api/utils/gltf";

export class Player extends Component {
  turnSpeed: number;

  offscreenTimer: number = 0;
  maxTimeOffScreen: number = 3;

  runner: CoroutineRunner;

  text: StateDisplayHelper;
  skinInstance: SkinInstance;

  constructor(gameObject: GameObject) {
    super(gameObject);

    const model: GLTFModel = globalsCustom.models.knight;
    globalsCustom.playerRadius = model.size! / 2;
    this.text = gameObject.addComponent(StateDisplayHelper, model.size);
    this.skinInstance = gameObject.addComponent(SkinInstance, model);
    this.skinInstance.setAnimation("Run");
    this.turnSpeed = globalsCustom.moveSpeed / 4;
    this.runner = new CoroutineRunner();


    function* emitNotes(): any {
      for (; ;) {
        yield waitSeconds(UtilsMath.rand(0.5, 1));
        const noteGO: GameObject = GameObjectManager.instance.createGameObject(
          globals.scene,
          "note"
        );
        noteGO.transform.position.copy(gameObject.transform.position);
        noteGO.transform.position.y += 5;
        noteGO.addComponent(Note);
      }
    }

    this.runner.add(emitNotes());
  }

  update(): void {
    this.runner.update();
    const { deltaTime } = globals;
    const { moveSpeed, cameraInfo } = globalsCustom;

    const { transform } = this.gameObject;

    const delta: number =
      (InputManager.instance.keys.left.down ? 1 : 0) +
      (InputManager.instance.keys.right.down ? -1 : 0);
    transform.rotation.y += this.turnSpeed * delta * deltaTime;
    transform.translateOnAxis(kForward, moveSpeed * deltaTime);

    const { frustum } = cameraInfo;
    if (frustum.containsPoint(transform.position)) {
      this.offscreenTimer = 0;
    } else {
      this.offscreenTimer += deltaTime;
      if (this.offscreenTimer >= this.maxTimeOffScreen) {
        transform.position.set(0, 0, 0);
      }
    }
  }
}
