import * as THREE from 'three';

export type VertexInfo = { index: number; position: THREE.Vector3; };

export class UtilsMesh {
    static moveVertices(mesh: THREE.Mesh, vertexInfos: VertexInfo[], deltaMove: THREE.Vector3): void {
        for (let i = 0; i < vertexInfos.length; i++) {
            const vertex = new THREE.Vector3().addVectors(vertexInfos[i].position, deltaMove);
            mesh.geometry.attributes.position.setXYZ(vertexInfos[i].index, vertex.x, vertex.y, vertex.z);

            // Todo > check editMesh
            // this.addDebugPoint(mesh.localToWorld(vertex.clone()), 0xffff00);
        }
    }

    static getEdgeVertexInfos(vertex: THREE.Vector3, meshPositions: THREE.BufferAttribute): VertexInfo {
        let index = -1;
        for (let i = 0; i < meshPositions.count; i++) {
            const currentVertex = new THREE.Vector3().fromArray(meshPositions.array, i * 3);
            if (vertex.x === currentVertex.x && vertex.y === currentVertex.y && vertex.z === currentVertex.z) {
                index = i;
                break;
            }
        }
        const newVertex = new THREE.Vector3().fromArray(meshPositions.array, index * 3);
        return { index, position: newVertex };
    }
}