import { GUI, GUIController } from 'dat.gui';

export enum GUIParamsItemType {
    number,
    boolean,
    stringList,
    numberList,
    object,
    color
}

/*
    Use according to GUI signatures :

    number: add(target: Object, propName:string, min?: number, max?: number, step?: number): GUIController;
    boolean: add(target: Object, propName:string, status: boolean): GUIController;
    stringList: add(target: Object, propName:string, items:string[]): GUIController;
    numberList: add(target: Object, propName:string, items:number[]): GUIController;
    object: add(target: Object, propName:string, items:Object): GUIController;

    addColor(target: Object, propName:string): GUIController;
*/
export interface GuiParametersItemType {
    key: string,
    type: GUIParamsItemType,
    min?: number,
    max?: number,
    step?: number,
    status?: boolean,
    itemsString?: string[],
    itemsNumber?: number[],
    itemsObject?: { [key: string]: unknown },//object
}

// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface TargetParameters {
    //
}

//Todo: externalize in a agnostic file as this can be used for other things needed by GUI
export interface GuiParameters {
    name: string,
    // eslint-disable-next-line @typescript-eslint/ban-types
    target: {},//object
    controllers: GuiParametersItemType[],
}

export class UtilsGUI {
    static fillFolderWithParameters(gui: GUI, guiParameters: GuiParameters, updater: () => void): void {
        const folder: GUI = gui.addFolder(guiParameters.name);

        for (const controller of guiParameters.controllers) {
            let guiController: GUIController;
            switch (controller.type) {
                case GUIParamsItemType.number:
                    guiController = folder.add(guiParameters.target,
                        controller.key,
                        controller.min,
                        controller.max,
                        controller.step);
                    break;
                case GUIParamsItemType.boolean:
                    guiController = folder.add(guiParameters.target,
                        controller.key,
                        controller.status ?? false);
                    break;
                case GUIParamsItemType.stringList:
                    guiController = folder.add(guiParameters.target,
                        controller.key,
                        controller.itemsString ?? []);
                    break;
                case GUIParamsItemType.numberList:
                    guiController = folder.add(guiParameters.target,
                        controller.key,
                        controller.itemsNumber ?? []);
                    break;
                case GUIParamsItemType.object:
                    guiController = folder.add(guiParameters.target,
                        controller.key,
                        controller.itemsObject ?? []);
                    break;
                case GUIParamsItemType.color:
                    guiController = folder.addColor(guiParameters.target, controller.key);
                    break;
            }

            guiController.onChange(updater);
        }

        folder.open();
    }
}