export class UtilsMath {
    static rand(min: number, max?: number): number {
        if (max === undefined) {
            max = min;
            min = 0;
        }
        return Math.random() * (max - min) + min;
    }

    // min and max included 
    static randomIntFromInterval(min: number, max: number): number {
        return Math.floor(Math.random() * (max - min + 1) + min);
    }

    // keeps v between -min and +min
    static minMagnitude(v: number, min: number): number {
        return Math.abs(v) > min ? min * Math.sign(v) : v;
    }

    static randomMultipleOf(multipleOf: number, max: number): number {
        const m = Math.floor(max / multipleOf);
        return ((UtilsMath.randomIntFromInterval(0, m) * multipleOf) % max);
    }
}