import * as THREE from 'three';
import { MouseManager } from '../../api/engine/mouse_manager';
import { MeshCreator } from "../../api/mesh/creators/mesh_creator";
import { Point } from "../../api/mesh/primitives/point";
import { LineHelper } from './line_helper';

export class RayHelper extends THREE.Object3D {
    private target!: THREE.Mesh;
    private origin!: THREE.Mesh;
    private ray!: THREE.Ray;
    private intersectPoint!: Point;
    private directionHelper!: THREE.ArrowHelper;
    private lineHelper!: LineHelper;

    constructor() {
        super();

        this.origin = MeshCreator.sphere({
            radius: 0.05, widthSegments: 8,
            heightSegments: 8
        });
        this.origin.position.copy(new THREE.Vector3(0, 0, 1.5));
        this.origin.material = new THREE.MeshStandardMaterial({
            color: 0xffff00,
        });
        this.add(this.origin);

        this.target = MeshCreator.sphere({
            radius: 0.03, widthSegments: 2,
            heightSegments: 2
        });
        this.target.position.copy(new THREE.Vector3(1, 0, 0.9));
        this.target.material = new THREE.MeshStandardMaterial({
            color: 0xffff00,
        });
        this.add(this.target);

        this.intersectPoint = new Point({
            color: 0xffffff
        });
        this.intersectPoint.position.copy(this.origin.position);
        this.add(this.intersectPoint);

        this.ray = new THREE.Ray(this.origin.position, this.getDirection(this.origin.position, this.target.position));

        const direction = this.ray.direction;
        const origin = this.ray.origin;
        const length = 1;
        const color = 0xffff00;
        this.directionHelper = new THREE.ArrowHelper(direction, origin, length, color);
        this.add(this.directionHelper);

        MouseManager.instance.mouseDrag.subscribe(this.updateObjects.bind(this));

        //Temps position from single point
        this.lineHelper = new LineHelper(this.origin.position, this.origin.position, true, 0xffffff);
        this.add(this.lineHelper);
    }

    private updateObjects(): void {
        const direction = this.getDirection(this.origin.position, this.target.position);
        this.ray.set(this.origin.position, direction);
        this.directionHelper.setDirection(direction);
        this.directionHelper.position.copy(this.origin.position);
        this.directionHelper.setLength(this.origin.position.distanceTo(this.target.position));
    }

    private getDirection(origin: THREE.Vector3, target: THREE.Vector3): THREE.Vector3 {
        return new THREE.Vector3().subVectors(target, origin).normalize();
    }

    intersectSphere(sphere: THREE.Sphere): void {
        this.updateObjects();

        const intersect = this.ray.intersectSphere(sphere, new THREE.Vector3());
        if (intersect) {
            this.intersectPoint.position.copy(intersect);
            this.lineHelper.setPoints(this.target.position, intersect);
            this.lineHelper.visible = true;
        } else {
            this.intersectPoint.position.copy(this.origin.position);
            this.lineHelper.visible = false;
        }
    }

    closestPointToPoint(point: THREE.Vector3): void {
        this.updateObjects();

        const closestPoint = this.ray.closestPointToPoint(point, new THREE.Vector3());
        if (closestPoint) {
            this.intersectPoint.position.copy(closestPoint);
            this.lineHelper.setPoints(point, closestPoint);
            this.lineHelper.visible = true;
        } else {
            this.intersectPoint.position.copy(this.origin.position);
            this.lineHelper.visible = false;
        }
    }
}