import { ICustomCreator } from "../creators/custom_mesh_creator";
import { GeometryCreator } from "../creators/geometry_creator";
import { GuiParameters, GUIParamsItemType } from "../../utils/gui";
import { GeometryParameters } from "./primitives";

export const DefaultBoxGeometryParameters = {
    width: 2,
    height: 2,
    depth: 2,
    widthSegments: 1,
    heightSegments: 1,
    depthSegments: 1,

    wireframe: false, //Todo : externalize wireframe
};

export interface BoxGeometryParameters extends GeometryParameters {
    width: number,
    height: number,
    depth: number,
    widthSegments: number,
    heightSegments: number,
    depthSegments: number,

    wireframe: boolean; //Todo : externalize wireframe
}

export const getBoxGeometryGUIParameters = (parameters: BoxGeometryParameters = DefaultBoxGeometryParameters): GuiParameters => {
    const result: GuiParameters = {
        name: 'Box',
        target: parameters,
        controllers: [
            {
                key: 'width',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'height',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'depth',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'heightSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'widthSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'depthSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'wireframe',
                type: GUIParamsItemType.boolean,
                status: parameters.wireframe
            },
        ],
    };

    return result;
};

export class BoxGeometryCustomCreator implements ICustomCreator {
    geometryParameters: BoxGeometryParameters;
    geometryGUIParameters: GuiParameters;

    constructor(parameters: BoxGeometryParameters = DefaultBoxGeometryParameters) {
        this.geometryParameters = { ...parameters };
        this.geometryGUIParameters = getBoxGeometryGUIParameters(this.geometryParameters);
    }

    geometryCreator(parameters: BoxGeometryParameters): THREE.BufferGeometry {
        const geometry = GeometryCreator.box(parameters);
        // geometry.translate(0, parameters.height / 2, 0);
        return geometry;
    }
}