import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { AScene } from '../../api/engine/a_scene';
import { hasGeometry } from '../../api/utils/geometry';

export class EditMeshEdgeSelectScene extends AScene {

    perspectiveCamera!: THREE.PerspectiveCamera;

    constructor() {
        super();
    }

    setup(): void {
        let intersected: THREE.Intersection | null;
        const mouse = new THREE.Vector2();
        this.perspectiveCamera = new THREE.PerspectiveCamera(
            45,
            window.innerWidth / window.innerHeight,
            0.1,
            300
        );
        this.perspectiveCamera.position.set(2, 5, 3);
        this.mainCamera = this.perspectiveCamera;

        const raycaster = new THREE.Raycaster();

        const geometry = new THREE.BoxGeometry();
        const material = new THREE.MeshBasicMaterial({
            color: new THREE.Color("white")
        });

        const mesh = new THREE.Mesh(geometry, material);
        this.add(mesh);

        const edgesGeometry = new THREE.EdgesGeometry(mesh.geometry, 40);

        const colors = [];
        for (let i = 0; i < edgesGeometry.attributes.position.count; i++) {
            colors.push(0, 0, 0);
        }
        edgesGeometry.setAttribute(
            "color",
            new THREE.Float32BufferAttribute(colors, 3)
        );
        const edgesMaterial = new THREE.LineBasicMaterial({
            vertexColors: true
        });

        const line = new THREE.LineSegments(edgesGeometry, edgesMaterial);

        mesh.add(line);

        const setLineColor = (color: THREE.Color): void => {
            const { index, object } = intersected as THREE.Intersection;
            if (hasGeometry(object) && index !== undefined) {
                object.geometry.attributes.color.setXYZ(index, color.r, color.g, color.b);
                object.geometry.attributes.color.setXYZ(index + 1, color.r, color.g, color.b);
                object.geometry.attributes.color.needsUpdate = true;
            }
        };

        const onPointerMove = (event: MouseEvent): void => {
            event.preventDefault();

            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            raycaster.setFromCamera(mouse, this.perspectiveCamera);

            //for thin lines
            raycaster.params.Line = { threshold: 0.05 };

            const intersects: THREE.Intersection[] | null = raycaster.intersectObjects(mesh.children);

            if (intersects.length > 0) {
                if (intersected?.object !== intersects[0].object) {
                    if (intersected) {
                        setLineColor(new THREE.Color("black"));
                    }
                    intersected = intersects[0];
                    setLineColor(new THREE.Color("aqua"));
                }
            } else {
                if (intersected) {
                    setLineColor(new THREE.Color("black"));
                }
                intersected = null;
            }
        };

        document.addEventListener("mousemove", onPointerMove, false);

        new OrbitControls(this.perspectiveCamera, this.engine.canvas);
    }

    update(): void {
        //
    }
}


