import * as SkeletonUtils from "three/examples/jsm/utils/SkeletonUtils.js";
import * as THREE from "three";
import { Component } from "./component";
import { GameObject } from "./game_object";
import { globals } from "./globals";
import { IMapper, Mapper } from "../../../../api/utils/types";
import { GLTFModel } from "../../../../api/utils/gltf";

export class SkinInstance extends Component {
  model: GLTFModel;
  actions: IMapper<THREE.AnimationAction> = new Mapper<THREE.AnimationAction>();
  mixer: THREE.AnimationMixer;
  animRoot: THREE.Object3D;

  constructor(gameObject: GameObject, model: GLTFModel) {
    super(gameObject);
    this.model = model;
    // @ts-expect-error - bug de typage dans @types/three : SkeletonUtils.clone existe au runtime mais le .d.ts l'enveloppe à tort dans un namespace
    this.animRoot = SkeletonUtils.clone(this.model.gltf!.scene); // eslint-disable-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call
    this.mixer = new THREE.AnimationMixer(this.animRoot);
    gameObject.transform.add(this.animRoot);
  }

  setAnimation(animName: string): void {
    const clip: THREE.AnimationClip = this.model.animations![animName];
    const AnimationActions: THREE.AnimationAction[] = Object.values(this.actions);
    // turn off all current actions
    for (const action of AnimationActions) {
      action.enabled = false;
    }
    // get or create existing action for clip
    const action: THREE.AnimationAction = this.mixer.clipAction(clip);
    action.enabled = true;
    action.reset();
    action.play();
    this.actions[animName] = action;
  }

  update(): void {
    this.mixer.update(globals.deltaTime);
  }
}