import { ISimpleEvent, SimpleEventDispatcher } from 'strongly-typed-events';
import * as THREE from 'three';
import { CustomMouseEvent, MouseManager } from '../../engine/mouse_manager';
import { AScene } from '../../engine/a_scene';
import { MeshRayCaster } from '../mesh_ray_caster';
import { Point } from '../primitives/point';
import { EditMeshMode } from './edit_mesh_mode';
import { IEditMeshItemFactory } from './item/edit_mesh_factory';
import { IEditMeshItem } from './item/i_edit_mesh_item';

export const DEBUG: boolean = false;
export const DEBUG_SHOW_BOUDNING_SPHERE: boolean = false;
export const DEBUG_SHOW_TRACE_POINT: boolean = false;

export class EditMesh {

    private _mesh?: THREE.Mesh;
    public get mesh(): THREE.Mesh | undefined {
        return this._mesh;
    }

    private _meshRayCaster: MeshRayCaster;
    public get meshRayCaster(): MeshRayCaster {
        return this._meshRayCaster;
    }

    private editMeshItemFactory: IEditMeshItemFactory;
    private currentEditMeshItem: IEditMeshItem | undefined;
    public get editMeshMode(): EditMeshMode {
        return this.currentEditMeshItem?.editMeshMode ?? EditMeshMode.none;
    }

    //Events
    public onEditModeChangedDispatcher: SimpleEventDispatcher<EditMeshMode> = new SimpleEventDispatcher<EditMeshMode>();
    public get onEditModeChanged(): ISimpleEvent<EditMeshMode> {
        return this.onEditModeChangedDispatcher.asEvent();
    }

    public onDragMeshElementChangedDispatcher: SimpleEventDispatcher<boolean> = new SimpleEventDispatcher<boolean>();
    public get onDragMeshElementChanged(): ISimpleEvent<boolean> {
        return this.onDragMeshElementChangedDispatcher.asEvent();
    }

    //Debug Helpers
    private boundingSphereMesh?: THREE.Mesh;
    private wireColor: THREE.ColorRepresentation = 0x639BFA;
    private helperWireMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial({ color: this.wireColor, wireframe: true, wireframeLinewidth: 2 });
    //Used to debug mode to add some visual elements
    private _scene?: AScene;
    public set scene(scene: AScene) {
        this._scene = scene;
    }

    constructor(cameraGetter: () => THREE.Camera, editMeshItemFactory: IEditMeshItemFactory) {
        this._meshRayCaster = new MeshRayCaster(cameraGetter, {
            baseColor: 0x639BFA,
            highlightColor: 0xffff00
        });
        this.editMeshItemFactory = editMeshItemFactory;

        MouseManager.instance.mouseDown.subscribe(this.onMouseDownHandler.bind(this));
        MouseManager.instance.mouseMove.subscribe(this.onMouseMoveHandler.bind(this));
        MouseManager.instance.mouseDrag.subscribe(this.onMouseDragHandler.bind(this));
        MouseManager.instance.mouseUp.subscribe(this.onMouseUpHandler.bind(this));
    }

    init(mesh: THREE.Mesh): void {
        this._mesh = mesh;
    }

    enter(editMeshMode: EditMeshMode = EditMeshMode.vertex): void {

        if (!this.mesh) return;
        if (editMeshMode === EditMeshMode.none) return;

        if (this.editMeshMode === EditMeshMode.none) {

            if (DEBUG) {
                // Helpers
                this._scene?.add(this._meshRayCaster.helper);

                if (DEBUG_SHOW_BOUDNING_SPHERE && this.mesh.geometry.boundingSphere) {
                    const boundingSphere = this.mesh.geometry.boundingSphere;
                    const boundingSphereGeometry = new THREE.SphereGeometry(boundingSphere?.radius);
                    this.boundingSphereMesh = new THREE.Mesh(boundingSphereGeometry, this.helperWireMaterial);
                    this.boundingSphereMesh.position.copy(boundingSphere.center);

                    if (this.boundingSphereMesh) {
                        this.mesh.add(this.boundingSphereMesh);
                    }
                }
            }
        }

        this.currentEditMeshItem?.exit();
        this.currentEditMeshItem = this.editMeshItemFactory.getEditMeshItemByMode(editMeshMode, this);
        this.currentEditMeshItem!.enter();

        this.onEditModeChangedDispatcher.dispatch(this.editMeshMode);
    }

    exit(): void {
        if (!this.mesh) return;

        this.currentEditMeshItem?.exit();
        this.currentEditMeshItem = undefined;

        if (DEBUG) {
            this._scene?.remove(this._meshRayCaster.helper);
            if (DEBUG_SHOW_BOUDNING_SPHERE && this.boundingSphereMesh) {
                this.mesh.remove(this.boundingSphereMesh);
                this.boundingSphereMesh = undefined;
            }
        }

        this.onEditModeChangedDispatcher.dispatch(this.editMeshMode);
    }

    toggle(): void {
        if (this.currentEditMeshItem) {
            this.exit();
        } else {
            this.enter();
        }
    }

    private onMouseMoveHandler(e: CustomMouseEvent): void {
        if (!this.currentEditMeshItem) return;
        this.currentEditMeshItem.onMouseMoveHandler(e);
    }

    private onMouseDownHandler(e: CustomMouseEvent): void {
        if (!this.currentEditMeshItem) return;
        this.currentEditMeshItem.onMouseDownHandler(e);
    }

    private onMouseDragHandler(e: CustomMouseEvent): void {
        if (!this.currentEditMeshItem) return;
        this.currentEditMeshItem.onMouseDragHandler(e);
    }

    private onMouseUpHandler(e: CustomMouseEvent): void {
        if (!this.currentEditMeshItem) return;
        this.currentEditMeshItem.onMouseUpHandler(e);
    }

    public addDebugPoint(point: THREE.Vector3, color: THREE.ColorRepresentation = 0x000000): void {
        if (DEBUG && DEBUG_SHOW_TRACE_POINT && this._scene) {
            const debugPoint = new Point({
                color: color
            });
            debugPoint.position.copy(point);
            this._scene.add(debugPoint);
        }
    }

    cleanup(): void {
        this._mesh = undefined;
        this.editMeshItemFactory.cleanup();
    }
}
