import { assert } from "../../../utils/type_check";
import { Vector } from "../linear-algebra/vector";

export class UtilsVector {
    static fromVector3(vector3: THREE.Vector3): Vector {
        return new Vector(vector3.x, vector3.y, vector3.z);
    }

    /**
     * Create an array of Vector from a ArrayLike
     * @param array - ArrayLike : The array to convert
     * @returns Vector[] : The resulting array 
     */
    static vectorsfrom(array: ArrayLike<number>): Vector[] {
        assert(array.length % 3 === 0);

        const result: Vector[] = [];

        for (let i = 0; i < array.length; i += 3) {
            const x = array[i];
            const y = array[i + 1];
            const z = array[i + 2];
            const vector = new Vector(x, y, z);
            result.push(vector);
        }

        return result;
    }
}