import * as THREE from 'three';
import { hasGeometry } from '../utils/geometry';

export class MeshRayCaster {
    private cameraGetter: () => THREE.Camera;

    private raycaster: THREE.Raycaster = new THREE.Raycaster();
    private intersects: THREE.Intersection[] | null = null;

    private plane: THREE.Plane = new THREE.Plane(new THREE.Vector3(0, 1, 0));
    helper: THREE.PlaneHelper = new THREE.PlaneHelper(this.plane, 3, 0xffff00);
    private planeNormal: THREE.Vector3 = new THREE.Vector3();
    private planePoint: THREE.Vector3 = new THREE.Vector3();

    private baseColor: THREE.ColorRepresentation;
    private highlightColor: THREE.ColorRepresentation;

    constructor(cameraGetter: () => THREE.Camera, {
        threshold = 0.04,
        selectionLayer = 1,
        baseColor = 0x000000,
        highlightColor = 0xff0000,
    }: {
        threshold?: number,
        selectionLayer?: number,
        baseColor?: THREE.ColorRepresentation,
        highlightColor?: THREE.ColorRepresentation,
    } = {}) {
        this.cameraGetter = cameraGetter;
        this.baseColor = baseColor;
        this.highlightColor = highlightColor;
        this.raycaster.params.Points = { threshold: threshold };
        this.raycaster.params.Line = { threshold: threshold };
        this.raycaster.layers.set(selectionLayer);
    }

    private setPlane(point: THREE.Vector3): void {
        this.planeNormal.subVectors(this.cameraGetter().position, point).normalize();
        this.plane.setFromNormalAndCoplanarPoint(this.planeNormal, point);
    }

    private setFromCamera(mouseCoordinates: THREE.Vector2): void {
        this.raycaster.setFromCamera(mouseCoordinates, this.cameraGetter());
    }

    private intersectPlane(): THREE.Vector3 {
        this.raycaster.ray.intersectPlane(this.plane, this.planePoint);
        return this.planePoint;
    }

    private hasIntersect(mouseCoordinates: THREE.Vector2, object3D: THREE.Object3D): boolean {
        this.setFromCamera(mouseCoordinates);

        this.intersects = this.raycaster.intersectObject(object3D);
        if (this.intersects.length === 0) {
            return false;
        }

        return true;
    }

    getPlaneIntersection(mouseCoordinates: THREE.Vector2): THREE.Vector3 {
        this.setFromCamera(mouseCoordinates);
        this.raycaster.ray.intersectPlane(this.plane, this.planePoint);
        return this.planePoint;
    }

    //Vertices

    selectVertex(mouseCoordinates: THREE.Vector2, vertices: THREE.Points): THREE.Intersection | undefined {
        this.setFromCamera(mouseCoordinates);

        this.intersects = this.raycaster.intersectObject(vertices, false);
        if (this.intersects.length === 0) {
            return undefined;
        }

        this.setPlane(this.intersects[0].point);

        const result = this.intersects[0];

        return result;
    }

    //Edges

    private previousEdgeIndex: number | undefined;
    selectEdge(mouseCoordinates: THREE.Vector2, edges: THREE.Object3D, useForHighLight: boolean = true): THREE.Intersection | undefined {
        if (!hasGeometry(edges)) return;

        this.setFromCamera(mouseCoordinates);

        this.intersects = this.raycaster.intersectObject(edges, false);
        if (this.intersects.length === 0) {
            if (this.previousEdgeIndex !== undefined && edges.geometry.attributes.colorBase && useForHighLight) {
                this.restoreSegmentColor(edges);
            }
            return undefined;
        }

        const result = this.intersects[0];

        this.setPlane(result.point);

        const index: number | undefined = result.index;
        if (index !== undefined && index !== this.previousEdgeIndex) {
            if (useForHighLight) {
                this.highlightSegment(edges, index, new THREE.Color(this.baseColor), new THREE.Color(this.highlightColor));
            }

            this.previousEdgeIndex = index;
        }

        return result;
    }

    private highlightSegment(edges: THREE.Object3D, index: number, baseColor: THREE.Color, highlightColor: THREE.Color): void {
        this.setSegmentColor(edges, index, baseColor, highlightColor);
        if (this.previousEdgeIndex !== undefined) {
            this.restoreSegmentColor(edges);
        }

    }

    getEdgeNearVertexIndex(index: number): number {
        return index % 2 === 0 ? index + 1 : index - 1;
    }

    private setSegmentColor(edges: THREE.Object3D, index: number, baseColor: THREE.Color, highlightColor: THREE.Color): void {
        if (!hasGeometry(edges)) return;
        const indexNear = this.getEdgeNearVertexIndex(index);

        if (!edges.geometry.attributes.color) {
            const count = edges.geometry.attributes.position.count;
            edges.geometry.setAttribute('color', new THREE.BufferAttribute(new Float32Array(count * 3), 3));
            for (let i = 0; i < count; i++) {
                (edges.geometry.attributes.color as THREE.BufferAttribute).setXYZ(i, baseColor.r, baseColor.g, baseColor.b);
            }
        }

        if (!edges.geometry.attributes.colorBase) {
            const count = edges.geometry.attributes.position.count;
            edges.geometry.setAttribute('colorBase', new THREE.BufferAttribute(new Float32Array(count * 3), 3));
            for (let i = 0; i < count; i++) {
                (edges.geometry.attributes.colorBase as THREE.BufferAttribute).setXYZ(i, baseColor.r, baseColor.g, baseColor.b);
            }
        }

        const colors = edges.geometry.attributes.color;

        colors.setXYZ(index, highlightColor.r, highlightColor.g, highlightColor.b);
        colors.setXYZ(indexNear, highlightColor.r, highlightColor.g, highlightColor.b);
        colors.needsUpdate = true;
    }

    private restoreSegmentColor(edges: THREE.Object3D): void {
        if (this.previousEdgeIndex === undefined) return;
        if (!hasGeometry(edges)) return;

        const oldIndexNear = this.getEdgeNearVertexIndex(this.previousEdgeIndex);

        const colors = edges.geometry.attributes.color as THREE.BufferAttribute;
        const colorBase = edges.geometry.attributes.colorBase as THREE.BufferAttribute;
        colors.copyAt(this.previousEdgeIndex, colorBase, this.previousEdgeIndex);
        colors.copyAt(oldIndexNear, colorBase, oldIndexNear);
        colors.needsUpdate = true;

        this.previousEdgeIndex = undefined;
    }

    //Faces

    prevIndex: number | undefined;
    prevColor: THREE.Color = new THREE.Color();
    materialCount?: number;

    selectColor: THREE.ColorRepresentation = 0xff0000;
    selectMaterial: THREE.MeshBasicMaterial = new THREE.MeshBasicMaterial({ color: this.selectColor, vertexColors: false, wireframe: false, side: THREE.DoubleSide });

    selectFace(normalizedMouseCoordinates: THREE.Vector2, mesh: THREE.Mesh): THREE.Intersection | undefined {
        this.setFromCamera(normalizedMouseCoordinates);

        this.intersects = this.raycaster.intersectObject(mesh);
        if (this.intersects.length == 0) return;

        const result = this.intersects[0];

        this.setPlane(result.point);

        if (result.faceIndex !== this.prevIndex) {
            if ((result.object as THREE.Mesh).isMesh) {
                const mesh = result.object as THREE.Mesh;

                if (Array.isArray(mesh.material) && this.materialCount === undefined) {
                    this.materialCount = mesh.material.length;
                    mesh.material.push(this.selectMaterial);
                }

                const geometry = mesh.geometry;

                //Todo: 
                //- Consider multiple present already present
                //- What if mesh.material is not an Array
                //- Select only single face
                //- Select multiple face with CTRL
                //- Deselect Face
                if (result.faceIndex) {
                    geometry.addGroup(result.faceIndex * 3, 3, 1);
                }
            }
        }

        return result;
    }
}
