import * as THREE from 'three';
import { EditMesh } from '../edit_mesh';
import { EditMeshMode } from "../edit_mesh_mode";
import { MoveMeshTool } from '../meshtool/type/common/move';
import { AEditMeshItem } from "./a_edit_mesh_item";

export class EditMeshVertex extends AEditMeshItem {
    readonly editMeshMode: EditMeshMode = EditMeshMode.vertex;

    get canDrag(): boolean {
        return this.editMesh.editMeshMode === this.editMeshMode
            && this.vertexInfos?.length === 1
            && this.currentIntersection?.index !== undefined;
    }

    private _vertices?: THREE.Points;
    public get vertices(): THREE.Points | undefined {
        return this._vertices;
    }

    private readonly pointColor: THREE.ColorRepresentation = 0x639BFA;
    private readonly overPointColor: THREE.ColorRepresentation = 0xffff00;
    private readonly selectedPointColor: THREE.ColorRepresentation = 0xff0000;

    private pointMaterial: THREE.PointsMaterial = new THREE.PointsMaterial({
        size: 0.05,
        color: this.pointColor
    });

    constructor(editMesh: EditMesh) {
        super(editMesh);

        this.currentMeshTool = new MoveMeshTool(this);
        // this.currentMeshTool = new VertexTraverseMeshTool(this);
    }

    enter(): void {
        this._vertices = new THREE.Points(this.mesh.geometry, this.pointMaterial);
        this._vertices.layers.enable(1); //meshRayCaster is set to layer 1 by default
        this.mesh.add(this._vertices);
    }

    exit(): void {
        if (!this._vertices) return;
        this.mesh.remove(this._vertices);
        this._vertices = undefined;
    }

    overMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this._vertices) return;

        this.vertexInfos = [];

        this.currentIntersection = this.meshRayCaster.selectVertex(normalizedMouseCoordinates, this._vertices);

        if (this.currentIntersection && this.currentIntersection.index !== undefined) {
            this.setVertexInfos(this.currentIntersection.index);
        }
    }

    selectMeshItem(normalizedMouseCoordinates: THREE.Vector2): void {
        if (!this._vertices) return;
        this.currentIntersection = this.meshRayCaster.selectVertex(normalizedMouseCoordinates, this._vertices);
    }

    updateGeometry(): void {
        //
    }
}
