export class UniqueNameCreator {
  private static uniqueName: { [key: string]: number } = {};
  static createUniqueNameFor(name: string): string {
    const count: number | undefined = UniqueNameCreator.uniqueName[name];
    if (count === undefined) {
      UniqueNameCreator.uniqueName[name] = 0;
    } else {
      UniqueNameCreator.uniqueName[name]++;
    }
    return `${name}_${UniqueNameCreator.uniqueName[name]}`;
  }

  static resetAll(): void {
    UniqueNameCreator.uniqueName = {};
  }
}