import * as THREE from "three";
import { MeshData } from "../mesh_data";
import { Modifier } from "./modifier";
import { UtilsArray } from "../../utils/array";
import { Newable } from "../../utils/types";

/*
  An MeshModifier is a mesh container to add modifiers.

  Usage:

    // Create a mesh
    const geometry = new THREE.BoxGeometry(1, 2, 1, 10, 20, 10);
    const mesh = new THREE.Mesh(geometry, this.standardMaterial);
    
    // Create an EditableMesh and adding its mesh to the scene
    this.meshModifier = new MeshModifier(mesh, "edit");
    this.add(this.meshModifier.mesh);
    
    // Add a modifier to the EditableMesh
    const modifier = this.meshModifier.addModifier(Twist);
    modifier.parameters.amount = 90;
    this.meshModifier.update();

*/
export class MeshModifier {

  private _mesh: THREE.Mesh | undefined;
  public get mesh(): THREE.Mesh | undefined {
    return this._mesh;
  }

  get modifiers(): Modifier[] {
    if (!this._mesh) throw "MeshModifier::get modifiers : No mesh available. Did init ?";
    return MeshData.get(this._mesh).modifiers;
  }

  constructor() {
    //
  }

  init(mesh: THREE.Mesh): void {
    this._mesh = mesh;

    const meshData = MeshData.get(mesh);
    if (!meshData.originalGeometry) {
      meshData.originalGeometry = mesh.geometry;//Juste to keep original one
    }

    if (!meshData.modifierUpdater) {
      meshData.modifierUpdater = this.update.bind(this);
    }
  }

  cleanup(): void {
    this._mesh = undefined;
  }


  addModifier<M extends Modifier>(ModifierType: Newable<M>, ...args: any[]): M {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
    const modifier: M = new ModifierType(this, ...args);
    this.modifiers.push(modifier);
    return modifier;
  }

  removeModifier(modifier: Modifier): void {
    UtilsArray.removeArrayElement(this.modifiers, modifier);
  }

  getModifier<C extends Modifier>(ModifierType: Newable<C>): Modifier | undefined {
    return this.modifiers.find((c: Modifier) => c instanceof ModifierType);
  }

  update(): void {
    if (!this.mesh) return;

    const meshData: MeshData = MeshData.get(this.mesh);

    if (meshData.originalGeometry) {
      this.mesh.geometry.dispose();
      this.mesh.geometry = meshData.originalGeometry.clone();// First, cloe the original unmodified
      for (const modifier of this.modifiers) {
        modifier.update();
        this.mesh.geometry = modifier.resultGeometry;
      }
    }
  }
}
