import * as THREE from 'three';
import { Ease } from '../../animation/ease';

export class DynamicLine extends THREE.Line {

    readonly MIN_POINTS: number = 2; // draw the first 2 points, only
    readonly MAX_POINTS: number = 300;
    private drawRange: number = 0;

    maxPoint: number = this.MAX_POINTS;
    material: THREE.LineBasicMaterial = new THREE.LineBasicMaterial({ color: 0xff0000 });

    constructor() {
        super();

        // geometry
        const geometry: THREE.BufferGeometry = new THREE.BufferGeometry();

        // attributes
        const positions: Float32Array = new Float32Array(this.MAX_POINTS * 3); // 3 vertices per point
        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

        // draw range
        geometry.setDrawRange(0, this.MIN_POINTS);

        // line
        this.geometry = geometry;

        this.fillLine();
    }

    private fillLine(): void {
        const positions: THREE.BufferAttribute = this.geometry.attributes.position as THREE.BufferAttribute;

        let x: number, y: number, z: number, index: number;
        x = y = z = index = 0;

        for (let i: number = 0, l: number = this.MAX_POINTS; i < l; i++) {

            positions.setXYZ(index++, x, y, z);

            const factor: number = 0.17;
            x += (Math.random() - 0.5) * factor;
            y += (Math.random() - 0.5) * factor;
            z += (Math.random() - 0.5) * factor;
        }
    }

    update(): void {
        const currentMaxPoint: number = Math.min(this.MAX_POINTS, this.maxPoint);

        this.drawRange = (this.drawRange + 0.2) % currentMaxPoint;
        const ratio: number = Ease.sine(this.drawRange / currentMaxPoint) * currentMaxPoint;

        this.geometry.setDrawRange(0, ratio);

        if (this.drawRange < 1) {
            this.resetLine();
        }
    }

    // generate new data
    private resetLine(): void {
        this.fillLine();
        this.geometry.attributes.position.needsUpdate = true; // required after the first render
        this.material.color.setHSL(Math.random(), 1, 0.5);
    }
}