import { UtilsHtml } from '../../../../api/utils/html';

export class UIControls {

    get element(): HTMLElement {
        return this.ui;
    }

    private readonly ui: HTMLDivElement;
    private readonly left: HTMLDivElement;
    private readonly right: HTMLDivElement;

    constructor() {
        const xmlString: string = `
        <div id="ui">
            <div id="left">
                <img src="/assets/making_game/flutePlayer/ui/left.svg"/>
            </div>
            <div style="flex: 0 0 40px;"> </div>
            <div id="right">
                <img src="/assets/making_game/flutePlayer/ui/right.svg"/>
            </div>
        </div>
        `;
        const doc: Document = new DOMParser().parseFromString(xmlString, "text/xml");

        const ui: HTMLDivElement = doc.getElementById("ui") as HTMLDivElement;
        this.ui = UtilsHtml.convertHtmlFromParser(ui) as HTMLDivElement;

        const left: HTMLDivElement = doc.getElementById("left") as HTMLDivElement;
        this.left = UtilsHtml.convertHtmlFromParser(left) as HTMLDivElement;

        const right: HTMLDivElement = doc.getElementById("right") as HTMLDivElement;
        this.right = UtilsHtml.convertHtmlFromParser(right) as HTMLDivElement;
    }

    show(): void {
        this.ui.style.display = 'block';
    }

    hide(): void {
        this.ui.style.display = 'none';
    }
}
