import { EditMeshMode } from '../edit_mesh_mode';
import { IEditMeshItem } from './i_edit_mesh_item';
import { EditMeshEdge } from './edit_mesh_edge';
import { EditMeshFace } from './edit_mesh_face';
import { EditMeshVertex } from './edit_mesh_vertex';
import { EditMesh } from '../edit_mesh';

export interface IEditMeshItemFactory {
    getEditMeshItemByMode(editMeshMode: EditMeshMode, editMesh: EditMesh): IEditMeshItem | undefined;
    cleanup(): void;
}

class EditMeshItemFactory implements IEditMeshItemFactory {

    private editMeshVertex?: EditMeshVertex;
    private editMeshEdge?: EditMeshEdge;
    private editMeshFace?: EditMeshFace;

    getEditMeshItemByMode(editMeshMode: EditMeshMode, editMesh: EditMesh): IEditMeshItem | undefined {
        let result: IEditMeshItem | undefined;

        switch (editMeshMode) {
            case EditMeshMode.vertex:
                result = this.editMeshVertex ?? (this.editMeshVertex = new EditMeshVertex(editMesh));
                break;
            case EditMeshMode.edge:
                result = this.editMeshEdge ?? (this.editMeshEdge = new EditMeshEdge(editMesh));
                break;
            case EditMeshMode.face:
                result = this.editMeshFace ?? (this.editMeshFace = new EditMeshFace(editMesh));
                break;
            case EditMeshMode.none:
                break;
        }

        return result;
    }

    cleanup(): void {
        this.editMeshVertex = undefined;
        this.editMeshEdge = undefined;
        this.editMeshFace = undefined;
    }
}

//Singleton like
export const editMeshItemFactory: IEditMeshItemFactory = new EditMeshItemFactory();