import { StringBuffer } from "../../../utils/string_buffer";
import { Corner } from "../core/corner";
import { Edge } from "../core/edge";
import { Face } from "../core/face";
import { Geometry } from "../core/geometry";
import { HalfEdge } from "../core/halfEdge";
import { Mesh } from "../core/mesh";
import { Vertex } from "../core/vertex";
import { Vector } from "../linear-algebra/vector";

export class UtilsGeometryProcessingLogger {
    static logData(mesh: Mesh, geometry: Geometry): void {

        const stringBuffer = new StringBuffer();

        UtilsGeometryProcessingLogger.logPositions(geometry.positions, stringBuffer);
        UtilsGeometryProcessingLogger.logVertices(mesh.vertices, stringBuffer);
        UtilsGeometryProcessingLogger.logEdges(mesh.edges, stringBuffer);
        UtilsGeometryProcessingLogger.logHalfEdges(mesh.halfEdges, stringBuffer);
        UtilsGeometryProcessingLogger.logCorners(mesh.corners, stringBuffer);
        UtilsGeometryProcessingLogger.logBoundaries(mesh.boundaries, stringBuffer);

        // Generators
        // Todo ?

        //
        console.log(stringBuffer.toString());
    }

    static logBoundaries(boundaries: Face[], stringBuffer: StringBuffer): void {
        stringBuffer.appendLine("\n> boundariesInfos");
        stringBuffer.appendLine(`> face.index`);
        for (const face of boundaries) {
            UtilsGeometryProcessingLogger.logFace(face, stringBuffer);
        }
    }

    static logCorners(corners: Corner[], stringBuffer: StringBuffer): void {
        stringBuffer.appendLine(`\n> cornersInfos `);
        stringBuffer.appendLine(`> corner.index : corner?.halfEdge?.index`);
        for (const corner of corners) {
            UtilsGeometryProcessingLogger.logCorner(corner, stringBuffer);
        }
    }

    static logHalfEdges(halfEdges: HalfEdge[], stringBuffer: StringBuffer): void {
        stringBuffer.appendLine(`\n> halfEdgesInfos `);
        stringBuffer.appendLine(`> halfEdge.index :halfEdge?.vertex?.index, halfEdge?.next?.vertex?.index`);
        for (const halfEdge of halfEdges) {
            UtilsGeometryProcessingLogger.logHalfEdge(halfEdge, stringBuffer);
        }
    }

    static logEdges(edges: Edge[], stringBuffer: StringBuffer): void {
        stringBuffer.appendLine(`\n> edgesInfos `);
        stringBuffer.appendLine(`> edge.index : halfEdge.vertex.index, halfEdge.twin.vertex.index`);
        for (const edge of edges) {
            UtilsGeometryProcessingLogger.logEdge(edge, stringBuffer);
        }
    }

    static logVertices(vertices: Vertex[], stringBuffer: StringBuffer): void {
        stringBuffer.appendLine("\n> verticesInfos");
        stringBuffer.appendLine(`> vertex.index : vertex.index`);
        for (const vertex of vertices) {
            UtilsGeometryProcessingLogger.logVertex(vertex, stringBuffer);
        }
    }

    static logPositions(positions: { [key: number]: Vector }, stringBuffer: StringBuffer): void {
        stringBuffer.appendLine("\n> positions");
        stringBuffer.appendLine(`> index : position.x, position.y, position.z`);
        for (const index in positions) {
            UtilsGeometryProcessingLogger.logGeometryPosition(positions[index], Number(index), stringBuffer);
        }
    }

    static logGeometryPosition(position: Vector, index: number, stringBuffer: StringBuffer): void {
        stringBuffer.appendLine(`${index}: ${position.x}, ${position.y}, ${position.z}`);
    }

    static logFace(face: Face, stringBuffer: StringBuffer): void {
        const faceIndex = face.index;
        stringBuffer.appendLine(`${faceIndex}`);
    }

    static logCorner(corner: Corner, stringBuffer: StringBuffer): void {
        const cornerIndex = corner.index;
        const cornerHalfEdgeIndex = corner?.halfEdge?.index;
        stringBuffer.appendLine(`${cornerIndex}: ${cornerHalfEdgeIndex !== undefined ? cornerHalfEdgeIndex.toString() : "undefined"}`);
    }

    static logHalfEdge(halfEdge: HalfEdge, stringBuffer: StringBuffer): void {
        const halfEdgeIndex = halfEdge.index;
        const halfEdgeVertexIndex = halfEdge?.vertex?.index;
        const halfEdgeNextVertexIndex = halfEdge?.next?.vertex?.index;
        stringBuffer.appendLine(`${halfEdgeIndex}: ${halfEdgeVertexIndex !== undefined ? halfEdgeVertexIndex.toString() : "undefined"}, ${halfEdgeNextVertexIndex !== undefined ? halfEdgeNextVertexIndex.toString() : "undefined"}`);
    }

    static logEdge(edge: Edge, stringBuffer: StringBuffer): void {
        const edgeIndex = edge.index;
        const edgeHalfEdgeIndex = edge.halfEdge?.vertex?.index;
        const edgeHalfEdgeTwinIndex = edge.halfEdge?.twin?.vertex?.index;
        stringBuffer.appendLine(`${edgeIndex}: ${edgeHalfEdgeIndex !== undefined ? edgeHalfEdgeIndex.toString() : "undefined"}, ${edgeHalfEdgeTwinIndex !== undefined ? edgeHalfEdgeTwinIndex.toString() : "undefined"}`);
    }

    static logVertex(vertex: Vertex, stringBuffer: StringBuffer): void {
        stringBuffer.appendLine(`${vertex.index}: ${vertex.index}`);
    }
}