import * as THREE from 'three';

export interface PointMaterialParameters {
    color?: THREE.ColorRepresentation,
    size?: number,
    position?: [number, number, number]
}

//A single point
export class Point extends THREE.Points {
    constructor({
        position = [0, 0, 0],
        color = 0x000000,
        size = 0.04,
    }: PointMaterialParameters = {}) {
        super();
        this.geometry = this.getSinglePointBufferGeometry();
        this.position.set(position[0], position[1], position[2]);

        this.material = new THREE.PointsMaterial({
            color: color,
            size: size
        });
    }

    withPosition(x: number, y: number, z: number): this {
        this.position.set(x, y, z);
        return this;
    }

    private getSinglePointBufferGeometry(): THREE.BufferGeometry {
        const vertices = new Float32Array([0, 0, 0]);

        const geometry = new THREE.BufferGeometry();
        // itemSize = 3 because there are 3 values (components) per vertex
        geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));

        return geometry;
    }
}
