import { UtilsHtml } from '../../../../api/utils/html';

export class Labels {

    get element(): HTMLElement {
        return this.labels;
    }

    private readonly labels: HTMLDivElement;

    constructor() {
        const htmlString: string = `
        <div id="labels"></div>
        `;

        const doc: Document = new DOMParser().parseFromString(htmlString, "text/xml");
        const labels: HTMLDivElement = doc.getElementById("labels") as HTMLDivElement;
        this.labels = UtilsHtml.convertHtmlFromParser(labels) as HTMLDivElement;
    }

    show(): void {
        this.labels.style.display = 'block';
    }

    hide(): void {
        this.labels.style.display = 'none';
    }

    setVisibility(value: boolean): void {
        this.labels.style.display = value ? "block" : "none";
    }
}
