import { Dispatch } from "react";
import { Action, Reducer } from "redux";
import { SceneType } from "../scenes/scene_factory";

export interface InitialState {
    sceneName: SceneType;
}

export const initialState: InitialState = {
    sceneName: SceneType.Default,
};

export enum ActionType {
    UpdateSceneName,
}

export interface DispatchAction extends Action<ActionType> {
    payload: Partial<InitialState>;
}

export const rootReducer: Reducer<InitialState, DispatchAction> = (state: InitialState | undefined = initialState, action: DispatchAction) => {
    if (action.type === ActionType.UpdateSceneName) {
        return { ...state, sceneName: action.payload.sceneName || SceneType.Default };
    } else return state;
};

export class RootDispatcher {

    private readonly dispatch: Dispatch<DispatchAction>;

    constructor(dispatch: Dispatch<DispatchAction>) {
        this.dispatch = dispatch;
    }

    updateSceneName = (sceneName: SceneType): void => this.dispatch({ type: ActionType.UpdateSceneName, payload: { sceneName } });
}