import { ICustomCreator } from "../creators/custom_mesh_creator";
import { GeometryCreator } from "../creators/geometry_creator";
import { GuiParameters, GUIParamsItemType } from "../../utils/gui";
import { GeometryParameters } from "./primitives";

export const DefaultCylinderGeometryParameters = {
    radiusTop: 1,
    radiusBottom: 1,
    height: 1,
    radialSegments: 8,
    heightSegments: 1,
    openEnded: false,
    thetaStart: 0,
    thetaLength: Math.PI * 2
};

export interface CylinderGeometryParameters extends GeometryParameters {
    radiusTop?: number,
    radiusBottom?: number,
    height?: number,
    radialSegments?: number,
    heightSegments?: number,
    openEnded?: boolean,
    thetaStart?: number,
    thetaLength?: number,
}

export const getCylinderGeometryGUIParameters = (parameters: CylinderGeometryParameters): GuiParameters => {
    const result: GuiParameters = {
        name: 'Cylinder',
        target: parameters,
        controllers: [
            {
                key: 'radiusTop',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'radiusBottom',
                type: GUIParamsItemType.number,
                min: 0.01,
                max: 20,
                step: 0.01
            }, {
                key: 'height',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'radialSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'heightSegments',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'openEnded',
                type: GUIParamsItemType.boolean,
                status: false
            }, {
                key: 'thetaStart',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            }, {
                key: 'thetaLength',
                type: GUIParamsItemType.number,
                min: 1,
                max: 100,
                step: 1
            },
        ],
    };

    return result;
};

export class CylinderGeometryCustomCreator implements ICustomCreator {
    geometryParameters: CylinderGeometryParameters;
    geometryGUIParameters: GuiParameters;

    constructor(parameters: CylinderGeometryParameters = DefaultCylinderGeometryParameters) {
        this.geometryParameters = { ...parameters };
        this.geometryGUIParameters = getCylinderGeometryGUIParameters(this.geometryParameters);
    }

    geometryCreator(parameters: CylinderGeometryParameters): THREE.BufferGeometry {
        const geometry = GeometryCreator.cylinder(parameters);
        parameters.height && geometry.translate(0, parameters.height / 2, 0);
        return geometry;
    }
}