import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { Engine } from './engine';
import { IScene } from '../scene/i_scene';

/**
 * A AScene is a scene with setup for THREE with Default Project Structure.
 * This is used to simplifiy and reuse most usual configuration part.
 */
export abstract class AScene extends THREE.Scene implements IScene {

    private _engine!: Engine;
    get engine(): Engine {
        if (!this._engine) throw new Error("Engine must be set before use. Use AScene::initialize before.");
        return this._engine;
    }

    get canvas(): HTMLCanvasElement {
        return this._engine.canvas;
    }

    private _mainCamera: THREE.Camera = new THREE.Camera();
    get mainCamera(): THREE.Camera {
        return this._mainCamera;
    }
    set mainCamera(camera: THREE.Camera) {
        this._mainCamera = camera;
    }

    private _controls?: OrbitControls;
    get controls(): OrbitControls | undefined {
        return this._controls;
    }
    set controls(controls: OrbitControls | undefined) {
        this._controls = controls;
    }

    private _hasInit: boolean = false;
    get hasInit(): boolean {
        return this._hasInit;
    }

    constructor() {
        super();
    }

    initialize(engine: Engine): void {
        if (!this.hasInit) {
            this._hasInit = true;
            this._engine = engine;
        }
    }

    abstract setup(): void;
    abstract update(): void;

    dispose(): void {
        console.debug("AScene::dispose not implemented");
    }

    hasControl(): this is OrbitControls {
        return this.controls !== undefined;
    }
}

export class DefaultScene extends AScene {

    constructor() {
        super();
    }

    setup(): void {
        //nothing to do here
    }

    update(): void {
        //nothing to do here
    }
}
