type PromiseResolve<T> = (value?: T | PromiseLike<T>) => void;

type PromiseReject = (error?: any) => void;


export class Completer<R = any> {
  readonly promise: Promise<R | undefined>;

  private _isCompleted: boolean = false;
  get isCompleted(): boolean {
    return this._isCompleted;
  }

  private _complete!: (value?: R | PromiseLike<R> | undefined) => void;

  private _reject!: (error?: any, stackTrace?: string) => void;

  constructor() {
    this.promise = new Promise((resolve: PromiseResolve<R>, reject: PromiseReject) => {
      this._complete = resolve;
      this._reject = reject;
    });
  }

  complete(value?: R | PromiseLike<R> | undefined): void {
    this._checkCompleterValidity();
    // this._completeValue = value;
    this._complete(value);
  }


  reject(error?: any, stackTrace?: string): void {
    this._checkCompleterValidity(stackTrace);
    this._reject(error);
  }

  private _checkCompleterValidity(stackTrace?: string): void {
    if (this._isCompleted) {
      throw new Error(`Error : Completer is already completed. ${stackTrace ?? ""}`);
    } else {
      this._isCompleted = true;
    }
  }
}

