import * as THREE from "three";
import { Indexer } from "./types";

interface GeometryGetter<TGeometry extends THREE.BufferGeometry = THREE.BufferGeometry> {
    get geometry(): TGeometry;
}


export function hasGeometry(obj: any): obj is GeometryGetter {
    return 'geometry' in obj;
}

export class GeometryUtils {

    static getTriangleFaces(geometry: THREE.BufferGeometry): THREE.Triangle[] {
        const result: THREE.Triangle[] = [];

        const position: THREE.BufferAttribute | THREE.InterleavedBufferAttribute = geometry.getAttribute('position');

        //Buffer geometries can be indexed or non-indexed. 

        const index: THREE.BufferAttribute | null = geometry.getIndex();

        if (index) {
            //In the first case, you get the triangle indices

            const drawRange = geometry.drawRange;
            const start = Math.max(0, drawRange.start);
            const end = Math.min(index.count, (drawRange.start + drawRange.count));

            for (let i = start, il = end; i < il; i += 3) {

                const a = index.getX(i);
                const b = index.getX(i + 1);
                const c = index.getX(i + 2);

                const triangle = GeometryUtils.getTriangle(position, a, b, c);
                result.push(triangle);
            }
        } else {
            // If the geometry is non - indexed, use the position attribute which holds the actual vertices.

            for (let i = 0; i < position.count; i += 3) {
                const a = i;
                const b = i + 1;
                const c = i + 2;

                const triangle = GeometryUtils.getTriangle(position, a, b, c);
                result.push(triangle);
            }
        }

        return result;
    }


    static getTriangle(position: THREE.BufferAttribute | THREE.InterleavedBufferAttribute, a: number, b: number, c: number): THREE.Triangle {
        const v1: THREE.Vector3 = new THREE.Vector3(position.getX(a), position.getY(a), position.getZ(a));
        const v2: THREE.Vector3 = new THREE.Vector3(position.getX(b), position.getY(b), position.getZ(b));
        const v3: THREE.Vector3 = new THREE.Vector3(position.getX(c), position.getY(c), position.getZ(c));

        return new THREE.Triangle(v1, v2, v3);
    }

    // Author: Fyrestar https://mevedia.com (https://github.com/Fyrestar/THREE.BufferGeometry-toIndexed)
    static toIndexed(baseGeometry: THREE.BufferGeometry): (fullIndex?: boolean, precision?: number) => THREE.BufferGeometry {

        let list: number[] = [];
        let vertices: Indexer<number | undefined> = {};

        let _src: THREE.BufferGeometry | null;
        let attributesKeys: string[];
        let morphKeys: string[];

        let prec: number = 0;
        // let precHalf: number = 0;
        let length: number = 0;

        const floor = (array: number[], offset: number): number => {
            if (array instanceof Float32Array) {
                return Math.floor(array[offset] * prec);
            }
            // else if (array instanceof Float16Array) {
            //     return Math.floor(array[offset] * precHalf);
            // }
            else {
                return array[offset];
            }
        };

        const createAttribute = (src_attribute: THREE.BufferAttribute | THREE.BufferAttribute): THREE.BufferAttribute => {
            // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
            // const k: ArrayLike<number> = new src_attribute.array.constructor(length * src_attribute.itemSize);
            const float32Array: Float32Array = new Float32Array(length * src_attribute.itemSize);
            const dst_attribute = new THREE.BufferAttribute(float32Array, src_attribute.itemSize);

            const dst_array = float32Array;//Array.from(dst_attribute.array);
            const src_array = src_attribute.array;

            switch (src_attribute.itemSize) {
                case 1:
                    for (let i = 0, l = list.length; i < l; i++) {
                        dst_array[i] = src_array[list[i]];
                    }
                    break;
                case 2:
                    for (let i = 0, l = list.length; i < l; i++) {
                        const index = list[i] * 2;
                        const offset = i * 2;

                        dst_array[offset] = src_array[index];
                        dst_array[offset + 1] = src_array[index + 1];
                    }
                    break;
                case 3:
                    for (let i = 0, l = list.length; i < l; i++) {
                        const index = list[i] * 3;
                        const offset = i * 3;

                        dst_array[offset] = src_array[index];
                        dst_array[offset + 1] = src_array[index + 1];
                        dst_array[offset + 2] = src_array[index + 2];
                    }
                    break;
                case 4:
                    for (let i = 0, l = list.length; i < l; i++) {
                        const index = list[i] * 4;
                        const offset = i * 4;

                        dst_array[offset] = src_array[index];
                        dst_array[offset + 1] = src_array[index + 1];
                        dst_array[offset + 2] = src_array[index + 2];
                        dst_array[offset + 3] = src_array[index + 3];
                    }
                    break;
            }
            return dst_attribute;
        };

        const hashAttribute = (attribute: THREE.BufferAttribute, offset: number): string => {
            const array: number[] = Array.from(attribute.array);

            switch (attribute.itemSize) {
                case 1:
                    return `${floor(array, offset)}`;
                case 2:
                    return `${floor(array, offset)}_${floor(array, offset + 1)}`;
                case 3:
                    return `${floor(array, offset)}_${floor(array, offset + 1)}_${floor(array, offset + 2)}`;
                case 4:
                    return `${floor(array, offset)}_${floor(array, offset + 1)}_${floor(array, offset + 2)}_${floor(array, offset + 3)}`;
            }

            return "";
        };

        const store = (index: number, n: number): number => {
            let id: string = '';

            for (let i = 0, l = attributesKeys.length; i < l; i++) {
                const key: string = attributesKeys[i];
                const attribute = _src?.attributes[key] as THREE.BufferAttribute;

                const offset = attribute.itemSize * index * 3 + n * attribute.itemSize;

                id += hashAttribute(attribute, offset) + '_';
            }

            for (let i = 0, l = morphKeys.length; i < l; i++) {
                const key: string = morphKeys[i];
                const attribute: (THREE.BufferAttribute | THREE.InterleavedBufferAttribute)[] | undefined = _src?.morphAttributes[key];

                if (attribute && attribute instanceof THREE.BufferAttribute) {
                    const offset = attribute.itemSize * index * 3 + n * attribute.itemSize;
                    id += hashAttribute(attribute, offset) + '_';
                }
            }

            if (vertices[id] === undefined) {
                vertices[id] = list.length;
                list.push(index * 3 + n);
            }

            return vertices[id] as number;
        };

        const storeFast = (x: number, y: number, z: number, v: number): number => {
            const id: string = `${Math.floor(x * prec)}_${Math.floor(y * prec)}_${Math.floor(z * prec)}`;

            if (vertices[id] === undefined) {
                vertices[id] = list.length;
                list.push(v);
            }

            return vertices[id] as number;
        };

        const indexBufferGeometry = (src: THREE.BufferGeometry, dst: THREE.BufferGeometry, fullIndex: boolean): void => {
            _src = src;
            attributesKeys = Object.keys(src.attributes);
            morphKeys = Object.keys(src.morphAttributes);

            const position = src.attributes.position.array;
            const faceCount = position.length / 3 / 3;

            const typedArray = faceCount * 3 > 65536 ? Uint32Array : Uint16Array;
            const indexArray = new typedArray(faceCount * 3);

            // Full index only connects vertices where all attributes are equal

            if (fullIndex) {
                for (let i = 0, l = faceCount; i < l; i++) {
                    indexArray[i * 3] = store(i, 0);
                    indexArray[i * 3 + 1] = store(i, 1);
                    indexArray[i * 3 + 2] = store(i, 2,);
                }
            } else {
                for (let i = 0, l = faceCount; i < l; i++) {
                    const offset = i * 9;
                    indexArray[i * 3] = storeFast(position[offset], position[offset + 1], position[offset + 2], i * 3);
                    indexArray[i * 3 + 1] = storeFast(position[offset + 3], position[offset + 4], position[offset + 5], i * 3 + 1);
                    indexArray[i * 3 + 2] = storeFast(position[offset + 6], position[offset + 7], position[offset + 8], i * 3 + 2);
                }
            }

            // Index
            dst.index = new THREE.BufferAttribute(indexArray, 1);
            length = list.length;

            // Attributes
            for (let i = 0, l = attributesKeys.length; i < l; i++) {
                const key = attributesKeys[i];
                dst.attributes[key] = createAttribute(src.attributes[key] as THREE.BufferAttribute);
            }

            // Morph Attributes
            for (let i = 0, l = morphKeys.length; i < l; i++) {
                // const key = morphKeys[i];
                // dst.morphAttributes[key] = createAttribute(src.morphAttributes[key] as THREE.BufferAttribute[]);
            }

            if (src.boundingSphere) {
                dst.boundingSphere = src.boundingSphere.clone();
            } else {
                dst.boundingSphere = new THREE.Sphere;
                dst.computeBoundingSphere();
            }

            if (src.boundingBox) {
                dst.boundingBox = src.boundingBox.clone();
            } else {
                dst.boundingBox = new THREE.Box3;
                dst.computeBoundingBox();
            }

            // Groups
            const groups = src.groups;

            for (let i = 0, l = groups.length; i < l; i++) {
                const group = groups[i];
                dst.addGroup(group.start, group.count, group.materialIndex);
            }

            // Release data
            vertices = {};
            list = [];

            _src = null;
            attributesKeys = [];
            morphKeys = [];
        };

        return (fullIndex?: boolean, precision?: number): THREE.BufferGeometry => {

            precision = precision || 6;

            prec = Math.pow(10, precision);
            // precHalf = Math.pow(10, Math.floor(precision / 2));

            const geometry = new THREE.BufferGeometry;

            indexBufferGeometry(baseGeometry, geometry, fullIndex === undefined ? true : fullIndex);

            return geometry;
        };
    }
}

